(window.GIM_TS=window.GIM_TS||{})["Yoma.3"]={"from":72,"a":[["\u0003בסירוגין,\u0004 כלומר: שראשי הפסוקים היו כתובים במילואם והמילים שלאחריהם עד סוף הפסוק היו כתובים בראשי תיבות. ואם כן אין מקום להוכיח מכאן לגבי מגילה לתינוק.","במשנה מוזכר כי \u0003ניקנור נעשו נסים לדלתותיו. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003מה נסים נעשו לדלתותיו? אמרו: כשהלך נקנור להביא דלתות\u0004 נחושת עבור שער המזרח \u0003מאלכסנדריא של מצרים\u0004 שהיתה מפורסמת באומניה, \u0003בחזירתו\u0004 כשהביא את הדלתות באניה \u0003עמד עליו נחשול\u0004 (סערה) \u0003שבים לטבעו, נטלו\u0004 נוסעי הספינה \u0003אחת\u0004 מן הדלתות שהיו כבדות ביותר וחשבו שבשל כובדה הרב תטבע הספינה \u0003והטילוה לים\u0004 כדי להנצל, \u0003ועדיין לא נח הים מזעפו,\u0004","\u0003בקשו להטיל את חברתה\u0004 (הדלת האחרת) \u0003עמד הוא וכרכה\u0004 כלומר חיבקה ונכרך בה, \u0003אמר להם: הטילוני עמה. מיד נח הים מזעפו\u0004 והמשיכו לנסוע עם דלת אחת, \u0003והיה מצטער\u0004 כל הדרך \u0003על חברתה\u0004 שהניח לזרוק. \u0003כיון שהגיע לנמלה של עכו\u0004 שבו ירדו, \u0003היתה\u0004 הדלת \u0003מבצבצת ויוצאה מתחת דופני הספינה\u0004 אף על פי ששל נחושת היתה. \u0003ויש אומרים בריה\u0004 (חיה) \u0003שבים בלעתה, והקיאתה ליבשה.\u0004","\u0003ועליה אמר שלמה: \"קרות בתינו ארזים רהיטנו ברותים\"\u0004 (שיר השירים א, יז), ולמדו חכמים: \u0003אל תיקרי \"ברותים\" אלא \"ברית ים\"\u0004 כלומר: אף הים נראה ככורת ברית עם דלת זו להשיבה למקומה. \u0003לפיכך, כל השערים שהיו במקדש נשתנו\u0004 שמתחילה עשאום ממתכות אחרות ולבסוף כשהעשירו עשאום \u0003של זהב, חוץ משערי ניקנור מפני שנעשו בו נסים. ויש אומרים: מפני שנחושתן מוצהבת\u0004 (בהירה ומשובחת) \u0003היתה. ר' אליעזר בן יעקב אומר: נחשת קלוניתא\u0004 \u0005[מזוקקת]\u0006 \u0003היתה, והיתה מאירה כשל זהב.\u0004","אגב הזכרת אותם אנשים שעשו מעשים במקדש והזכירום לדורות לשבח, מונים את \u0003אלו\u0004 שהיו במקדש והוזכרו \u0003לגנאי;\u0004 האומנים \u0003של בית\u0004 (משפחת) \u0003גרמו לא רצו ללמד על מעשה לחם הפנים\u0004 שהשאירו את סוד עשייתו רק בתוך משפחתם שלהם, וכן \u0003של בית אבטינס לא רצו ללמד על מעשה הקטורת\u0004 כיצד הוא נעשה.","וכן \u0003הוגרס בן לוי היה יודע פרק בשיר\u0004 כאשר יבואר \u0003ולא רצה ללמד\u0004 לאחרים, והלבלר \u0003בן קמצר לא רצה ללמד על מעשה הכתב\u0004 שהיה בקי בכתיבת שם בן ארבע אותיות בארבע אצבעותיו בשעה אחת. \u0003על הראשונים\u0004 שהוזכרו לשבח \u0003נאמר: \"זכר צדיק לברכה\"\u0004 (משלי י, ז) \u0003ועל אלו\u0004 שדאגו רק לעצמם \u0003נאמר: \"ושם רשעים ירקב\"\u0004 (משלי י, ז).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003בית גרמו היו בקיאין במעשה לחם הפנים ולא רצו ללמד\u0004 לאחרים את סוד עשייתו. פיטרום, ו\u0003שלחו חכמים והביאו אומנין מאלכסנדריא של מצרים\u0004 שהיתה עיר גדולה ובה מומחים רבים. \u0003והיו יודעין\u0004 אותן אומנים \u0003לאפות כמותן\u0004 כבית גרמו \u0003ולא ידעו לרדות\u0004 את הלחם \u0003כמותן\u0004 כי ללחם הפנים היתה צורה מורכבת מאד, וחששו להכניסו לתוך התנור ולהוציאו משם, שלא ישבר. \u0003שהללו\u0004 בני אלכסנדריא היו \u0003מסיקין\u0004 את האש בתנור \u0003מבחוץ ואופין מבחוץ, והללו\u0004 בני בית גרמו היו \u0003מסיקין מבפנים ואופין מבפנים. הללו\u0004 מאלכסנדריא היתה \u0003פיתן\u0004 של לחם הפנים \u0003מתעפשת\u0004 במשך השבוע, \u0003והללו\u0004 בית גרמו \u0003אין פיתן מתעפשת.\u0004","\u0003כששמעו חכמים בדבר\u0004 שפת זו שעושין האומנים כעת איננה משובחת כפי שהיתה, \u0003אמרו: כל מה שברא הקדוש ברוך הוא — לכבודו בראו, שנאמר: \"כל הנקרא בשמי ולכבודי בראתיו\"\u0004 (ישעיה מג, ז) וכיון שהוא כבוד שמים, ראוי לחכמים למחול על כבודם. \u0003וחזרו בית גרמו למקומן. שלחו להם חכמים\u0004 שיחזרו לעבודתן — \u0003ולא באו. כפלו להם שכרן ובאו. בכל יום\u0004 עד אז \u0003היו נוטלין\u0004 שכרם \u0003שנים עשר מנה, והיום\u0004 והלאה \u0003עשרים וארבעה\u0004 מנה היה שכרם. \u0003ר' יהודה אומר: בכל יום עשרים וארבעה\u0004 מנה נטלו, \u0003והיום ארבעים ושמונה.\u0004","\u0003אמרו להם חכמים: מה ראיתם שלא ללמד\u0004 לאחרים מלאכה זו? \u0003אמרו להם: יודעין היו של בית אבא שבית זה\u0004 (המקדש) \u0003עתיד ליחרב,\u0004 ו\u0003שמא ילמוד אדם שאינו מהוגן\u0004 עבודת אפיה שבידינו \u0003וילך ויעבוד עבודה זרה בכך\u0004 במעשה משובח זה, ולכן לא רצו ללמד אלא בתוך משפחתם. ומעירים, ועל כל פנים \u0003ועל דבר זה מזכירין אותן לשבח\u0004 כי \u0003מעולם לא נמצאת פת נקיה\u0004 של סולת \u0003ביד בניהם, שלא יאמרו\u0004 הבריות \u0003ממעשה לחם הפנים זה\u0004 הם \u0003ניזונין,\u0004 אלא היו אוכלים רק פת קיבר, המעורבת בסובין, \u0003לקיים מה שנאמר: \"והייתם נקים מה' ומישראל\"\u0004 (במדבר לב, כב). שראוי שלא רק שיהיו מעשי האדם נקיים באמת, אלא מוטל עליו אף לדאוג שהדבר ייראה ולא יבואו לחושדו.","כיוצא בזה שנינו במשנה: \u0003של בית אבטינס לא רצו ללמד על מעשה הקטורת\u0004 שהיו בקיאים בעשייתה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003בית אבטינס היו בקיאין במעשה הקטורת ולא רצו ללמד\u0004 לאחרים, פיטרום ולאחר מכן \u0003שלחו חכמים והביאו אומנין מאלכסנדריא של מצרים. והיו יודעין\u0004 אומני אלכסנדריא \u0003לפטם\u0004 (לערב) סממני קטורת \u0003כמותם ולא היו יודעין להעלות עשן כמותן. של הללו,\u0004 של בית אבטינס, היה העשן \u0003מתמר ועולה כמקל, של הללו\u0004 של אלכסנדריא היה \u0003מפציע\u0004 (מתפצל) \u0003לכאן ולכאן\u0004 ולא עלה יפה.","\u0003וכששמעו חכמים בדבר\u0004 שעכשיו אין מעשהו יפה כמקודם, \u0003אמרו: כל מה שברא הקדוש ברוך הוא לכבודו בראו, שנאמר: \"כל פעל ה' למענהו\"\u0004 (משלי טז, ד) \u0003וחזרו בית אבטינס למקומן\u0004 (לביתם). \u0003שלחו להם חכמים\u0004 לבית אבטינס שיחזרו \u0003ולא באו, כפלו להם שכרן ובאו. בכל יום היו נוטלין שנים עשר מנה והיום עשרים וארבעה. ר' יהודה אומר: בכל יום\u0004 היו נטלים בשכרם \u0003עשרים וארבעה\u0004 מנה \u0003והיום ארבעים ושמונה.\u0004","\u0003אמרו להם חכמים: מה ראיתם שלא ללמד? אמרו: יודעין היו של בית אבא שבית זה עתיד ליחרב\u0004 לבסוף, \u0003אמרו: שמא ילמוד אדם שאינו מהוגן וילך ויעבוד עבודה זרה בכך.\u0004 ומכל מקום \u0003ועל דבר זה מזכירין אותן לשבח — מעולם לא יצאת כלה מבושמת\u0004 בבשמים \u0003מבתיהן,\u0004 וגם \u0003וכשנושאין אשה ממקום אחר\u0004 ממשפחה אחרת \u0003מתנין עמה שלא תתבסם, שלא יאמרו\u0004 המעליזים: \u0003ממעשי הקטורת מתבסמין, לקיים מה שנאמר: \"והייתם נקים מה' ומישראל\"\u0004 (במדבר לב, כ).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' ישמעאל: פעם אחת הייתי מהלך בדרך ומצאתי אחד מבני בניהם\u0004 של משפחת אבטינס, \u0003אמרתי לו: אבותיך בקשו להרבות כבודן ורצו למעט כבוד המקום\u0004 שלא גילו הסוד לאחרים, \u0003עכשיו כבוד מקום במקומו\u0004 אף שחרב הבית, \u0003ומיעט כבודם\u0004 של בני משפחתך, שלא היה כבודן אלא מתוך היותם עובדים בבית המקדש.","\u0003אמר ר' עקיבא: פעם אחת סח לי ר' ישמעאל בן לוגא: פעם אחת יצאתי אני ואחד מבני בניהם\u0004 של בית אבטינס \u0003לשדה ללקט עשבים, וראיתי ששחק ובכה. אמרתי לו: מפני מה בכית? אמר לי: כבוד אבותי נזכרתי\u0004 כמה היו חשובין במקדש. אמרתי לו \u0003ומפני מה שחקת? אמר לי: שעתיד הקדוש ברוך הוא להחזירה לנו,\u0004 ושוב נהיה בכבודנו. אמרתי לו: \u0003ומפני מה נזכרת\u0004 עכשיו בדבר זה? \u0003אמר לי: מעלה עשן כנגדי,\u0004 שהעשב הקרוי \"מעלה עשן\" מצוי כאן כנגדי, ובשלו נזכרתי. אמרתי לו: \u0003הראהו לי,\u0004 איזהו? \u0003אמר לי: שבועה היא בידינו שאין מראין אותו לכל אדם\u0004 אלא לבני משפחה בלבד.","\u0003אמר ר' יוחנן בן נורי: פעם אחת מצאתי זקן אחד ומגילת סממנין בידו\u0004 שכתוב בה סדר פיטומן ומהיכן הם נלקחים. \u0003אמרתי לו: מאין אתה?\u0004 מהו יחוסך? \u0003אמר לי: מבית אבטינס אני.\u0004 ושאלתיו: \u0003ומה בידך? אמר לי: מגילת סממנין.\u0004 בקשתי ממנו: \u0003הראהו לי! אמר לי: כל זמן שבית אבא היו קיימין\u0004 באמונתם הראשונה \u0003לא היו מוסרין אותו לכל אדם, ועכשיו הרי הוא לך, והזהר בה\u0004 שלא תמסרנה לכל אדם. \u0003וכשבאתי וסחתי דברי לפני ר' עקיבא אמר לי: מעתה\u0004 כיון שמסרו את המגילה לראויים לכך לאחר שהם אינם מסוגלים עוד לשמור עליה בקדושה \u0003אסור לספר בגנותן של אלו,\u0004 שנראה שאף מתחילה לשם שמים נתכוונו.","\u0003מכאן\u0004 בשל המעשים על אומני המקדש שהוצרכו להחזירם לעבודתם \u0003אמר בן עזאי:\u0004 אל ידאג אדם שמא יקפחו אחרים את פרנסתו והצלחתו, כי בעת הראויה לכך \u0003בשמך יקראוך\u0004 להחזירך למלאכתך, \u0003ובמקומך יושיבוך,\u0004"],["\u0003ומשלך יתנו לך,\u0004 שלכל אדם חלק המוכן לו משמים, ומשלו הוא זוכה, כפי שרואים שאירע לבית אבטינס. וכלל הוא ש\u0003אין אדם נוגע במוכן\u0004 מן השמים \u0003לחבירו\u0004 וכל אדם מקבל מן החלק המוכן לו. \u0003ואין מלכות נוגעת בחברתה אפילו כמלא נימא\u0004 (שערה) וכשמגיע זמנה של מלכות אחת ליפול, מיד מקבלת המלכות החדשה את ההנהגה ואין אחת מהן נוהגת מלכות בזמן השייך לחבירתה.","שנינו במשנה כי \u0003הוגרס בן לוי\u0004 היה יודע פרק בשיר ולא רצה ללמד. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כשהוא\u0004 הוגרס בן לוי היה \u0003נותן קולו בנעימה\u0004 היה \u0003מכניס גודלו לתוך פיו, ומניח אצבעו בין הנימין\u0004 שבגרונו. והיה משמיע קול אדיר כל כך \u0003עד שהיו אחיו הכהנים נזקרים\u0004 (נזרקים ונרתעים) \u0003בבת ראש\u0004 (בבת אחת) \u0003לאחוריהם.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בן קמצר לא רצה ללמד על מעשה הכתב,\u0004 ומה היה עניינו? \u0003אמרו עליו שהיה נוטל ארבעה קולמוסין\u0004 (עטים) \u0003בין אצבעותיו, ואם היתה תיבה של ארבע אותיות היה כותבה בבת אחת. אמרו לו: מה ראית שלא ללמד? כולן מצאו תשובה לדבריהם,\u0004 שטענו שלא רצו שיבוא סוד מלאכתם בסופו של דבר לידי שבח עבודה זרה, אולם \u0003בן קמצר לא מצא תשובה לדבריו\u0004 והיה ברור שרק מפני שמירת כבודו נמנע מללמד. \u0003על הראשונים נאמר: \"זכר צדיק לברכה\"\u0004 (משלי י, ז) \u0003ועל בן קמצר וחביריו נאמר: \"ושם רשעים ירקב\"\u0004 (משלי י, ז).","אגב הזכרת הפסוק שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ושם רשעים ירקב\",\u0004 מה משמעו של ריקבון בשם? \u0003אמר ר' אלעזר:\u0004 כוונתו \u0003רקביבות תעלה בשמותן,\u0004 ופירושו: \u0003דלא מסקינן בשמייהו\u0004 \u0005[שאין אנו\u0006 קוראים לאחרים \u0005בשמותיהם]\u0006 ולכן השם נשכח במשך הדורות. \u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבינא,\u0004 מן המעשה המסופר על ימי חורבן הבית. \u0003מעשה\u0004 בנער אחד שהיה נקרא \u0003דואג בן יוסף, שהניחו אביו\u0004 ומת, והיה \u0003בן קטן לאמו\u0004 והיתה אוהבתו ביותר \u0003בכל יום היתה אמו מודדתו בטפחים\u0004 כמה גדל \u0003ונותנת משקלו,\u0004 שנוסף, \u0003של זהב לבית המקדש.\u0004 ולבסוף \u0003כשגבר אויב\u0004 והיה הרעב הנורא בעיר \u0003טבחתו ואכלתו.\u0004","\u0003ועליה\u0004 וכיוצא בה \u0003קונן ירמיה: \"אם תאכלנה נשים פרים עללי טפחים\"\u0004 (איכה ב, כ), שאף עולל כזה שנמדד טפחים טפחים (\"טיפוחים\") אף הוא נאכל על ידי אמו. \u0003משיבה רוח הקדש\u0004 להם \u0003ואומרת:\u0004 מדוע אירע להם כך — \u0003\"אם יהרג במקדש ה' כהן ונביא\"\u0004 (איכה ב, כ), על שנהרג זכריה בן יהוידע הכהן. ולפי דרכנו למדנו שהיה ילד שנקרא בשם דואג, ואף שהוא שמו של אדם רשע, ונמצא שקוראים בשמו של רשע! ומשיבים: \u0003חזי מאי סליק ביה\u0004 \u0005[ראה מה עלתה בגורלו]\u0006 של אותו ילד, שמה שאירע לו לילד זה אף הוא סימן רע.","\u0003אמר ר' אלעזר: צדיק מעצמו\u0004 (על ידי מעשיו), משבחים אותו בכל עת, \u0003ורשע\u0004 מקללים אותו לא רק על ידי עצמו אלא גם \u0003מחבירו. צדיק מעצמו\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זכר צדיק לברכה\"\u0004 (משלי י, ז) בלשון יחיד. \u0003ורשע מחבירו\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושם רשעים ירקב\"\u0004 (משלי י, ז) בלשון רבים, שכיון שמזכירים רשע אחד, מקללים את כל הרשעים חבריו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לההוא מרבנן דהוה מסדר אגדתא קמיה\u0004 \u0005[לאחד החכמים שהיה מסדר\u0006 דברי \u0005אגדה לפניו]:\u0006 \u0003מנא הא מילתא דאמור רבנן\u0004 \u0005[מנין דבר זה שאמרו חכמים]\u0006 על כמה אנשים \u0003\"זכר צדיק לברכה\"? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דהא כתיב\u0004 \u0005[הרי נאמר]\u0006 מפורש בכתובים: \u0003\"זכר צדיק לברכה\"!\u0004 חזר ושאלו: \u0003מדאורייתא מנא לן\u0004 \u0005[מדברי התורה,\u0006 ולא מן הכתובים, \u0005מנין לנו]\u0006 שכן הוא? אמר לו: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וה' אמר המכסה אני מאברהם אשר אני עשה\"\u0004 (בראשית יח, יז) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אגב הזכרת שמו של אברהם, ובלא קשר לענין: \u0003\"ואברהם היו יהיה לגוי גדול ועצום\"\u0004 (בראשית יח, יח), משמע: מיד שמזכירים שמו של צדיק ראוי לומר דברי שבח עליו, והוא המקור למנהג חכמים.","שוב שאל: \u0003מנא הא מילתא\u0004 \u0005[מנין דבר זה]\u0006 \u0003דאמור רבנן\u0004 \u0005[שאומרים חכמים]\u0006 \u0003\"ושם רשעים ירקב\"? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דהא כתיב\u0004 \u0005[שהרי נאמר]:\u0006 \u0003\"ושם רשעים ירקב\".\u0004 שאלו: אולם \u0003מדאורייתא מנא לן\u0004 \u0005[מן התורה מנין לנו]?\u0006 אמר לו: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בלוט: \u0003\"ויאהל עד סדום\"\u0004 (בראשית יג, יב), וכיון שהוזכרה סדום נאמר מיד: \u0003\"ואנשי סדם רעים וחטאים לה' מאד\"\u0004 (בראשית יג, יג).","אגב הזכרתם של אלה מביאים מאמר נוסף ש\u0003אמר ר' אלעזר: צדיק\u0004 היה ש\u0003דר בין שני רשעים ולא למד ממעשיהם, רשע\u0004 היה ש\u0003דר בין שני צדיקים ולא למד ממעשיהם.\u0004 כיצד? \u0003צדיק\u0004 ש\u0003דר בין שני רשעים ולא למד ממעשיהם —\u0004 זה \u0003עובדיה\u0004 שהיה שר אצל אחאב ואיזבל ונשאר ירא ה' מאד (מלכים א' פרק יח). \u0003רשע\u0004 ש\u0003דר בין שני צדיקים ולא למד ממעשיהם — זה עשו\u0004 שנולד וגדל אצל יצחק ורבקה ואף על פי כן נותר ברשעותו.","עוד \u0003אמר ר' אלעזר: מברכתן של צדיקים אתה למד\u0004 אגב כך \u0003קללה לרשעים,\u0004 ולהיפך \u0003ומקללתן של רשעים אתה למד ברכה לצדיקים.\u0004 כיצד? \u0003מברכתן של צדיקים אתה למד קללה לרשעים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי ידעתיו למען אשר יצוה\u0004 את בניו ואת ביתו אחריו\u0003\"\u0004 (בראשית יח, יט) \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"זעקת סדם ועמרה כי רבה\"\u0004 (בראשית יח, כ), שכיון שהוזכר הצדיק, ממילא הובלט יותר רשעם של הרשעים ועל כן גם גדל ענשם. ולהיפך: \u0003ומקללתן\u0004","\u0003של רשעים אתה למד ברכה לצדיקים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואנשי סדם רעים וחטאים לה'\u0004 מאד\u0003\"\u0004 (בראשית יג, יג) ואחר כך נאמר: \u0003\"וה' אמר אל אברם אחרי הפרד לוט מעמו\"\u0004 (בראשית יג, יד), שברכו. \u0003ואמר ר' אלעזר: אפילו בשביל צדיק אחד עולם\u0004 שלם \u0003נברא, שנאמר: \"וירא אלהים את האור כי טוב\"\u0004 (בראשית א, ד) — \u0003ואין טוב אלא צדיק, שנאמר: \"אמרו צדיק כי טוב\"\u0004 (ישעיה ג, י).","ועוד מה ש\u0003אמר ר' אלעזר: כל המשכח דבר מתלמודו\u0004 — סופו ש\u0003גורם גלות לבניו, שנאמר: \"ותשכח תורת אלהיך אשכח בניך גם אני\"\u0004 (הושע ד, ו). \u0003ר' אבהו אמר:\u0004 המשכח תלמודו — \u0003מורידין אותו מגדולתו, שנאמר: \"כי אתה הדעת מאסת ואמאסך מכהן לי\"\u0004 (הושע ד, ו).","ועוד בענין הצדיקים, \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: אין צדיק נפטר מן העולם עד שנברא צדיק כמותו, שנאמר: \"וזרח השמש ובא השמש\"\u0004 (קהלת א, ה), כלומר: עוד טרם בואה שבאה (שקיעתה) של השמש, כבר זורחת שמש חדשה. כגון: \u0003עד שלא כבתה שמשו של עלי, כבר זרחה שמשו של שמואל הרמתי,\u0004 וכן הלאה בכל הדורות. \u0003ואמר ר' חייא אמר ר' יוחנן: ראה הקדוש ברוך הוא שצדיקים מועטין\u0004 הן, \u0003עמד ושתלן\u0004 (קבען ופזרן) \u0003בכל דור ודור,\u0004 כדי שיהיה בכל דור לפחות צדיק אחד, \u0003שנאמר: \"כי לה' מצקי ארץ וישת עליהם תבל\"\u0004 (שמואל א' ב, ח) כי מאחר שעל הצדיקים עומד העולם (\"ישת עליהם תבל\") צריך שיהיה בכל דור צדיק שהעולם עומד עליו.","\u0003ואמר ר' חייא בר אבא אמר ר' יוחנן: אפילו בשביל צדיק אחד העולם מתקיים, שנאמר: \"וצדיק יסוד עולם\"\u0004 (משלי י, כה). \u0003ר' חייא דידיה\u0004 \u0005[משלו]\u0006 ולא מדברי ר' יוחנן \u0003אמר: מהכא\u0004 \u0005[מכאן\u0006 הראיה\u0005]\u0006 שנאמר: \u0003\"רגלי חסידיו ישמר\"\u0004 (שמואל א' ב, ט), והכוונה כי לרגלי (בגלל) חסידיו — ישמור. ותוהים: מה ראיה היא מכאן הלא \u0003חסידיו טובא משמע\u0004 \u0005[רבים במשמע],\u0006 ולא רק חסיד אחד בלבד! \u0003אמר רב נחמן בר יצחק: חסידו כתיב\u0004 \u0005[כתוב],\u0006 ולומדים מהכתיב שה' שומר אפילו רגלי חסידו האחד.","\u0003ואמר ר' חייא בר אבא אמר ר' יוחנן: כיון שיצאו רוב שנותיו של אדם ולא חטא — שוב אינו חוטא, שנאמר: \"רגלי חסידיו ישמר\"\u0004 (שמואל א' ב, ט). שאם זכה אדם להיות בגדר חסיד — ה' שומר אותו מכאן והלאה שלא יכשל. \u0003דבי\u0004 \u0005[\u0006בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא אמרי\u0004 \u0005[\u0006היו \u0005אומרים]:\u0006 \u0003כיון שבאה לידו\u0004 של אדם \u0003דבר עבירה פעם ראשונה ושניה, ואינו חוטא — שוב אינו חוטא, שנאמר: \"רגלי חסידיו ישמר\",\u0004 שמאחר וכבר נשמר מן העבירה כמה פעמים, הריהו נחשב כחסיד ומכן והלאה ישמרהו ה' (שמואל א' ב, ט).","\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אם ללצים הוא יליץ ולענוים יתן חן\"\u0004 (משלי ג, לד) — כוונתו: \u0003בא\u0004 אדם \u0003לטמא\u0004 (\"ללצים\") — \u0003פותחין לו\u0004 פתח (אפשרות) שיוכל לעשות כרצונו, שהרי יש בחירה חופשית. ואם \u0003בא לטהר\u0004 (\"לענוים\") — אף \u0003מסייעין אותו. תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 על כתוב זה — \u0003משל לאדם שהיה מוכר\u0004 גם \u0003נפט\u0004 גולמי שריחו רע וגם \u0003אפרסמון\u0004 שריחו ערב ביותר,"],["\u0003בא\u0004 אדם לקנות ו\u0003למדוד נפט, אומר לו\u0004 המוכר: \u0003מדוד אתה לעצמך,\u0004 שאין אני רוצה להתלכלך בו. \u0003בא\u0004 הלוקח \u0003למדוד אפרסמון, אומר לו\u0004 המוכר: \u0003המתן לי עד שאמדוד עמך, כדי שנתבסם אני ואתה.\u0004 כך בעבירות, ה' רק פותח פתח, ובמצוות הוא מסייע ממש בדבר.","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: עבירה מטמטמת\u0004 (מטפשת) \u0003לבו של אדם\u0004 העובר אותה, \u0003שנאמר: \"ולא תטמאו בהם ונטמתם בם\"\u0004 (ויקרא יא, מג) \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"ונטמאתם\" אלא\u0004 קרא: \u0003\"ונטמטם\"\u0004 — שלבכם נעשה מטומטם — סתום ואטום.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"ולא תטמאו בהם ונטמתם בם\"\u0004 (ויקרא יא, מג), וכך שיעורו של הכתוב \u0003אדם מטמא\u0004 את \u0003עצמו מעט\u0004 (\"תיטמאו בהם\") \u0003מטמאין אותו הרבה\u0004 (\"ונטמתם בם\"). ואם אדם מטמא עצמו \u0003מלמטה\u0004 מרצונו שלו — \u0003מטמאין אותו\u0004 יותר \u0003מלמעלה.\u0004 ואם מטמא עצמו \u0003בעולם הזה — מטמאין אותו לעולם הבא.\u0004 וכנגד זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הכתוב: \u0003\"והתקדשתם והייתם קדשים\"\u0004 (ויקרא יא, מד) — \u0003אדם מקדש עצמו מעט — מקדשין אותו\u0004 ומסייעין לו \u0003הרבה,\u0004 מקדש עצמו \u0003מלמטה — מקדשין אותו מלמעלה,\u0004 מקדש עצמו \u0003בעולם הזה — מקדשין אותו לעולם הבא.\u0004","","","\u0003טרף\u0004 (ערבב את הגורלות. ר\"ח) \u0003בקלפי\u0004 (תיבה של גורל), \u0003והעלה\u0004 משם \u0003שני גורלות, אחד כתוב עליו \"לשם\" ואחד כתוב עליו \"לעזאזל\". הסגן\u0004 היה עומד \u0003בימינו\u0004 של כהן גדול, \u0003וראש בית אב משמאלו. אם\u0004 גורל \u0003של שם עלה בימינו\u0004 של הכהן הגדול — \u0003הסגן אומר לו: אישי כהן גדול, הגבה ימינך\u0004 והנח את הגורל על השעיר שלימינך. \u0003ואם של שם עלה בשמאלו — ראש בית אב אומר לו: אישי כהן גדול, הגבה שמאלך\u0004 והנח את הגורל על השעיר שלשמאלך.","לאחר מכן \u0003נתנן\u0004 את הגורלות \u0003על שני השעירים, ואומר: \"לה' חטאת\". ר' ישמעאל אומר: לא היה צריך לומר\u0004 את המילה \u0003\"חטאת\" אלא\u0004 אומר \u0003\"לה\"\u0004 בלבד. \u0003והן,\u0004 הכהנים והעם כששומעין את הזכרת השם, \u0003עונין\u0004 ואומרים \u0003אחריו: \"ברוך שם כבוד מלכותו לעולם ועד\".\u0004","על דברי המשנה שואלים: \u0003למה לי טרף בקלפי?\u0004 מדוע לא היה לוקח משם בלא ערבוב? ומשיבים: \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ניכוין ולישקול\u0004 \u0005[יתכוין ויקח]\u0006 באופן שיעלה גורל \"לה'\" בצד ימינו דווקא, שהדבר נחשב לסימן טוב כשעולה בימין.","\u0003אמר רבא: קלפי\u0004 זו \u0003של עץ היתה, ושל חול היתה,\u0004 כלומר שלא קדשוה בקדושת כלי שרת, \u0003ואינה מחזקת אלא\u0004 שיעור \u0003שתי ידים\u0004 ולא יותר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: בשלמא\u0004 \u0005[נניח]\u0006 מה שאמרנו \u0003שאינה מחזקת אלא שתי ידים,\u0004 יש טעם לדבר — \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ליכוין ולישקול\u0004 \u0005[יתכוין ויקח]\u0006 גורל של שם ביד ימין דווקא, על ידי שיהיה לו מקום רחב דיו כדי למשמש את שני הגורלות ולזהותם. \u0003אלא\u0004 משום מה היתה תיבת הגורל מ\u0003של חול? נקדשה\u0004 \u0005[שיקדשו]\u0006 אותה כשאר כלי שרת! ומשיבים: \u0003אם כן הוה לה\u0004 \u0005[הרי יהיה]\u0006 לנו \u0003כלי שרת של עץ, וכלי שרת\u0004 של עץ \u0003לא עבדינן\u0004 \u0005[אין אנו עושים]\u0006 על פי דין התורה. ושואלים: אם כן \u0003ונעבדה\u0004 \u0005[ונעשנה]\u0006 את הקלפי משל \u0003כסף!\u0004 או: \u0003ונעבדה\u0004 \u0005[ונעשנה]\u0006 משל \u0003זהב!\u0004 ומשיבים: \u0003התורה חסה על ממונן של ישראל\u0004 ואין להוציא ממון מרובה כאשר אין הדבר נחוץ לעבודת המקדש.","ומעירים: \u0003מתניתין דלא כי האי תנא דתניא\u0004 \u0005[משנתנו שלא\u0006 כשיטתו של \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה אומר משום ר' אליעזר: הסגן וכהן גדול\u0004 היו \u0003מכניסין ידן בקלפי, אם בימינו של כהן גדול עולה\u0004 הגורל לה' \u0003הסגן אומר לו: אישי כהן גדול הגבה ימינך. ואם בימינו של סגן עולה\u0004 הגורל לה' \u0003ראש בית אב אומר לו לכהן גדול: דבר מילך\u0004 \u0005[אמור דבריך].\u0006","ושואלים: \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]\u0006 לכהן הגדול ה\u0003סגן,\u0004 שמעלתו גדולה משל ראש בית אב? ומשיבים: \u0003כיון\u0004 ש\u0003לא סליק בידיה חלשא דעתיה\u0004 \u0005[עלה הגורל\u0006 לה' \u0005בידו\u0006 של הכהן הגדול \u0005חלשה דעתו]\u0006 ואם עוד יאמר לו הסגן את הדברים יראה לו כאילו מלגלג עליו.","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה\u0006 באיזה עקרון \u0005נחלקו]\u0006 תנאים אלה? ומסבירים: \u0003מר\u0004 \u0005[\u0006חכם \u0005זה]\u0006 של הברייתא \u0003סבר: ימינא\u0004 \u0005[ימינו]\u0006 של ה\u0003סגן עדיף\u0004 \u0005[עדיפה]\u0006 \u0003משמאליה\u0004 \u0005[משמאלו]\u0006 של ה\u0003כהן גדול\u0004 ולכן מוטב שיכניסו שניהם את ידם הימנית. \u0003ומר\u0004 \u0005[וחכם זה]\u0006 במשנתנו \u0003סבר: כי הדדי נינהו\u0004 \u0005[הרי הם זה כזה]\u0006 ואיו להעדיף זה על זה, ולמעשה מוטב שייעשה הכל בידו של הכהן הגדול.","ושואלים: \u0003ומאן האי תנא דפליג עליה\u0004 \u0005[ומיהו התנא הזה\u0006 של משנתנו \u0005שחולק עליו]\u0006 על \u0003ר' יהודה?\u0004 ומשיבים: \u0003רבי חנינא סגן הכהנים הוא, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' חנינא סגן הכהנים אומר: למה\u0004 היה ה\u0003סגן\u0004 נמצא במשך כל יום הכיפורים \u0003מימינו\u0004 של הכהן הגדול \u0003— שאם אירע בו פסול בכהן גדול, נכנס סגן ומשמש תחתיו.\u0004 ומכאן למדים שקודם לכן אין לסגן תפקיד מסויים שעליו לעשות במקדש, ושלא כר' יהודה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 כל אותם \u0003ארבעים שנה ששמש שמעון הצדיק\u0004 ככהן גדול \u0003היה הגורל\u0004 לה' \u0003עולה\u0004 תמיד בצד \u0003ימין, מכאן ואילך — פעמים עולה בימין פעמים עולה בשמאל.\u0004 וכן כל השנים ששימש שמעון הצדיק ככהן גדול \u0003היה לשון של זהורית\u0004 (צמר סרוק שהיה צבוע אדום) שקושרים בראש השעיר המשתלח \u0003מלבין,\u0004 בדרך נס, להודיע שנמחלו חטאי ישראל ככתוב \"אם יהיו חטאיכם כשנים כשלג ילבינו\" (ישעיה א, יח), \u0003מכאן ואילך פעמים מלבין פעמים אינו מלבין.\u0004 וכן \u0003היה נר מערבי\u0004 במנורה \u0003דולק\u0004 בדרך נס כל היום וכל הלילה אף לאחר שכבו כל שאר הנרות, והיה בכך אות כי השכינה שורה על ישראל, \u0003מכאן ואילך פעמים דולק פעמים כבה.\u0004 \u0003והיה אש מערכה מתגבר\u0004 תמיד ודולקת מעצמה \u0003ולא היו\u0004 ה\u0003כהנים צריכין להביא עצים\u0004 נוספים \u0003למערכה\u0004 של עצים כל היום כולו \u0003חוץ משני גזירי עצים\u0004 שהיו מביאים \u0003כדי לקיים מצות עצים, מכאן ואילך — פעמים\u0004 האש \u0003מתגבר\u0004 ו\u0003פעמים אין מתגבר\u0004, \u0003ולא היו כהנים נמנעין מלהביא עצים למערכה כל היום כולו.\u0004","","וכן \u0003ונשתלחה ברכה\u0004 בימי שמעון הצדיק \u0003בעומר, ובשתי הלחם, ובלחם הפנים.\u0004 ולאחר שחלקו את אלה לכהנים \u0003וכל כהן שמגיעו\u0004 מהן \u0003כזית יש\u0004 שהיה \u0003אוכלו\u0004 מזית זה \u0003ושבע, ויש\u0004 אף שהיה \u0003אוכלו ומותיר,\u0004 שהיתה בו ברכת השובע. \u0003מכאן ואילך נשתלחה מאירה\u0004 (קללה) \u0003בעומר ובשתי הלחם ובלחם הפנים, וכל כהן מגיעו כשיעור פול\u0004 (פחות מכזית) בלבד ולא יותר, הכהנים \u0003הצנועין\u0004 היו \u0003מושכין את ידיהן\u0004 בכלל מנטילת חלקם בלחם הפנים, שלא היה בו כשיעור אכילת מצוה \u0003והגרגרנין\u0004 היו \u0003נוטלין ואוכלין, ומעשה באחד שנטל חלקו וחלק חבירו, והיו קורין אותו \"בן\u0004"],["\u0003חמצן\u0004 (גזלן) \u0003\" עד יום מותו.\u0004","\u0003אמר רבה בר רב שילא: מאי קרא\u0004 \u0005[מהו הפסוק]\u0006 שממנו למדים ש\"חמצן\" פירושו גזלן? — שנאמר: \u0003\"אלהי פלטני מיד רשע מכף מעול וחומץ\"\u0004 (תהלים עא, ד). \u0003רבא אמר: מהכא\u0004 \u0005[מ\u0006כתוב \u0005זה]\u0006 \u0003\"למדו היטב דרשו משפט אשרו חמוץ\"\u0004 (ישעיה א, יז) ומשמעו: \u0003אשרו חמוץ\u0004 = נגזל, \u0003ואל תאשרו חומץ\u0004 = גזלן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ב\u0003אותה שנה שמת בה שמעון הצדיק אמר להם\u0004 למקורביו: \u0003בשנה זו הוא\u0004 (אני) \u0003מת. אמרו לו: מניין אתה יודע? אמר להם: בכל יום הכפורים היה מזדמן לי\u0004 במחזה כעין נבואה \u0003זקן אחד לבוש לבנים ועטוף לבנים, נכנס עמי\u0004 לקודש הקודשים \u0003ויצא עמי, והיום נזדמן לי זקן לבוש שחורים ועטוף שחורים, נכנס עמי ולא יצא עמי\u0004 לרמז לו ששנה זו שנתו האחרונה. \u0003אחר הרגל\u0004 (חג הסוכות) \u0003חלה שבעה ימים ומת.\u0004","ומאז הרגישו הכל שיש שינוי וירידה בדורות \u0003ונמנעו אחיו הכהנים מלברך\u0004 את ישראל ברכת כהנים \u0003בשם\u0004 המפורש, והיו אומרים כפי שאנו אומרים היום, בכינוי.","כיון שתוארו ימי ההצלחה במקדש בימי שמעון הצדיק מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארבעים שנה קודם חורבן הבית לא היה גורל\u0004 של יום הכיפורים \u0003עולה\u0004 כלל \u0003בימין, ולא היה לשון של זהורית\u0004 הקשור בראשו של השעיר המשתלח \u0003מלבין, ולא היה נר מערבי דולק\u0004 יותר משאר נרות","\u0003והיו דלתות ההיכל נפתחות מאליהן\u0004 כרמז שהן עתידות להפתח על ידי האויבים, \u0003עד שגער בהן רבן יוחנן בן זכאי.\u0004 וכך \u0003אמר לו: היכל היכל! מפני מה אתה מבעית\u0004 (מפחיד) \u0003עצמך\u0004 בסימנים אלה? \u0003יודע אני בך שסופך עתיד ליחרב, וכבר נתנבא עליך זכריה בן עדוא: \"פתח לבנון דלתיך ותאכל אש בארזיך\"\u0004 (זכריה יא, א) ולבנון הוא כינוי לבית המקדש,","ש\u0003אמר ר' יצחק בן טבלאי: למה נקרא שמו לבנון — שמלבין עונותיהן של ישראל.\u0004","\u0003אמר רב זוטרא בר טוביה: למה נקרא שמו יער,\u0004 שכן נאמר: \u0003\"בית יער הלבנון\"\u0004 (מלכים א, י, יז) \u0003לומר לך: מה יער מלבלב\u0004 ומצמיח — \u0003אף בית המקדש מלבלב.\u0004 וכפי ש\u0003אמר רב הושעיא: בשעה שבנה שלמה בית המקדש נטע בו כל מיני מגדים\u0004 (עצי פרי) \u0003של זהב, והיו מוציאין פירות בזמניהן\u0004 בדרך נס. \u0003וכיון שהרוח מנשבת בהן היו נושרין פירותיהן, שנאמר: \"ירעש כלבנון פריו\"\u0004 (תהלים עב, טז) \u0003ומהן\u0004 מפירות זהב אלה \u0003היתה פרנסה לכהונה.\u0004","\u0003וכיון שנכנסו גוים להיכל יבשו\u0004 עצים אלו, \u0003שנאמר: \"ופרח לבנון אמלל\"\u0004 (נחום א, ד). \u0003ועתיד הקדוש ברוך הוא להחזירה לנו\u0004 בשעת הגאולה העתידה, \u0003שנאמר: \"פרח תפרח ותגל אף גילת ורנן כבוד הלבנון נתן לה\"\u0004 (ישעיה לה, ב).","שנינו במשנה כי לאחר שהעלה הכהן את שתי הגורלות, \u0003נתנן\u0004 את הגורלות \u0003על שני השעירים,\u0004 וכשנתן הגורל לה', היה מזכיר את השם. בנושא זה של הזכרת השם על ידי הכהן הגדול \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003עשר פעמים מזכיר\u0004 ה\u0003כהן\u0004 ה\u0003גדול את השם בו ביום\u0004 (ביום הכיפורים): \u0003שלשה\u0004 פעמים \u0003בוידוי ראשון, ושלשה בוידוי שני\u0004 על הפר, \u0003ושלשה\u0004 בזמן שהוא מתוודה \u0003בשעיר המשתלח, ואחד בגורלות.\u0004","\u0003וכבר\u0004 היה מעשה ש\u0003אמר\u0004 הכהן הגדול \u0003\"השם\"\u0004 והיה קולו כה אדיר עד שהולך ו\u0003נשמע קולו\u0004 אף \u0003ביריחו\u0004. \u0003אמר רבה בר בר חנה: מירושלים ליריחו עשרה פרסאות,\u0004 ללמדנו מה רב המרחק, ואף על פי כן היה הקול נשמע. וכיון שסיפרו בדבר זה מוסיפים מעשים אחרים כעין זה.","אמרו: \u0003ציר דלתות ההיכל\u0004 כאשר השער נפתח \u0003נשמע בשמונה תחומי שבת\u0004 שהוא מרחק של שמונה מילין. ועוד: \u0003עזים\u0004 ש\u0003ביריחו היו מתעטשות מריח הקטורת\u0004 שהוקטרה במקדש, וכן \u0003נשים שביריחו אינן צריכות להתבשם\u0004 מפני \u0003ריח\u0004 ה\u0003קטורת\u0004 שהיה מגיע עד שם. \u0003כלה שבירושלים אינה צריכה להתקשט\u0004 מחמת \u0003ריח\u0004 ה\u0003קטורת\u0004 שהיה כה ערב ומגיע לכל מקום בירושלים.","\u0003אמר ר' יוסי בן דולגאי: עזים היו לאבא בהרי מכמר\u0004 (מחוז מרוחק מירושלים), \u0003והיו מתעטשות מריח הקטורת.\u0004 וקצת בדומה לזה: \u0003אמר ר' חייא בר אבין אמר ר' יהושע בן קרחה: סח לי זקן אחד: פעם אחת הלכתי לשילה,\u0004 לחורבות המקום שבו עמד המשכן בימי השופטים, \u0003והרחתי ריח קטורת מבין כותליה,\u0004 אף שעברו מאז יותר מאלף שנה.","\u0003אמר ר' ינאי: עליית גורל מתוך קלפי — מעכבת,\u0004 שכל זמן שלא הוציא הכהן את הגורלות מן הקלפי לא נקבע מי מן השעירים לה' ומי לעזאזל ולכך עדיין לא ניתן לעשות בהן עבודתם, אולם \u0003הנחה\u0004 של הגורלות על השעירים לאחר הוצאת מן הקלפי — \u0003אינה מעכבת\u0004 ואף שעדיין לא הניח, יכול לעשות את העבודות. \u0003ור' יוחנן אמר: אף עלייה אינה מעכבת,\u0004 ואם יקבע הכהן בלא הגרלה איזה הוא השעיר לה' ואיזה לעזאזל — יצא ידי חובתו, אף שביטל מצות הכתוב.","ומבארים את המחלוקת: \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' יהודה,\u0004 ש\u0003אמר\u0004 בכלל: \u0003דברים\u0004 המיוחדים ליום הכיפורים \u0003הנעשים\u0004 אפילו \u0003בבגדי לבן מבחוץ\u0004 שלא בקודש הקדשים \u0003לא מעכבא\u0004 \u0005[מעכבים],\u0006 שאף אם לא עשאום, לא בטלה בכך עבודת יום הכיפורים כולה, אם כן לשיטה זו \u0003כולי עלמא לא פליגי דלא מעכבא\u0004 \u0005[הכל אינם חלוקים שאין\u0006 ההגרלה \u0005מעכבת].\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' נחמיה\u0004 שלדעתו אף העבודות הנעשות בבגדי לבן בחוץ מעכבות, \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי ההגרלה \u0003מעכבא\u0004 \u0005[מעכבת]\u0006 — סבר ממש כדברי \u0003ר' נחמיה. ומאן דאמר\u0004 \u0005[ומי שאמר]\u0006 \u0003לא מעכבא\u0004 \u0005[מעכבת]\u0006 סבור: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאמר ר' נחמיה שהעבודות בבגדי לבן מעכבות הריהן רק לענין דברים המוגדרים כ\u0003עבודה,\u0004 כגון הקרבת הקרבנות, אבל \u0003הגרלה לאו עבודה היא.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 כי כך יש לייחס את המחלוקת,","\u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' נחמיה\u0004 ש\u0003אמר\u0004 שהנעשה בבגדי לבן בחוץ \u0003מעכבא\u0004 \u0005[מעכבת]\u0006 — \u0003כולי עלמא לא פליגי דמעכבא\u0004 \u0005[הכל אינם חלוקים\u0006 שהגרלה \u0005מעכבת],\u0006","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הוא \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' יהודה. מאן דאמר לא מעכבא\u0004 \u0005[מי שאמר אינה מעכבת] —\u0006 דעתו \u0003כר' יהודה, ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003מעכבא\u0004 \u0005[מעכבת]\u0006 אומר כי \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 \u0003דתנא ביה קרא\u0004 \u0005[ששנה בו הכתוב],\u0006 שנאמר: \u0003\"אשר עלה\"\u0004 (ויקרא טז, ט) \u0003\"אשר עלה\"\u0004 (ויקרא טז, י) \u0003תרי זימני\u0004 \u0005[שתי פעמים]\u0006 וכלל בידינו בהלכות קדשים כי כל מקום שכפל הכתוב דבריו — הרי זה ללמד שהוא מעכב.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 ממה ששנינו בברייתא: \u0003מצוה להגריל ואם לא הגריל כשר.\u0004","ומעתה לשיטת הברייתא, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003להך לישנא דאמרת\u0004 \u0005[ללשון זו שאמרת]\u0006 כי \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' יהודה כולי עלמא לא פליגי דלא מעכבא\u0004 \u0005[הכל אינם חלוקים שאינה מעכבת]\u0006 \u0003הא מני —\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 דעת \u0005מי היא] —\u0006 כשיטת \u0003ר' יהודה היא\u0004 לכל הדעות."],["\u0003אלא להך לישנא דאמרת פליגי\u0004 \u0005[ללשון זו שאתה אומר\u0006 שאף התנאים \u0005חולקים בכך],\u0006 \u0003בשלמא למאן דאמר לא מעכבא\u0004 \u0005[נניח\u0006 לשיטת \u0005מי שאומר\u0006 כי \u0005אינה מעכבת]\u0006 \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא] —\u0006 כשיטת \u0003ר' יהודה היא,\u0004","\u0003אלא למאן דאמר מעכבא\u0004 \u0005[\u0006לדעת \u0005מי שאומר מעכבת]\u0006 \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 ומתרצים: \u0003תני\u0004 \u0005[שנה]\u0006 תקן כך: \u0003מצוה להניח\u0004 את הגורלות על השעירים, אולם אם לא הניח — כשר. ובזה הכל מודים שאינה מעכבת.","\u0003תא שמע\u0004 \u0005[בא ושמע]\u0006 פתרון אחר לשאלה מן הברייתא: \u0003מצוה\u0004 על הכהן \u0003להגריל ולהתודות, לא הגריל ולא התודה — כשר. וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך גם כן]\u0006 תתקן גם כן שמצוה \u0003להניח,\u0004 אם כן \u0003אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של אותה ברייתא\u0005]\u0006 \u0003ר' שמעון אומר: לא הגריל — כשר, לא התודה — פסול.\u0004","ועתה נברר \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא הגריל\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שכוונת הדברים היא \u0003לא הניח,\u0004 אם כן \u0003מכלל\u0004 הדברים ש\u0003ר' שמעון סבר\u0004 כי \u0003הגרלה מעכבא\u0004 \u0005[מעכבת],\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 באותו ענין עצמו: אם לאחר שערכו הגרלה על שני שעירים וקבעו כל אחד למצוותו \u0003מת אחד מהן, מביא חבירו\u0004 (שעיר אחר) \u0003שלא בהגרלה, דברי ר' שמעון.\u0004 הרי שלדעתו אין ההגרלה מעכבת!","ומשיבים: \u0003ר' שמעון לא ידע מאי קאמרי רבנן\u0004 \u0005[לא ידע\u0006 היטב, לא היה ברור לו, \u0005מה אומרים חכמים],\u0006 \u0003והכי קאמר להו\u0004 \u0005[וכך אמר להם],\u0006 כלומר, כך יש לפרש את הדברים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003הגרלה הגרלה ממש קא אמריתו\u0004 \u0005[אומרים אתם],\u0006 כלומר: העלאת הגורל מן הקלפי, הרי \u0003פליגנא עלייכו בחדא\u0004 \u0005[חולק אני עליכם\u0006 בהלכה \u0005אחת],\u0006 שלדעתי זו אינה מעכבת. \u0003אי הגרלה דאמריתו היינו הנחה\u0004 \u0005[ואם הגרלה שאתם אומרים כוונתה הנחה]\u0006 \u0003פליגנא עלייכו בתרתי\u0004 \u0005[חולק אני עליכם בשתים]\u0006 בהגרלה ובהנחה, שלדעתי שתיהן אינן מעכבות.","\u0003תא שמע\u0004 \u0005[בא ושמע]\u0006 ראיה ממקור אחר; ששנינו כי מהלך העבודה הנעשה ב\u0003פר\u0004 יום הכיפורים \u0003מעכב את\u0004 מהלך העבודה הנעשה ב\u0003שעיר,\u0004 שכל עבודה בשעיר האמורה להיעשות לאחר שנעשו עבודות מסויימות בפר, אם עשאה לפניהן — עבודה זו פסולה,","ואילו עבודה האמורה להיעשות ב\u0003שעיר\u0004 לפני עבודות הפר אם עשה לפניה את עבודות הפר המאוחרות \u0003אין מעכב את\u0004 עבודות \u0003הפר במתנות שבפנים\u0004 ואינן נפסלות.","ומעתה נסביר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שאמרו כי \u0003פר מעכב את השעיר,\u0004 כוונתו היא: \u0003דאי אקדמיה\u0004 \u0005[שאם הקדים]\u0006 והקריב את ה\u0003שעיר מקמי\u0004 \u0005[לפני]\u0006 ה\u0003פר — לא עבד\u0004 \u0005[עשה]\u0006 \u0003ולא כלום\u0004 וצריך לחזור ולעשות כתיקונו. \u0003אלא שעיר אין מעכב את הפר מאי ניהו\u0004 \u0005[מה הוא],\u0006 מה עניינו?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דאי אקדים\u0004 \u0005[שאם הקדים]\u0006 את ה\u0003מתנות\u0004 של ה\u0003פר בהיכל מקמי\u0004 \u0005[לפני]\u0006 נתינת ה\u0003מתנות של\u0004 ה\u0003שעיר\u0004 הניתנות \u0003בפנים\u0004 — דבר זה אינו יתכן, שהרי \u0003\"חוקה\" כתיב בהו\u0004 \u0005[נאמר בהם],\u0006 ודבר שכתוב בו \"חוקה\" פירושו שהוא לעכב.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003דאקדים\u0004 \u0005[שהקדים]\u0006 את ה\u0003מתנות\u0004 של ה\u0003פר\u0004 הניתנות \u0003בפנים מקמיה\u0004 \u0005[מלפני]\u0006 \u0003הגרלה\u0004 על השעירים. \u0003ומדסדרא לא מעכבא\u0004 \u0005[וכיון שהסדר\u0006 לגבי ההגרלה \u0005אינו מעכב] —\u0006 סברה היא ש\u0003עיקרא\u0004 \u0005[עיקר]\u0006 \u0003הגרלה נמי לא מעכבא\u0004 \u0005[גם כן אינה מעכבת]!\u0006 שאם ההגרלה היא חובה ממש ביום הכיפורים אינו מסתבר שיכול לשנות את זמנה.","ודוחים: \u0003לא,\u0004 הכוונה בברייתא היא כי אם הקדים \u0003מתנות\u0004 של \u0003פר במזבח\u0004 הפנימי \u0003מקמי\u0004 \u0005[מלפני]\u0006 \u0003מתנות\u0004 של \u0003שעיר בהיכל\u0004 אין הדבר מעכב\u0003.\u0004 ודבר זה כשיטת \u0003ר' יהודה הוא,\u0004 ש\u0003אמר: דברים הנעשין בבגדי לבן בחוץ — לא מעכבי\u0004 \u0005[אינם מעכבים]\u0006 וזריקת הדם על המזבח מן הדברים שבחוץ היא.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003במתנות שבפנים קתני\u0004 \u0005[שנינו],\u0006 ומשמע שאנו מדברים דווקא על עבודת פנים!","\u0003אלא\u0004 כך יש לומר: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו כשיטת מי היא] —\u0006 כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: הגרלה לא מעכבא\u0004 \u0005[מעכבת]\u0006 אבל שאר החכמים סבורים כי היא מעכבת.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003לעולם\u0004 אותה ברייתא המדברת בשינוי הסדר כדעת \u0003ר' יהודה היא,\u0004 אולם \u0003נהי דבסדרא לא מעכבא — הגרלה מיהא מעכבא\u0004 \u0005[אף על פי שבסדר אינה מעכבת —\u0006 \u0005הגרלה עצמה מכל מקום מעכבת].\u0006","ולפי זה \u0003ואזדו לטעמייהו\u0004 \u0005[הולכים הם\u0006 לשיטתם\u0005]\u0006 שכבר הביעו בדומה לזה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006"],["נאמר: \"והשעיר אשר עלה עליו הגורל לעזאזל \u0003יעמד חי לפני ה' לכפר עליו\u0004 לשלח אותו לעזאזל המדברה\" (ויקרא טז, י), ולמדו חכמים כי על השעיר להיות חי במשך זמן מסויים ואם מת לפני כן, יש להביא אחר במקומו. ואמרו חכמים: \u0003עד מתי יהיה זקוק\u0004 שעיר זה \u0003לעמוד חי — עד שעת מתן דמו של חבירו\u0004 (השעיר הנעשה לה'), ואם מת לאחר מכן — אין צריך להביא אחר, אלו \u0003דברי ר' יהודה. ר' שמעון אומר:\u0004 על השעיר המשתלח להיות חי \u0003עד שעת וידוי דברים\u0004 עליו, ואחר כך אם מת — שוב אין זה מעכב.","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]?\u0006 \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר בשעיר המשתלח: \u0003\"לכפר\"\u0004 (ויקרא טז, י), ולדעת הכל על השעיר להיות חי עד שעת הכפרה. ומאי כפרה זו? — \u0003בכפרת דמים\u0004 על ידי זריקת הדם השעיר לה' \u0003הכתוב מדבר, וכן הוא אומר \"וכלה מכפר את הקדש\u0004 ואת אהל מועד ואת המזבח והקריב את השעיר החי\u0003\"\u0004 (ויקרא טז, כ), \u0003מה להלן\u0004 הכוונה היא \u0003בכפרת דמים — אף כאן\u0004 שנאמר \"לכפר\" — \u0003בכפרת דמים\u0004 הכתוב מדבר, אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' שמעון אומר: \"לכפר עליו\" — בכפרת דברים\u0004 על ידי וידוי \u0003הכתוב מדבר.\u0004","\u0003תא שמע\u0004 \u0005[בא ושמע]\u0006 ראיה אחרת אם ההגרלה מעכבת. ששנינו: \u0003שאלו תלמידיו את ר' עקיבא:\u0004 עלה הגורל לה' ביד \u0003שמאל, מהו שיחזור,\u0004 כלומר: יהפוך את הידים וישים אותו ב\u0003ימין? אמר להן: אל תתנו מקום למינין לרדות\u0004 (למשול), כלומר: אל תתנו להם מקום להתקיף את החכמים ולומר שהם עושים הכל כרצונם.","ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003אל תתנו מקום למינים לרדות, הא לאו הכי\u0004 \u0005[הרי אם לא\u0006 היה \u0005כך]\u0006 מעיקר הדין \u0003מהדרינן ליה\u0004 \u0005[\u0006היינו \u0005מחזירים אותו],\u0006 \u0003והא אמרת\u0004 \u0005[והרי אומר אתה]\u0006 ש\u0003הגרלה מעכבא\u0004 \u0005[מעכבת]\u0006 \u0003וכיון דקבעתיה\u0004 \u0005[ש\u0006כבר \u0005קבעה אותו]\u0006 יד \u0003שמאל\u0004 שהוא צריך להיות השעיר לה' \u0003היכי מהדרינן ליה\u0004 \u0005[כיצד\u0006 אם כן \u0005מחזירים אנו אותו]?\u0006 והרי מכאן הוכחה לכאורה שאין הגרלה מעכבת!","ודוחים, \u0003אמר רבא: הכי קאמרי\u0004 \u0005[כך אומרים],\u0006 כך היתה כוונתם: אם \u0003עלה הגורל בשמאל, מהו שיחזירו לו ולשעירו לימין\u0004 כלומר לא ישנה השעיר שעלה עליו הגורל לה', אלא למראית העין יהפכו את הסדר כולו, שיראה שהשעיר לה' עלה בימין. \u0003אמר להם: אל תתנו מקום למינים לרדות.\u0004 ואם כן אין להוכיח מכאן.","ועוד מנסים להוכיח, \u0003תא שמע\u0004 \u0005[בא ושמע]:\u0006 \u0003אילו נאמר: \"את השעיר אשר עליו\u0004 הגורל\u0003\"\u0004 (ויקרא טז, ט) \u0003הייתי אומר יניחנו עליו,\u0004 שחייבים להניח את הגורל על השעיר — \u0003תלמוד לומר:\u0004 \"אשר \u0003עלה\u0004 עליו\" (ויקרא טז, ט) \u0003כיון שעלה\u0004 הגורל מן הקלפי \u0003שוב אינו צריך\u0004 להניחו על השעיר.","ומעתה נברר את פירוש הדברים לדיוקם, מה שאמרו \"אינו צריך\" \u0003למאי\u0004 \u0005[למה]\u0006 היתה הכוונה? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שהכוונה היא שאין צריך כלל, אפילו לא \u0003למצוה\u0004 לכתחילה, האם נאמר \u0003מכלל\u0004 הדברים ש\u0003הנחה\u0004 של הגורלות על גבי השעירים אפילו \u0003מצוה\u0004 היא \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא?\u0004 והרי בפירוש שנינו הנחה בסדר עבודת היום! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה שאינו צריך להניח פירושו שאין \u0003לעכב\u0004 אם לא הניח. \u0003ושמע מינה\u0004 \u0005[ותלמד מכאן]\u0006 כי \u0003הגרלה מעכבא\u0004 \u0005[מעכבת]\u0006 ואילו \u0003הנחה\u0004 על השעיר עצמו \u0003לא מעכבא\u0004 \u0005[מעכבת]!\u0006","\u0003אמר רבא:\u0004 מכאן אין להוכיח, כי \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין את הדברים\u0005]:\u0006 \u0003אילו נאמר: \"אשר עליו\u0004 הגורל\u0003\", הייתי אומר יניחנו\u0004 את הגורל \u0003עליו\u0004 על השעיר \u0003עד שעת שחיטה, תלמוד לומר: \"אשר עלה\" — כיון שעלה\u0004 פעם אחת וכבר ידוע איזה מן השעירים לה' ואיזה לעזאזל \u0003שוב אינו צריך\u0004 ומותר להסירם מעל השעירים. ואם כן, אין לפתור מכאן אם ההנחה עצמה מעכבת.","\u0003תא שמע\u0004 \u0005[בא ושמע]\u0006 ראיה לדבר מברייתא אחרת: על הנאמר בכתוב: \u0003\"\u0004והקריב אהרן את השעיר אשר עלה עליו הגורל לה' \u0003ועשהו חטאת\"\u0004 (ויקרא טז, ט), שנינו: \u0003הגורל עושהו חטאת, ואין השם עושהו חטאת\u0004 שאין בקריאת שמו כשעיר לה' או כשעיר לעזאזל לעשותו קדוש כמו בשאר קרבנות.","ודנים בדבר: \u0003שיכול,\u0004 אפשר היה לחשוב אחרת: \u0003והלא דין\u0004 (קל וחומר) \u0003הוא: ומה במקום\u0004 (שאר כל הקרבנות) \u0003שלא קידש\u0004 בהם \u0003הגורל\u0004 ובכל זאת \u0003קידש\u0004 בהם קריאת \u0003השם,\u0004 וכגון בקיני זבים וזבות ויולדות שאחד מן התורים או מבני היונה הוא לחטאת והשני לעולה, ואם קובע על פי גורל איזה מהן תהיה לעולה ואיזה לחטאת — אין בכך כלום ואילו אם קבע כך בפיו — נתקדשו בכך, \u0003מקום\u0004 (שעירי יום הכיפורים) \u0003שקידש\u0004 בו \u0003הגורל, אינו דין שיקדש\u0004 בו אף \u0003השם?\u0004","\u0003תלמוד לומר: \"ועשהו חטאת\",\u0004 להדגיש כי \u0003הגורל עושה חטאת, ואין השם עושה חטאת.\u0004"],["\u0003סתם\u0004 דברי הלכה הנזכרים ב\u0003סיפרא\u0004 (מדרש ההלכה לתורת כהנים) \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא] —\u0006 כשיטת \u0003ר' יהודה\u0004 היא, כידוע, \u0003וקא תני\u0004 \u0005[ושנינו שם]:\u0006 \u0003הגורל עושה חטאת ואין השם עושה חטאת. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003הגרלה מעכבא\u0004 \u0005[מעכבת],\u0006 שהרי לשיטה זו ללא הגרלה אין אפשרות לקבוע את ייעוד השעירים, ואם כן הרי זו \u0003תיובתא דמאן דאמר\u0004 \u0005[קושיה חמורה למי שאמר]\u0006 כי \u0003הגרלה לא מעכבא\u0004 \u0005[מעכבת]\u0006 לשיטת ר' יהודה. ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה\u0006 חמורה היא\u0005]\u0006 והושבו דבריו מכל וכל.","כיון שעסקנו בשאלת קביעת הקרבנות למטרתם מביאים הלכה נוספת בנושא זה. \u0003אמר רב חסדא: אין הקינין\u0004 כאשר מביא אדם זוג תורים או בני יונה, אחד לחטאת ואחד לעולה, \u0003מתפרשות\u0004 (מתחלקות ונקבעות) איזה מהן לחטאת ואיזה לעולה \u0003אלא או בלקיחת בעלים\u0004 כשהבעלים בשעת קניה מחליטים בענין זה, \u0003או\u0004 אם לא החליטו הבעלים על כך בשעת הקניה — \u0003בעשיית כהן\u0004 כאשר הכהן מקריב אותם.","\u0003אמר רב שימי בר אשי: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003רב חסדא\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בפסוק אחד: \"ואם לא תמצא ידה די שה\u0003ולקחה\u0004 שתי תורים או שני בני יונה אחד לעולה ואחד לחטאת\" (ויקרא יב, ח) ונאמר עוד בפסוק אחר: \u0003\"ועשה\u0004 אותם הכהן אחד חטאת והאחד עולה\u0003\"\u0004 (ויקרא טו, טו), ללמד שהחלטה זו נעשית \u0003או\u0004 בשעת \u0003לקיחה\u0004 על ידי הבעלים, \u0003או\u0004 בשעת \u0003עשייה\u0004 על ידי הכהן.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: נאמר: \u0003\"ועשהו חטאת\"\u0004 (ויקרא טז, ט), ללמד ש\u0003הגורל עושה חטאת ואין השם עושה חטאת.\u0004","\u0003שיכול\u0004 אתה לומר אחרת: \u0003והלא דין\u0004 (קל וחומר) \u0003הוא ומה במקום\u0004 (בקרבן קינים) \u0003שלא קידש\u0004 בהם \u0003הגורל\u0004 לקבוע איזה מהם לעולה ואיזה לחטאת \u0003— קידש השם\u0004 על ידי עצם קריאת שם עולה או חטאת, \u0003מקום\u0004 (שני שעירי יום הכיפורים) \u0003שקידש\u0004 בהם \u0003הגורל — אינו דין שיקדש\u0004 בהם אף \u0003השם,\u0004","\u0003תלמוד לומר: \"ועשהו חטאת\" — הגורל עושה חטאת, ואין השם עושה חטאת.\u0004","ואם מקבלים את שיטת רב חסדא הדבר תמוה: \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 לענין שעיר זה, שעלה על הדעת שבקריאת שם לבד לעשותו חטאת \u0003דלאו\u0004 \u0005[שאין\u0006 זו\u0005]\u0006 \u0003שעת לקיחה\u0004 שהרי כבר נקנה לפני יום הכיפורים, \u0003ולאו\u0004 \u0005[ולא]\u0006 \u0003שעת עשייה היא, וקתני\u0004 \u0005[ולמדנו]\u0006 שיש סברה לומר ש\u0003קבע\u0004 בקריאת השם בלבד; ואם כן הרי זה לא כדברי רב חסדא!","\u0003אמר רבא: הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]\u0006 \u0003מה במקום שלא קידש הגורל\u0004 בשאר קרבנות \u0003ואפילו\u0004 היה מטיל גורל \u0003בשעת לקיחה, ואפילו בשעת עשייה\u0004 — מכל מקום \u0003קידש השם בשעת לקיחה ובשעת עשייה, מקום שקידש הגורל\u0004 וקביעה זו \u0003שלא בשעת לקיחה ושלא בשעת עשייה, אינו דין שיקדש השם בשעת לקיחה ובשעת עשייה?\u0004","על כן \u0003תלמוד לומר: \"ועשהו חטאת\",\u0004 לומר כי רק \u0003הגורל עושה חטאת ולא השם עושה חטאת.\u0004","ומנסים להביא ראיה אחרת, \u0003תא שמע\u0004 \u0005[בא ושמע]:\u0006 \u0003מטמא מקדש\u0004 (הנכנס למקדש כשהוא טמא) בשגגה שהיה \u0003עני,\u0004 וזו מן העבירות שיש הבדל בקרבנות הכפרה בין עני לעשיר (=קרבן עולה ויורד), שהעני צריך להביא קן תורים או של בני יונה, אחד לחטאת ואחד לעולה ואילו העשיר מביא בהמה אחת לחטאת בלבד, וכיון שהיה עני \u0003הפריש מעות לקינו\u0004 ובינתיים \u0003העשיר\u0004 וצריך להביא מעתה קרבן עשיר מן הבהמה, \u0003ואחר כך\u0004 חילק את הכסף שהפריש לשעבר, ו\u0003אמר:\u0004 דמים \u0003אלו לחטאתו, ואלו לעולתו —\u0004","\u0003מוסיף ומביא חובתו\u0004 של קרבן חטאת מן הבהמה \u0003מדמי חטאתו, ואין מוסיף ומביא חובתו\u0004 של חטאת \u0003מדמי עולתו.\u0004 שהרי כבר הוקדשה לעולה, ואינו יכול לשנותה לחטאת, ומכל מקום למדנו מכאן כי יכול המפריש להחליט מה יהא לחטאת ומה לעולה בשעת חלוקת הכסף.","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 כשהעשיר, \u0003דלאו\u0004 \u0005[שאין זו]\u0006 \u0003שעת לקיחה, ולאו\u0004 \u0005[ולא]\u0006 \u0003שעת עשייה היא, וקתני\u0004 \u0005[ולמדנו]\u0006 ש\u0003קבע!\u0004","\u0003אמר רב ששת: ותסברא\u0004 \u0005[וסבור אתה]\u0006 שברייתא זו אפשר לקיימה כמות שהיא? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר אמר ר' הושעיא: מטמא מקדש\u0004 כשהוא \u0003עשיר והביא קרבן עני — לא יצא\u0004 כלל ידי חובתו, \u0003וכיון\u0004 ש\u0003לא יצא\u0004 אם כן \u0003היכי קבע\u0004 \u0005[איך\u0006 יכול \u0005הוא לקבוע]\u0006 לגבי מעות שהוקדשו כקרבן עני מה יהא קרבנו?","\u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 שמה שאמרנו שחילק האיש במעות \"זה לחטאת וזה לעולה\" בהכרח לומר \u0003שכבר אמר\u0004 דבר זה בשעת \u0003עניותו, הכא נמי\u0004 \u0005[כך גם כאן]\u0006 תפרש כשלא אמר זאת לאחר זמן אלא \u0003שכבר אמר משעת הפרשה\u0004 מה יהא החלק לעולה ומה לחטאת, ובאופן כזה הלא גם רב חסדא מסכים שאפשר לעשות כן.","ושואלים: ולשיטת \u0003ר' חגא אמר ר' יאשיה,\u0004 ש\u0003אמר\u0004 שמטמא מקדש עשיר שהביא קרבן עני \u0003יצא\u0004 ידי חובתו,"],["\u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 לפי שיטה זו? ומשיבים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 כפי שגרסנו: \u0003\"ואחר כך אמר\", אלא אימא\u0004 \u0005[אמור]\u0006 ותקן: \u0003ואחר כך לקח ואמר,\u0004 שבשעת לקיחה קבע איזה מהם לחטאת ואיזה לעולה.","ושואלים: אם כן מה ששנינו שאם \u0003לקח מוסיף ומביא חובתו מאי ניהו\u0004 \u0005[מה הוא,\u0006 מה פירוש הדבר\u0005],\u0006 כיצד יכול הוא להוסיף על העוף שקנה כבר?!","על כך משיבים: \u0003דפריק ליה\u0004 \u0005[שהוא פודה אותו]\u0006 את העוף ומוציאו לחולין ונעשים מעותיו קודש ומוסיף עליהם. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 יודעים אנו כי \u0003אין פדיון לעוף\u0004 לאחר שהקדישוהו לקרבן!","\u0003אמר רב פפא: כגון שלקח פרידה\u0004 (יחידה) \u0003אחת,\u0004 גוזל אחד ולא שנים, ולכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003עולה זבן\u0004 \u0005[קנה] —\u0006 \u0003מוסיף ומביא חובתו\u0004 לחטאת בהמה \u0003מדמי חטאתו\u0004 שהפריש לקנות עוף ועדיין לא קנה בהם, \u0003והאי\u0004 \u0005[וזו]\u0006 ה\u0003עולה\u0004 שהפריש \u0003אזלא\u0004 \u0005[הולכת]\u0006 ונעשית קרבן \u0003לנדבה.\u0004 ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003חטאת זבן\u0004 \u0005[קנה]\u0006 מתחילה ולפיכך המעות שנותרו עומדות לעולה — \u0003אין מוסיף ומביא חובתו מדמי עולתו, והאי\u0004 \u0005[וזו]\u0006 \u0003חטאת\u0004 אותו עוף שהקריב לשם כך \u0003אזלא\u0004 \u0005[הולכת]\u0006 \u0003למיתה\u0004 ככל קרבן חטאת שהתכפרו בעליו באחר.","כיון שהוזכרה המחלוקת בענין קרבן עשיר ועני, מביאים את \u0003גופא\u0004 \u0005[גופה]\u0006 של המחלוקת. \u0003אמר ר' אלעזר אמר ר' הושעיא: מטמא מקדש\u0004 כשהוא \u0003עשיר והביא קרבן עני — לא יצא. ור' חגא אמר ר' הושעיא\u0004 אמר: \u0003יצא.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 מן המשנה, שנאמר בה: \u0003מצורע עני שהביא קרבן עשיר — יצא,\u0004 ואילו מצורע \u0003עשיר שהביא קרבן עני — לא יצא.\u0004 וכיצד איפוא אמר ר' חגא שמטמא מקדש יצא? ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 במצורע, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"זאת\u0004 תהיה תורת המצורע ביום טהרתו\u0003\"\u0004 (ויקרא יד, ב), \"זאת\", כלומר: כך דווקא, ואין לשנות.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאסרה התורה לשנות, \u0003רישא נמי\u0004 \u0005[מתחילה,\u0006 בדין הראשון \u0005גם כן]\u0006 יהא כן הדין, שעני שהביא קרבן עשיר גם הוא לא יצא ידי חובה, שהרי אמרה התורה \"זאת\" ולא אחרת! ומשיבים: \u0003הא רבי רחמנא\u0004 \u0005[הרי רבתה התורה]\u0006 \u0003\"תורת\"\u0004 (ויקרא יד,ב) ללמד שיש רשות להוסיף על הקצוב לו \u0003והתניא\u0004 \u0005[וכן שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"תורת\" — לרבות מצורע עני שהביא קרבן עשיר\u0004 שיצא בכך ידי חובתו. \u0003יכול אפילו עשיר שהביא קרבן עני\u0004 יצא — \u0003תלמוד לומר: \"זאת\"\u0004 — למעט.","ושואלים: \u0003ונילף מינה\u0004 \u0005[ושנלמד ממנה]\u0006 מדין המצורע גם לקרבנות אחרים שיש בהם חילוק בין עני לעשיר! ודוחים: \u0003מיעט רחמנא\u0004 \u0005[מיעטה התורה]\u0006 ואמרה במצורע \u0003\"ואם דל הוא\"\u0004 (ויקרא יד, כא), להדגיש כי רק \"הוא\" — המצורע יש בו דין זה, אבל לא לאחרים.","\u0003קשר\u0004 הכהן \u0003לשון של זהורית\u0004 (צמר סרוק הצבוע אדום) \u0003בראש שעיר המשתלח, והעמידו כנגד בית שילוחו\u0004 סמוך לשער שדרכו הוא נשלח, \u0003ולנשחט כנגד בית שחיטתו.\u0004","\u0003בא לו אצל פרו\u0004 בפעם \u0003שניה, וסומך שתי ידיו עליו ומתודה, וכך היה אומר: \"אנא השם! עויתי פשעתי חטאתי לפניך אני וביתי ובני אהרן עם קדושך. אנא השם! כפר נא לעונות ולפשעים ולחטאים שעויתי ושפשעתי ושחטאתי לפניך אני וביתי ובני אהרן עם קדושך, ככתוב בתורת משה עבדך: 'כי ביום הזה יכפר עליכם לטהר אתכם מכל חטאתיכם לפני ה' תטהרו'\"\u0004 (ויקרא טז, ל) \u0003והן\u0004 הכהנים והעם שהיו בעזרה \u0003עונין אחריו\u0004 עם שמיעת השם: \u0003\"ברוך שם כבוד מלכותו לעולם ועד\".\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: מה ששנינו במשנה כי \u0003\"ולנשחט\u0004 כנגד בית שחיטתו\u0003\",\u0004 האם על ענין ה\u0003קשירה קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 מוסב\u0005],\u0006 שקושרים לנשחט לשון של זהורית כנגד בית שחיטתו \u0003או\u0004 שמא על ענין ה\u0003העמדה\u0004 שלו כנגד בית שחיטתו \u0003קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 מוסב\u0005]?\u0006","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יוסף\u0004 בברייתא: \u0003קשר לשון של זהורית בראש שעיר המשתלח, והעמידו כנגד בית שילוחו, ולנשחט כנגד בית שחיטתו\u0004 כדי \u0003שלא יתערב זה בזה ולא יתערב באחרים.\u0004","ומעתה ננסה להבין; \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי על ה\u0003קשירה קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 מוסב\u0005]\u0006 שגם לנשחט קשרו לשון זהורית וקשירה זו היתה על צוארו — \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן הדבר\u0005].\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שלענין \u0003העמדה קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 מוסב\u0005],\u0006 \u0003נהי דבחבריה לא מיערב\u0004 \u0005[אם אמנם שבחבירו\u0006 בשעיר המשתלח \u0005אינו מתערב]\u0006 \u0003דהאי קטיר ביה והאי לא קטיר ביה\u0004 \u0005[שזה קשורה בו\u0006 לשון זהורית \u0005וזה אין קשורה בו],\u0006 אולם הרי \u0003באחריני מיהת מיערב\u0004 \u0005[באחרים על כל פנים הוא מתערב]\u0006 שהרי אין בו סימן היכר לעצמו! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד ממנה]\u0006 כי מה שאמרו כנגד בית שחיטתו על ה\u0003קשירה קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 מוסב\u0005]\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר ר' יצחק: שתי\u0004 סוגי \u0003לשונות\u0004 של זהורית \u0003שמעתי\u0004 בהן הלכות, \u0003אחת\u0004 מהן \u0003של פרה\u0004 אדומה (\"שני תולעת\". במדבר יט, ו) \u0003ואחת של שעיר המשתלח,\u0004 ושמעתי כי \u0003אחת\u0004 מהן \u0003צריכה שיעור, ואחת אינה צריכה שיעור. ולא ידענא הי מיניהו\u0004 \u0005[ואין אני יודע איזו מהן].\u0006","\u0003אמר רב יוסף: ניחזי אנן\u0004 \u0005[נראה אנחנו],\u0006 כלומר: נעיין בדבר בעצמנו ונגיע למסקנה, ונאמר: לשון ש\u0003ל שעיר המשתלח דבעי\u0004 \u0005[שצריכה]\u0006 \u0003חלוקה,\u0004 שהרי חולקין אותה ומחציתה נקשרת בין קרניו של השעיר ומחציתה בסלע — \u0003בעי\u0004 \u0005[צריכה]\u0006 \u0003שיעור,\u0004 אבל \u0003של פרה דלא בעי\u0004 \u0005[שאינה צריכה]\u0006 \u0003חלוקה לא בעי\u0004 \u0005[אינה צריכה]\u0006 \u0003שיעור.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רמי בר חמא: דפרה נמי\u0004 \u0005[גם כן]\u0006 \u0003בעי\u0004 \u0005[צריכה]\u0006 \u0003כובד\u0004 שתהא כבידה ותיפול בתוך האש ממש, ואם כן יש לומר שצריכה שיעור! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: כובד — תנאי\u0004 \u0005[מחלוקת תנאים]\u0006 \u0003היא\u0004 אם צריכה לשון זו כובד,","ומצד שני ברור כי של \u0003פרה לא בעי\u0004 \u0005[אינה צריכה]\u0006 \u0003חלוקה. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003כיצד הוא עושה\u0004 בשריפת הפרה \u0003כורכן\u0004 את עץ הארז והאזוב שציוותה התורה לשרוף עם הפרה \u0003בשירי לשון\u0004 של זהורית, ומשמע מכאן שמחלקים את לשון הזהורית, חלק לכריכה וחלק לשריפה בלא כריכה! ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 לא שכורכם בשיירי לשון, שמובנו, שצריכה ליחלק לשנים, אלא כורכן \u0003בזנב לשון,\u0004 בקצה הצר של לשון הזהורית ולא בכולה, ואין ללמוד מכאן שלשון זו צריכה חלוקה.","\u0003אמר ר' חנין אמר רב: עץ ארז ושני תולעת\u0004 של פרה אדומה \u0003שקלטתן שלהבת\u0004 ונשרפו באויר מחוץ לשריפת גוף הפרה — \u0003כשרה. מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003נתהבהב הלשון\u0004 של זהורית באש ולא נשרף עם האפר — \u0003מביא לשון אחר ומקדש\u0004 ושורפו שם!","\u0003אמר אביי: לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003כאן\u0004 מדובר באש \u0003בקולחת\u0004 שיוצאת הלהבה ופורצת החוצה, ואם נשרפה הלשון במרחק צריכים לשון אחרת. ו\u0003כאן\u0004 מדובר באש \u0003נכפפת\u0004 קטנה ונמוכה, ולשון זהורית נשרפת סמוך לאפר שריפת הפרה, ואין צורך שתהיה ממש בתוך האפר.","\u0003רבא אומר: כובד תנאי\u0004 \u0005[מחלוקת תנאים]\u0006 \u0003היא,\u0004 אם הוא נחוץ. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003למה כורכן\u0004 לעץ הארז והאזוב \u0003כדי שיהיו כולן באגודה אחת,\u0004 שהרי הוזכרו יחד בתורה, אלו \u0003דברי רבי. ר' אלעזר בר' שמעון אומר: כדי שיהא בהן כובד, ויפלו לתוך שריפת הפרה.\u0004 הרי שחלקו תנאים אלה אם נחוץ כובד בלשון.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: שלש לשונות\u0004 של זהורית \u0003שמעתי\u0004 בהן הלכות; \u0003אחת של פרה ואחת של שעיר המשתלח, ואחת של מצורע.\u0004 ושמעתי כי \u0003אחת\u0004 מהן צריך שתהיה \u0003משקל עשרה זוז, ואחת משקל שני סלעים\u0004 (שמונה זוז) \u0003ואחת משקל שקל\u0004 (שני זוזים) \u0003ואין לי לפרש\u0004 איזו מהן הקטנה ואיזו הגדולה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003פירשה משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יונתן\u0004 מה צריך לכל דבר,"],["לשון זהורית \u0003של פרה משקל עשרה זוז, ושל שעיר המשתלח משקל שני סלעים\u0004 שהם שמונה זוז, \u0003ושל מצורע משקל שקל.\u0004","ועוד \u0003אמר ר' יוחנן: פליגי בה\u0004 \u0005[חלוקים\u0006 בשאלה \u0005זו]\u0006 \u0003ר' שמעון בן חלפתא ורבנן\u0004 \u0005[וחכמים]\u0006 לענין לשון של זהורית \u0003בפרה, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 שהיא \u0003משקל עשרה\u0004 זוז, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 שהיא \u0003משקל שקל. וסימניך\u0004 לזכרון שלא תטעה לומר שאחד מהם אמר שני סלעים \u0003—\u0004 הביטוי מן המשנה \u0003\"אחד המרבה ואחד הממעיט\",\u0004 ששימושו כאן לומר שהמחלוקת היא קיצונית, שאף אחד מהם לא נתן את השיעור הבינוני, אלא או הגדול שבשיעורים או הקטן שבהם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי ירמיה מדיפתי לרבינא: לא בפרה פליגי\u0004 \u0005[נחלקו]\u0006 לענין זה, \u0003אלא\u0004 לענין לשון של \u0003שעיר המשתלח פליגי\u0004 \u0005[נחלקו]\u0006. \u0003וההוא יומא\u0004 \u0005[ואותו יום\u0006 שהיתה בו מחלוקת\u0005]\u0006 \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 החכם \u0003רביא בר קיסי, ואנחו\u0004 \u0005[והניחו]\u0006 \u0003בה סימנא\u0004 \u0005[סימן]\u0006 בהלכה זו וקשרוה בשמו: \u0003רביא בר קיסי מכפר כשעיר המשתלח,\u0004 שאמרו שמיתת צדיקים מכפרת על הדור.","\u0003אמר ר' יצחק:\u0004 ב\u0003שתי שחיטות שמעתי\u0004 הלכה לענין שחיטתן בזר, \u0003אחת של פרה\u0004 אדומה, \u0003ואחת של פרו\u0004 של כהן גדול ביום הכיפורים, ושמעתי ש\u0003אחת\u0004 מהם \u0003כשרה\u0004 שחיטתה \u0003בזר, ואחת פסולה\u0004 שחיטתה \u0003בזר,\u0004 אלא נשחטת על ידי כהן בלבד, \u0003ולא ידענא הי מינייהו\u0004 \u0005[ואינני יודע איזו מהן].\u0006","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר: \u0003שחיטת פרה\u0004 אדומה \u0003ופרו\u0004 של כהן גדול ביום הכיפורים, נחלקו בכך \u0003רב ושמואל. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: פרה\u0004 אדומה שנשחטה בזר \u0003פסולה,\u0004 ואילו \u0003פרו\u0004 של כהן גדול שנשחט בזר — \u0003כשרה. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: פרו — פסולה, פרה — כשרה.\u0004","ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 כי \u0003רב הוא\u0004 ש\u0003אמר פרה פסולה\u0004 בזר, ש\u0003אמר ר' זירא: שחיטת פרה בזר — פסולה. ואמר רב עלה\u0004 \u0005[על\u0006 הלכה \u0005זו]\u0006 של ר' זירא כהסבר: שהרי בשחיטת הפרה האדומה נזכר שמו של \u0003\"אלעזר\u0004 הכהן\u0003\"\u0004 (\"ונתתם אותה אל אלעזר הכהן והוציא אותה אל מחוץ למחנה ושחט אותה לפניו\". במדבר יט, ג) \u0003ו\u0004מיד לאחר מכן לשון \u0003\"חוקה\"\u0004 (\"זאת חוקת התורה\". במדבר יט, ב) \u0003שנינו בה,\u0004 וכל מקום שנאמר בו \"חוקה\" משמעו: כן הוא הדבר, ואין לשנות ממנו.","הרי שלדברי רב שחיטת פרה אדומה בזר — פסולה. ושואלים: \u0003ו\u0004לשיטת \u0003רב מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003פרה\u0004 אדומה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בה \u0003\"אלעזר\" ו\"חוקה\",\u0004 הרי בענין \u0003פרו\u0004 של הכהן הגדול ביום הכיפורים \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 גם \u0003\"אהרן\"\u0004 שהוא כהן גדול (\"והקריב אהרן את פר החטאת אשר לו וכיפר בעדו ובעד ביתו ושחט את פר החטאת אשר לו\". ויקרא טז, יא) וגם \u0003\"חוקה\"\u0004 (\"והיתה זאת לכם לחוקת עולם\". במדבר יט, לד)!","ומשיבים: בכל זאת \u0003שחיטה לאו\u0004 \u0005[לא]\u0006 \u0003עבודה היא,\u0004 שאינה נחשבת כעבודה המיוחדת לכהנים במעשה הקרבנות, ואף שהוזכר \"אהרן\" והוזכרה \"חוקה\" לומר שעבודה זו היום רק בכהן גדול — הרי זה רק בדברים שהם עבודת הכהנים, ושחיטה אינה בכלל עבודת כהן. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 ב\u0003פרה\u0004 אדומה \u0003נמי\u0004 \u0005[גם כן]\u0006 נאמר ששחיטה אינה נחשבת כעבודה! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 דין ה\u0003פרה\u0004 ש\u0003קדשי בדק הבית היא.\u0004 שפרה אדומה אינה נחשבת כקרבן, אלא כהקדש ממין אחר, כעין הקדש בדק הבית, ולכן אין דיני הקרבנות חלים עליה.","ומקשים: \u0003ולאו כל דכן\u0004 \u0005[ולא כל שכן]\u0006 \u0003הוא?\u0004 אם בקדשי מזבח אין שחיטה נחשבת כעבודה — כל שכן בקדשי בדק הבית! ומשיבים: \u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: מידי דהוה\u0004 \u0005[כמות שהוא\u0006 הדבר\u0005]\u0006 \u0003במראות נגעים\u0004 של מצורע \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003עבודה היא,\u0004 ובכל זאת \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003כהונה,\u0004 שרק כהן רשאי לטמא ולטהר, ומכאן שיתכן שאף דבר שאינו מעבודות הקודש צריך להיעשות על ידי כהן.","ושואלים: \u0003ולשמואל,\u0004 ש\u0003אמר\u0004 שחיטת \u0003פרו\u0004 של הכהן הגדול בזר \u0003פסולה, מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003פרו דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"אהרן\" ו\"חוקה\", פרה\u0004 אדומה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 בה: \u0003\"אלעזר\" ו\"חוקה\"!\u0004 ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושחט אותה לפניו\"\u0004 (במדבר יט, ג) ודיוק המילים משמעו: \u0003שיהא זר שוחט ואלעזר רואה.\u0004","ושואלים: \u0003ורב,\u0004 מה למד הוא מכאן? ומשיבים: לדעתו פירוש הדברים \u0003שלא יסיח דעתו\u0004 מן הפרה משעת שחיטה, שהיסח הדעת פוסל בכל מקום שיש בו חובת טהרה. ושואלים: \u0003ושמואל,\u0004 הלכה זו \u0003שלא יסיח דעתו מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצאת,\u0006 נלמדת, \u0005לו]\u0006 ממה שנאמר: \u0003\"ושרף את הפרה לעיניו\"\u0004 (במדבר יט, ה).","ושואלים: \u0003ורב\u0004 מה לומד הוא מפסוק זה? לדעתו יש צורך בפסוק \u0003חד\u0004 \u0005[אחד]\u0006 שהיסח הדעת אסור \u0003בשחיטה וחד\u0004 \u0005[ואחד,\u0006 הפסוק האחר\u0005]\u0006 בא ללמד שהיסח הדעת אסור \u0003בשריפה,\u0004","\u0003וצריכא\u0004 \u0005[ונצרכו\u0006 שניהם\u0005].\u0006 \u0003דאי כתב רחמנא\u0004 \u0005[שאילו\u0006 היתה \u0005כותבת התורה]\u0006 \u0003בשחיטה\u0004 בלבד, הייתי אומר שיש להמנע מהיסח הדעת, משום ש\u0003תחילת עבודה היא — אבל שריפה אימא\u0004 \u0005[אמור]\u0006 כי \u0003לא\u0004 צריכה היא השגחה ונתינת דעת, לכן \u0003צריכא\u0004 \u0005[נצרכה].\u0006 \u0003ואי כתב רחמנא\u0004 \u0005[ואם\u0006 היתה \u0005כותבת התורה]\u0006 \u0003בשריפה\u0004 בלבד, הייתי אומר: \u0003משום דהשתא\u0004 \u0005[שעכשיו]\u0006 \u0003הוא דמתכשרא\u0004 \u0005[שמתכשרת]\u0006 ה\u0003פרה\u0004 למטרתה \u0003אבל שחיטה אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 תיפסל בהיסח הדעת, על כן \u0003צריכא\u0004 \u0005[נצרכה].\u0006","ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט את מה]\u0006 שאם צריכים שני פסוקים להדגיש בשתי עבודות אלה, מה בא הדבר למעט שהוא אינו נפסל בהיסח הדעת? \u0003אילימא למעוטי\u0004 \u0005[אם תאמר למעט]\u0006 \u0003אסיפת אפרה\u0004 לאחר השריפה \u0003ומילוי מים\u0004 חיים בתוך האפר \u0003לקידוש\u0004 ועירובן יחד, שמעתה ראויה היא להזות ולטהר, שיהיו עבודות אלו כשרות על אף היסח הדעת,"],["הלא \u0003\"למשמרת למי נדה\"\u0004 (במדבר יט, ט) \u0003כתיב\u0004 \u0005[נאמר],\u0006 לומר שצריכים שמירה עד שיזה מהם. \u0003אלא למעוטי\u0004 \u0005[למעט]\u0006 \u0003השלכת עץ ארז ואזוב ושני תולעת\u0004 לתוך השריפה, \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003גופה\u0004 של ה\u0003פרה נינהו\u0004 \u0005[הם]\u0006 ולכן אינם צריכים נתינת דעת מתמדת.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים אחרים בדבר \u0003שחיטת פרה בזר, ר' אמי אמר: כשרה, ור' יצחק נפחא\u0004 \u0005[הנפח]\u0006 \u0003אמר: פסולה. עולא אמר: כשרה, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר: \u0003פסולה.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' יהושע בר אבא לסיועיה\u0004 \u0005[לסייע]\u0006 לדעת \u0003רב\u0004 שאמר ששחיטתה פסולה בזר, מברייתא זו: \u0003אין לי אלא הזאת מימיה\u0004 של פרה אדומה \u0003שאין כשרין באשה כבאיש, ואין כשרין אלא ביום.\u0004","\u0003מניין לרבות שחיטתה וקבלת דמה והזאת דמה ושריפתה והשלכת עץ ארז ואזוב ושני תולעת\u0004 שאף הם כשרים רק באיש ורק ביום — \u0003תלמוד לומר: \"תורה\"\u0004 (\"זאת חוקת התורה\". במדבר יט, ב) להדגיש שהוראה אחת ומנהג אחיד לכל מעשיה. \u0003יכול שאני מרבה אף אסיפת אפרה, ומילוי מים\u0004 חיים \u0003וקידוש\u0004 המים על ידי נתינתם בתוך האפר \u0003— תלמוד לומר: \"זאת\"\u0004 (במדבר יט, ב), שהיא לשון מיעוט ומיעט את אלו.","ושואלים: \u0003ומה ראית לרבות את אלו\u0004 ולומר שאין לשנות בהם, \u0003ולהוציא את אלו? אחר שריבה הכתוב ומיעט\u0004 שהרי לשון הכתוב יש בה צד ריבוי וצד מיעוט, \u0003אמרת\u0004 (אומר אתה)? \u0003הרי אנו למדין כולן מהזאת מימיה, מה הזאת מימיה אינן כשרין באשה כבאיש ואין כשרין אלא ביום — אף אני אביא שחיטתה וקבלת דמה, והזאת דמה, ושריפתה, והשלכת עץ ארז ואזוב ושני תולעת\u0004","\u0003הואיל ואין כשרין באשה כבאיש — אין כשרין אלא ביום. ומוציא אני אסיפת אפרה ומילוי מים וקידוש הואיל וכשרין באשה כבאיש כשרין נמי\u0004 \u0005[גם כן]\u0006 \u0003ביום ובלילה.\u0004","ושואלים: \u0003והאי מאי תיובתא\u0004 \u0005[וזו מה קושיה היא],\u0006 כלומר מה ההוכחה מברייתא זו שעסקה בענין כשרות האשה, לנושא הדיון שלנו בענין כשרות הזר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003מדפסולין\u0004 \u0005[כיון שפסולין]\u0006 \u0003באשה פסולין נמי\u0004 \u0005[גם כן]\u0006 \u0003בזר,\u0004 אולם מכאן אין ראיה, שהרי \u0003הזאת מימיה תוכיח\u0004 שלדעת הכל \u0003פסולין באשה וכשרין בזר!\u0004","\u0003אמר אביי: היינו תיובתיה\u0004 \u0005[זו היא קושייתו]\u0006 וכך יש להבינה: \u0003אשה מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסורה היא לעשות דברים אלה — משום שנאמר \u0003\"אלעזר\"\u0004 והתנא מדייק משם כי אלעזר שהוא זכר דווקא \u0003ולא אשה,\u0004 ואם כן \u0003זר נמי\u0004 \u0005[גם כן]\u0006 אפשר למעט באותה דרך, שהרי נאמר \u0003אלעזר\u0004 שהוא כהן \u0003ולא זר.\u0004","כיון שעסקנו בדין הפרה האדומה, מביאים עוד עניינים בנושא זה. \u0003אמר עולא: כל הפרשה כולה\u0004 של פרה אדומה יש להבינה בשני אופנים ואינה יכולה להדרש באופן אחד, אלא, דברים שהם \u0003משמע\u0004 בפסוק אחד \u0003מוציא מיד\u0004 דברים אחרים ש\u0003משמע\u0004 בפסוקים שלפניו או שלאחריו, או מדין של אדם אחר, ואילו דברים אחרים שהם \u0003משמע\u0004 מלשון או מתוכן הפסוקים אינם באים להוציא אלא אדרבא \u0003ממילא\u0004 יש להבינם ולקיימם כמו שהם. כיצד?","נאמר: \u0003\"ונתתם אתה אל אלעזר הכהן\"\u0004 (במדבר יט, ג) — לומר שדווקא \u0003אותה\u0004 פרה אדומה ראשונה \u0003לאלעזר\u0004 שהיה סגן כהן גדול \u0003ולא לדורות לאלעזר,\u0004 הרי זה משמע מוציא מיד משמע. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שבניגוד לפרה הראשונה שנעשתה על ידי אלעזר שהיה סגן — \u0003לדורות\u0004 תיעשה הפרה \u0003בכהן גדול\u0004 דווקא, \u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]\u0006 כי אף שהראשונה נעשתה על ידי הסגן — \u0003לדורות\u0004 תיעשה הפרה אפילו \u0003בכהן הדיוט.\u0004","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאמר]\u0006 כי \u0003לדורות\u0004 יכולה הפרה להיעשות אף \u0003בכהן הדיוט — שפיר\u0004 \u0005[יפה,\u0006 מובן הדבר\u0005],\u0006 כי אם אין הדבר נעשה בסגן דווקא יעשה בכל כהן. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאמר]\u0006 כי \u0003לדורות\u0004 אינה נעשית אלא \u0003בכהן גדול מנא ליה\u0004 \u0005[מנין לו]\u0006 שבכהן גדול דווקא? ומשיבים: \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שוה \u0003\"חקה\" \"חקה\" מיום הכפורים,\u0004 שכשם שעבודת יום הכיפורים היא בכהן גדול דווקא, אף עבודת פרה אדומה בכהן גדול דווקא.","ועוד נדרשת הפרשה בדרך משמע ממילא: \u0003\"והוציא אתה\"\u0004 (במדבר יט, ג) לדקדק \u0003שלא יוציא\u0004 פרה \u0003אחרת עמה. כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003לא היתה פרה רוצה לצאת\u0004 מעצמה ורוצים להוציא עימה פרה אחרת שתלך עימה — \u0003אין מוציאין עמה\u0004 פרה \u0003שחורה — שלא יאמרו שחורה שחטו, ואין מוציאין עמה\u0004 פרה \u0003אדומה\u0004 אחרת \u0003שלא יאמרו שתים שחטו\u0004 בבת אחת, וכל מלאכה אחרת הנעשית בשעת עשיית הפרה — פוסלת אותה. \u0003רבי אומר: לא מן השם הוא זה,\u0004 כלומר: לא מטעם זה, \u0003אלא משום שנאמר: \"אתה\"\u0004 שמשמעו \u0003לבדה\u0004 ולא אחרת עימה, וגזירת הכתוב היא שבכל מקרה אסור.","ושואלים: \u0003ותנא קמא\u0004 \u0005[\u0006ולדעת \u0005התנא הראשון]\u0006 יש לשאול: \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 במפורש \u0003\"אתה\"\u0004 ומה למד הוא מדיוק לשון זה? ומשיבים: \u0003מאן תנא קמא\u0004 \u0005[מי הוא התנא הראשון] —\u0006 \u0003ר' שמעון היא, דדריש טעמיה דקרא\u0004 \u0005[שהוא דורש את טעמו של הכתוב]\u0006 ופוסק הלכה על פי מה שהוא מבין שהוא טעמה של אותה הלכה. והכתוב המדגיש \"אותה\" יש להסבירו: שמוציאים אותה לבדה, כדי שלא להביא לטעות. ושואלים: אם כן \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם,\u0006 הלכה למעשה\u0005],\u0006 מה טעמה של הלכה זו? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם,\u0006 הבדל מעשי\u0005],\u0006"],["כגון: \u0003דאפיק\u0004 \u0005[שהוציא]\u0006 \u0003חמור בהדה\u0004 \u0005[עמה]\u0006 שלדעת החושש מן הטעות אין כאן מקום לחשש, ואילו לדעת המדגיש מצד גזירת הכתוב, אם כן אפילו הוצאת חמור עימה אסורה.","ומה שנאמר: \u0003\"ושחט אתה\"\u0004 (במדבר יט, ג), משמע אותה ולא אחרת — \u0003שלא ישחוט אחרת עמה.\u0004 ומה שנאמר: \u0003\"לפניו\"\u0004 לדעת \u0003רב,\u0004 כוונתו \u0003שלא יסיח דעתו ממנה\u0004 ותהא כלפניו תמיד, \u0003לשמואל\u0004 בא הדבר ללמד \u0003שיהא זר שוחט ואלעזר,\u0004 הוא הכהן \u0003רואה.\u0004","מה שנאמר: \u0003\"ולקח אלעזר הכהן מדמה באצבעו\"\u0004 (במדבר יט, ד), \u0003לשמואל\u0004 פסוק זה בא \u0003לאהדוריה\u0004 \u0005[להחזירו]\u0006 \u0003לאלעזר,\u0004 שהרי לדעתו יכול גם זר לעשות את המלאכות הקודמות, ולכן אמר שהזאת הדם רק על ידי אלעזר, כלומר: כהן. \u0003לרב הוי\u0004 \u0005[הרי זה]\u0006 \u0003מיעוט אחר מיעוט\u0004 שהרי גם העבודות הקודמות צריכות להיעשות על ידי אלעזר דווקא. ולפי כללי מדרש ההלכה \u0003אין מיעוט אחר מיעוט אלא לרבות,\u0004 ללמדנו: לאו דווקא אלעזר, אלא \u0003אפילו כהן הדיוט\u0004 מותר לו לעשות זאת.","נאמר: \u0003\"ולקח הכהן עץ ארז ואזוב ושני תולעת\"\u0004 (במדבר יט, ו), \u0003לשמואל\u0004 בא הדבר ללמד ש\u0003אפילו בכהן הדיוט\u0004 אפשר לעשות זאת. ואילו \u0003לרב\u0004 גם כן \u0003איצטריך\u0004 \u0005[הוצרך],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003כיון דלאו\u0004 \u0005[שלא]\u0006 מ\u0003גופה\u0004 של ה\u0003פרה נינהו\u0004 \u0005[הם],\u0006 אם כן \u0003לא ליבעי\u0004 \u0005[יצטרכו]\u0006 \u0003כהן\u0004 כלל ואפילו זר יהא כשר לכך, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינו נעשה אלא על ידי כהן.","נאמר: \u0003\"וכבס בגדיו הכהן\"\u0004 (במדבר יט, ז), הדגשה זו באה לומר: הכהן \u0003בכיהונו,\u0004 כשהוא לבוש בגדי כהונה וראוי לעבודה. ומה שנאמר: \u0003\"וטמא הכהן עד הערב\"\u0004 (במדבר יט, ז) — ללמד שמלאכת הפרה אינה נעשית אלא על ידי \u0003כהן בכיהונו\u0004 (כשהוא לבוש בגדי כהונה) אף \u0003לדורות.\u0004","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאמר]\u0006 \u0003לדורות בכהן הדיוט — שפיר\u0004 \u0005[יפה,\u0006 מוטב\u0005]\u0006 שרק בפעם הראשונה נעשה על ידי סגן הכהן, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאמר]\u0006 \u0003לדורות בכהן גדול, השתא כהן גדול בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003בכיהונו מיבעיא\u0004 \u0005[צריכה\u0006 לומר\u0005]\u0006 שצריך? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 נצרכה, כי פעמים \u0003מילתא דאתיא\u0004 \u0005[\u0006ש\u0005דבר הבא,\u0006 הנלמד\u0005]\u0006 \u0003בקל וחומר טרח וכתב לה קרא\u0004 \u0005[אותו הכתוב]\u0006 במפורש.","נאמר: \u0003\"ואסף איש טהור את אפר הפרה והניח\"\u0004 (במדבר יט, ט), \u0003\"איש\"\u0004 שנאמר, ודאי \u0003להכשיר את הזר\u0004 בא, שאף הוא ראוי לאסיפת האפר. \u0003\"טהור\" — להכשיר\u0004 אף \u0003את האשה, \"והניח\"\u0004 כוונתו — \u0003מי שיש בו דעת להניח,\u0004 שהוא מניח מצד דעת עצמו, \u0003יצאו חרש שוטה וקטן שאין בהן דעת להניח.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה בענין זה: \u0003הכל כשרין לקדש\u0004 כלומר לשפוך מים לאפר פרה אדומה, \u0003חוץ מחרש שוטה וקטן. ר' יהודה מכשיר בקטן, ופוסל באשה ובאנדרוגינוס.\u0004","ומסבירים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה טעמם של חכמים] —\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולקחו לטמא מעפר שרפת החטאת\"\u0004 (במדבר יט, יז) וכוונתו: \u0003הנך דפסלי\u0004 \u0005[אותם הפסולים]\u0006 \u0003לך באסיפה\u0004 של האפר — \u0003פסלי\u0004 \u0005[פסולים]\u0006 \u0003לך בקידוש\u0004 שלו, \u0003והנך דאכשרי\u0004 \u0005[ואלו שהכשרתי]\u0006 \u0003לך באסיפה\u0004 של האפר \u0003— אכשרי\u0004 \u0005[הכשרתי]\u0006 \u0003לך\u0004 אף \u0003בקידוש\u0004 שלו.","\u0003ור' יהודה\u0004 מה משיב הוא לטענה זו? לדעתו \u0003אם כן לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 כהמשך לפסוקים הקודמים \u0003\"ולקח\"\u0004 בלשון יחיד, \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003\"ולקחו\"\u0004 — ללמד ש\u0003אפילו קטן דפסלי לך התם\u0004 \u0005[שפסלתי לך שם]\u0006 לענין אסיפת האפר, \u0003הכא\u0004 \u0005[כאן]\u0006 לגבי קידושו — \u0003כשר.\u0004","ושואלים: \u0003אשה מנא ליה\u0004 \u0005[מנין לו]\u0006 לר' יהודה שהיא פסולה? — שנאמר: \u0003\"ונתן\"\u0004 בלשון זכר — \u0003ולא \"ונתנה\". ורבנן\u0004 מה טוענים הם כנגד הסבר זה? הם סבורים: \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 \u0003\"ולקח ונתן\", הוה אמינא עד דשקיל חד ויהיב חד\u0004 \u0005[הייתי אומר\u0006 שאין הדבר כשר \u0005עד שלוקח\u0006 אדם \u0005אחד ונותן\u0006 למים \u0005אחד,\u0006 אותו אדם\u0005]\u0006 לכך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"ולקחו\" —\u0004","ללמד שאין הלקיחה והנתינה צריכים להיעשות על ידי אותו אדם דווקא. \u0003ואי כתב רחמנא\u0004 \u0005[ואם\u0006 היתה \u0005כותבת התורה]\u0006 לשון אחידה \u0003\"ולקחו ונתנו\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003עד דשקלי תרי ויהבי תרי\u0004 \u0005[עד שלוקחים שנים ונותנים שנים],\u0006 שתהא המצוה בשנים דווקא, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"ולקחו\" \"ונתן\"\u0004 (במדבר יט, יז), לומר ש\u0003אפילו\u0004 אם \u0003שקלי תרי ויהיב חד\u0004 \u0005[אספו שנים ונתן אחד],\u0006 גם כשר.","נאמר: \u0003\"ולקח אזוב וטבל במים איש טהור\"\u0004 (במדבר יט, יח), \u0003לרבנן\u0004 \u0005[\u0006לשיטת \u0005חכמים]\u0006 ההדגשה היא: \u0003איש ולא אשה.\u0004 ואילו המילה \u0003\"טהור\"\u0004 באה \u0003להכשיר\u0004 למלאכה זו אף \u0003את הקטן, ולר' יהודה: \"איש\"\u0004 בא למעט — \u0003ולא קטן, \"טהור\" — להכשיר את האשה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו במשנה במסכת פרה: \u0003הכל כשרין להזות\u0004 מי חטאת \u0003חוץ מטומטום ואנדרוגינוס ואשה, וקטן שיש בו דעת אשה מסייעתו ומזה.\u0004"],["\u0003ולא פליג\u0004 \u0005[חולק]\u0006 \u0003ר' יהודה,\u0004 משמע שאף הוא מסכים לכך!","\u0003אמר אביי: כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שבכל פרשה זו \u0003משמע מוציא מיד משמע ומשמע ממילא,\u0004 כלומר יש פסוקים שיש להבינם כמשמעם ויש כאלה שאפשר לדייק בהם ולהוציא מכללם דברים אחרים וכיון שכך ודאי שלא פירש ר' יהודה כדעת חכמים, ובודאי \u0003פליג\u0004 \u0005[חולק]\u0006 ולא היה צריך לומר לנו כן במפורש.","נאמר: \u0003\"והזה הטהר על הטמא\"\u0004 (במדבר יט, יט), ולכאורה הדגשת הכתוב במה שאמר \u0003\"טהר\"\u0004 מיותרת \u0003—\u0004 אלא \u0003מכלל שהוא טמא,\u0004 כלומר: שמדובר באופן שהיה טמא בו ביום ורק עכשיו נטהר, ואם כן הרי איננו טהור מכל צד, שהרי עד שתעריב שמשו עדיין הוא טבול יום — אלא \u0003לימד על טבול יום שכשר בפרה,\u0004 בעשייתה ובהזאתה.","\u0003אמר ר' אסי: כי הוו בה\u0004 \u0005[כאשר היו עוסקין בה]\u0006 \u0003ר' יוחנן וריש לקיש\u0004 בפרשת פרה בתורה \u0003לא מסקי מינה\u0004 \u0005[לא היו מעלין ממנה],\u0006 לא היו מחדשים בה, \u0003אלא כמאי דמסיק תעלא מבי כרבא\u0004 \u0005[כמו שמעלה השועל מן השדה החרוש]\u0006 שהוא ביטוי לדבר מועט ביותר, שכמעט אינו ניכר. \u0003אלא אמרי\u0004 \u0005[\u0006היו \u0005אומרים]:\u0006 \u0003\"משמע מוציא מיד משמע ומשמע ממילא\",\u0004 וכך נדרשת כל הפרשה, וכיון שאין אחידות בדרשה אי אפשר לחדש בה דברים מדעתנו.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003ר' יוחנן: כל השחיטות כשירות בזר, חוץ משל פרה\u0004 אדומה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: פוק תני לברא\u0004 \u0005[לך ושנה בחוץ],\u0006 כלומר: זו איננה משנה הראויה להילמד בבית המדרש, כי \u0003לא מצינו\u0004 בשום מקום \u0003שחיטה בזר\u0004 שהיא \u0003פסולה.\u0004","ומעירים: \u0003ור' יוחנן\u0004 כל כך החזיק בשיטתו זו, ש\u0003לא מיבעיא לתנא דלא ציית\u0004 \u0005[לא די שלחוזר המשניות לא הקשיב]\u0006 \u0003אלא אפילו לרביה\u0004 \u0005[לרבו]\u0006 \u0003לא ציית\u0004 \u0005[הקשיב],\u0006 כלומר, אף שרבו החזיק בשיטה אחרת, הוא לא קיבל דבריו. ש\u0003אמר ר' יוחנן משום\u0004 (משמו) של \u0003ר' שמעון בן יהוצדק: שחיטת פרה בזר פסולה.\u0004 והוסיף ר' יוחנן: \u0003ואני אומר: כשירה,\u0004 כי \u0003לא מצינו שחיטה שפסולה בזר.\u0004","שנינו במשנה: \u0003בא לו\u0004 הכהן \u0003אצל פרו\u0004 בפעם ה\u0003שניה\u0004 והתוודה. שואלים: \u0003מאי שנא\u0004 \u0005[מה,\u0006 במה \u0005שונה]\u0006 \u0003בוידוי ראשון שלא אמר\u0004 בשעת הוידוי: \u0003\"ובני אהרן עם קדושך\" ומאי שנא\u0004 \u0005[ומה\u0006 במה \u0005שונה]\u0006 \u0003בוידוי שני\u0004 ש\u0003אמר\u0004 בו: \u0003\"ובני אהרן עם קדושך\"?\u0004","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כך היא מדת הדין נותנת,\u0004 וכך ראוי — \u0003מוטב יבא זכאי ויכפר על החייב.\u0004 שלאחר שהתוודה והתכפר לו לעצמו, ראוי הוא להתוודות ולכפר על אחרים. \u0003ואל יבא חייב ויכפר על החייב\u0004 ולכן אינו מתוודה וידוי זה לכפרת בני אהרן עד שלא נתכפר עוונו שלו.","\u0003שחטו\u0004 הכהן את הפר \u0003וקבל במזרק את דמו, ונותנו למי שהוא ממרס\u0004 (בוחש) \u0003בו,\u0004 והוא הממרס עומד \u0003על הרובד\u0004 (שורת המרצפות) \u0003הרביעי שבהיכל,\u0004 ומירוס זה נעשה \u0003כדי שלא יקרוש\u0004 הדם עד שהכהן עושה עבודות אחרות. \u0003נטל מחתה\u0004 (כלי לגחלים) \u0003ועלה לראש המזבח ופנה גחלים\u0004 העליונות \u0003אילך ואילך וחותה\u0004 במחתה \u0003מן\u0004 הגחלים \u0003המעוכלות הפנימיות, וירד והניחה\u0004 את המחתה עם הגחלים \u0003על הרובד הרביעי שבעזרה.\u0004","ומעירים: ו\u0003בכל יום היה חותה\u0004 המקטיר את הקטורת במחתה \u0003של כסף, ומערה\u0004 (ושופך) משם את הגחלים \u0003בתוך\u0004 מחתה \u0003של זהב, והיום\u0004 יום הכיפורים היה הכהן הגדול \u0003חותה בשל זהב ובה היה מכניס.\u0004","\u0003בכל יום\u0004 היתה המחתה \u0003של ארבעת קבין, ומערה\u0004 את הגחלים שבתוכה \u0003לתוך\u0004 מחתה של \u0003שלשת קבין והיום חותה בשלשת קבין ובה היה מכניס. ר' יוסי אומר\u0004 בשינוי מה: \u0003בכל יום חותה בשל סאה\u0004 שהיא ששה קבין \u0003ומערה בתוך שלשת קבין, והיום חותה בשלשת קבין ובה היה מכניס.\u0004","ועוד שינוי: \u0003בכל יום היתה\u0004 המחתה \u0003כבדה, והיום קלה. בכל יום היתה ידה\u0004 (ידיתה) \u0003קצרה, והיום ארוכה\u0004 יותר כדי יוכל להסתייע אף בזרועו. \u0003בכל יום היתה זהבה ירוק והיום\u0004 היה זהבה מסיג שונה והיה צבעו \u0003אדום\u0004 שהוא קל יותר. אלו \u0003דברי ר' מנחם.\u0004","\u0003בכל יום מקריב\u0004 לקטורת \u0003פרס\u0004 (חצי מנה) קטורת \u0003בשחרית ופרס בין הערבים, והיום מוסיף\u0004 ומקטיר גם \u0003מלא חפניו\u0004 קטורת בקודש הקדשים. \u0003בכל יום היתה\u0004 הקטורת \u0003דקה\u0004 כמצווה בתורה, \u0003והיום דקה מן הדקה.\u0004","\u0003בכל יום כהנים עולין במזרחו של כבש ויורדין במערבו\u0004 שיהא הבדל בין עליה וירידה \u0003והיום כהן גדול עולה באמצע\u0004 הכבש \u0003ויורד באמצע. ר' יהודה אומר:\u0004 בכך לא היה שינוי, כי \u0003לעולם כהן גדול עולה באמצע ויורד באמצע\u0004 מפני כבודו.","\u0003בכל יום כהן גדול מקדש ידיו ורגליו מן הכיור\u0004 כשאר הכהנים \u0003והיום מן הקיתון של זהב\u0004 שלא יטרח. \u0003ר' יהודה אומר: לעולם כהן גדול מקדש ידיו ורגליו מן הקיתון של זהב\u0004 מפני כבודו.","\u0003בכל יום היו שם\u0004 על המזבח \u0003ארבע מערכות\u0004 (ערימות מסודרות) של עצים \u0003והיום חמש\u0004 מערכות, אלו \u0003דברי ר' מאיר. ר' יוסי אומר: בכל יום\u0004 היו \u0003שלש\u0004 מערכות עצים בלבד \u0003והיום ארבע. ר' יהודה אומר: בכל יום\u0004 היו \u0003שתים, והיום שלש.\u0004","על האמור במשנה שהיה כהן ממרס על הרובד הרביעי שבהיכל מקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וכל אדם לא יהיה באהל מועד\u0004 בבואו לכפר בקודש עד צאתו\u0003\"\u0004 (ויקרא טז, יז)! \u0003אמר רב יהודה: תני\u0004 \u0005[שנה]\u0006 רובד הרביעי \u0003של היכל,\u0004 כלומר לא בתוך ההיכל עצמו היה הכהן עומד, אלא מחוץ לו, שהיה מניח את המזרק על הרובד הרביעי שביציאה מן ההיכל כלפי חוץ.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"וכל אדם לא יהיה באהל מועד\"\u0004 (ויקרא טז, יז)"],["\u0003יכול אפילו בעזרה\u0004 לא יהא אדם עומד בשעת הקטרת הקטורת \u0003תלמוד לומר: \"באהל מועד\"\u0004 (ויקרא טז, יז), לומר: בתוך הבית עצמו אסור, אבל אין איסור שהייה בעזרה. \u0003אין לי אלא\u0004 שיש דין זה \u0003באהל מועד שבמדבר,\u0004 ב\u0003שילה ובית עולמים\u0004 (בבית המקדש, שקדושתו לעולם) \u0003מנין? תלמוד לומר: \"בקדש\"\u0004 (ויקרא טז, יז), משמע: בכל מקום הקודש, בכל מקום שיהא.","\u0003אין לי אלא בשעת הקטרה\u0004 שאסור להיות בהיכל, \u0003בשעת מתן דמים מנין? תלמוד לומר: \"בבאו לכפר\"\u0004 (ויקרא טז, יז) ואין כפרה אלא במתן דם. \u0003אין לי אלא\u0004 שאסור להיות שם בשעת \u0003כניסתו\u0004 של הכהן אל הקודש, בשעת \u0003יציאתו מנין? תלמוד לומר: \"עד צאתו\"\u0004 (ויקרא טז, יז).","נאמר בפסוק: \u0003\"וכפר בעדו ובעד ביתו ובעד כל קהל ישראל\"\u0004 (ויקרא טז, יז), ללמד: \u0003כפרתו קודמת לכפרת ביתו, כפרת ביתו קודמת לכפרת אחיו הכהנים, כפרת אחיו הכהנים קודמת לכפרת כל קהל ישראל.\u0004","ומעתה מפרשים ברייתא זו. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"אין לי אלא בשעת הקטרה\".\u0004 ושואלים: \u0003מאי משמע\u0004 \u0005[מה,\u0006 כיצד \u0005משמע]\u0006 דברים אלה בכתוב? שהרי אין כתוב זה מדבר אלא מענין הזאת הדם ולא מענין הקטרת הקטורת! \u0003אמר רבא, וכן אמר ר' יצחק בר אבדימי, וכן אמר ר' אלעזר: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכפר בעדו ובעד ביתו ובעד כל קהל ישראל\"\u0004 (ויקרא טז, יז) \u0003איזהו כפרה ששוה לו ולביתו ולאחיו הכהנים ולכל קהל ישראל,\u0004 שאין בה חילוק ממדרגה למדרגה כבשאר הקרבנות — \u0003הוי אומר זה הקטרת הקטורת.\u0004","ותוהים: והאם \u0003קטורת מכפרת?\u0004 שאכן נזכרה לשון כפרה בכתוב המדבר מענין הקרבנות, אולם האם קטורת שלא נזכר בה לשון זה, אף היא מכפרת? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דהא תני\u0004 \u0005[שהרי שנה]\u0006 \u0003ר' חנניא: למדנו לקטורת שמכפרת\u0004 ממה \u0003שנאמר: \"ויתן את הקטרת ויכפר על העם\"\u0004 (במדבר יז, יב) \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: על מה קטורת מכפרת — על לשון הרע,\u0004 ומדוע? — \u0003יבא דבר שבחשאי\u0004 הקטרת הקטורת הנעשית כבהסתר בתוך ההיכל, \u0003ויכפר על מעשה חשאי\u0004 של לשון הרע שמספרים בדרך כלל בחדרי חדרים.","ב\u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 \u0003פורשין מבין האולם ולמזבח בשעת הקטרה. אמר ר' אלעזר: לא שנו\u0004 הלכה זו \u0003אלא בשעת הקטרה\u0004 של קטורת \u0003בהיכל, אבל בשעת הקטרה\u0004 שמקטיר הכהן הגדול ביום הכיפורים \u0003לפני ולפנים\u0004 (בקודש הקדשים), באותה שעה הכהנים \u0003מהיכל פרשי\u0004 \u0005[פורשים]\u0006 ויוצאים, אולם \u0003מבין האולם ולמזבח לא פרשי\u0004 \u0005[אינם פורשים].\u0006","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב אדא בר אהבה, ואמרי לה כדי\u0004 \u0005[ויש אומרים סתם]\u0006 כלומר שונים קושיה זו בלא שם אומרה: שנינו: \u0003ר' יוסי אומר: כשם שפורשין מבין האולם ולמזבח בשעת הקטרה — כך פורשין בשעת מתן\u0004 דם \u0003פר כהן משיח\u0004 המכפר על שהורה לעצמו בשוגג הלכה שיסודה בטעות ואף נהג כן למעשה \u0003ופר העלם דבר של ציבור\u0004 על הוראה מוטעית שהורו ראשי העדה לציבור בשוגג ונהג הציבור כפי הוראתם \u0003ושעירי עבודה זרה,\u0004 שעבדו הציבור עבודה זרה בהוראת בית דין.","אם כן, \u0003הא\u0004 \u0005[הרי]\u0006 מעתה \u0003מה מעלה יש\u0004 אם כן \u0003בין ההיכל לבין האולם ולמזבח? אלא, שבהיכל פורשין בין בשעת הקטרה ובין שלא בשעת הקטרה,\u0004 כלומר: אלא בשעת מתן דמים בפנים, \u0003ומבין האולם ולמזבח אין פורשין אלא בשעת הקטרה\u0004 בלבד, אבל לא בשעת מתן דמים.","ונדייק מכאן: \u0003בשעת הקטרה מיהא פרשי\u0004 \u0005[על כל פנים פורשים\u0006 הם\u0005],\u0006 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר אפילו \u0003בשעת הקטרה\u0004 ש\u0003לפני ולפנים\u0004 (בקודש הקדשים)?","ודוחים: \u0003לא, בשעת הקטרה\u0004 של \u0003היכל\u0004 פורשים. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003הא\u0004 \u0005[זה\u0006 הביטוי\u0005]\u0006 \u0003\"מה מעלה\" ותו\u0004 \u0005[ויותר]\u0006 \u0003לא\u0004 אינו במקומו, שהרי אם מדובר בהקטרה שלפני ולפנים \u0003הא איכא\u0004 \u0005[הרי יש]\u0006 גם כן את \u0003הא\u0004 \u0005[זו]\u0006 ה\u0003מעלה\u0004 של פרישה: ש\u0003אילו\u0004 מן ה\u0003היכל פרשי\u0004 \u0005[פורשים]\u0006 הם \u0003בין בשעת הקטרה דידיה\u0004 \u0005[שלו],\u0006 שהוא מקטיר בהיכל, \u0003בין בשעת הקטרה\u0004 ש\u0003לפני ולפנים, ואילו מבין האולם ולמזבח לא פרשי\u0004 \u0005[פורשים]\u0006 הם \u0003אלא בשעת הקטרה\u0004 שב\u0003היכל!\u0004","ומשיבים: אכן זאת \u0003הא קתני\u0004 \u0005[הרי כבר שנה]\u0006 וכך יש להבין: \u0003אלא\u0004 ש\u0003בהיכל פורשין בין בשעת הקטרה\u0004 בהיכל \u0003ובין שלא בשעת הקטרה\u0004 בהיכל אלא לפני ולפנים, ואילו \u0003מבין האולם ולמזבח אין פורשין\u0004"],["\u0003אלא בשעת הקטרה.\u0004","ומקשים עוד: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 עוד את \u0003הא\u0004 \u0005[זו]\u0006 ה\u0003מעלה,\u0004 ש\u0003אילו מהיכל פרשי\u0004 \u0005[פורשים]\u0006 הם \u0003בין בקדושה דידיה\u0004 \u0005[שלו],\u0006 כלומר: בהקטרת קטורת בו \u0003בין בקדושה,\u0004 כלומר: בהקטרת קטורת של \u0003לפני ולפנים, ואילו מבין האולם ולמזבח לא פרשי\u0004 \u0005[פורשים]\u0006 הם \u0003אלא בקדושה\u0004 של הקטרת הקטורת ב\u0003היכל! אמר רבא:\u0004 אין להקשות מכאן, כי \u0003שם פרישה אחת היא\u0004 שכיון שיש פרישה בכלל, שוב אין מחלקים בפרטיה.","ומוסיפים לדון באותה ברייתא: \u0003אמר מר\u0004 \u0005[החכם]\u0006 כשם שפורשים בשעת הקטרת הקטורת ביום הכיפורים \u0003כך פורשין בשעת מתן\u0004 דם \u0003פר כהן משיח, ופר העלם דבר של צבור, ושעירי עבודה זרה\u0004 שנותנים מדמם לפנים. ושואלים: \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 שכן הוא? \u0003אמר ר' פדת: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 מגזירה שוה \u0003\"כפרה\" \"כפרה\" מיום הכפורים\u0004 שאף באלה נאמרה כפרה ומתן דמם לפנים.","\u0003אמר רב אחא בר אהבה: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי אותן ה\u0003מעלות,\u0004 הבדלי דרגות הקדושה, שהוזכרו במשנה במסכת כלים (פ\"א מ\"ח) שבין חלקי המקדש ועזרותיו, ודאי \u0003דאורייתא\u0004 \u0005[מ\u0006דין \u0005תורה]\u0006 הם \u0003והכי גמירי להו\u0004 \u0005[וכך למודים הם]\u0006 במסורת, ואינם רק ענין של מבנה המקדש.","\u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 שחלוקות אלה של דרגות הקדושה הן \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 אם כן \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 שגזרו שיצאו מ\u0003בין האולם ולמזבח?\u0004 אם תאמר \u0003דילמא מיקרו ועיילי\u0004 \u0005[שמא יזדמנו ויכנסו\u0006 פנימה\u0005]\u0006 אל ההיכל בשעת הקטרה — אם כן מ\u0003כולה\u0004 של ה\u0003עזרה נמי נפרשו\u0004 \u0005[גם כן יפרשו],\u0006 \u0003דילמא מיקרו ועיילי\u0004 \u0005[שמא יזדמנו ויכנסו]\u0006 בטעות!","ודוחים: מכאן אין הוכחה, \u0003בין האולם ולמזבח כיון דלא מפסיק מידי\u0004 \u0005[שאין מפסיק דבר]\u0006 ביניהם, לכך \u0003לא מינכרא מילתא\u0004 \u0005[ניכר הדבר]\u0006 ויכולים לטעות וליכנס, אבל \u0003עזרה כיון דאכא\u0004 \u0005[שישנו]\u0006 \u0003מזבח החיצון\u0004 שהוא \u0003מפסיק\u0004 בין עזרת כהנים וההיכל — \u0003מינכרא מילתא\u0004 \u0005[ניכר הדבר],\u0006 ואין נכנסים שם.","\u0003אמר רבא\u0004 דבר אחר: \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 כי \u0003קדושת אולם\u0004 וקדושת ה\u0003היכל חדא מילתא\u0004 \u0005[דבר אחד]\u0006 \u0003היא,\u0004 ואין חילוקי מדרגות בקדושתם. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה בדעתך]\u0006 לומר כי בעיקרן \u0003שתי קדושות\u0004 נבדלות \u0003נינהו\u0004 \u0005[הן],\u0006 אם כן נמצא כי הפרישה מן ה\u0003אולם גופיה\u0004 \u0005[עצמו]\u0006 \u0003גזירה\u0004 היא, שהרי איננו קדוש בקדושת ההיכל \u0003וניקום\u0004 \u0005[ואנו נבוא]\u0006 \u0003ונגזור גזירה לגזירה\u0004 שגם בין האולם ולמזבח, שהוא רחוק ממנו יותר, אסור יהיה להכנס?!","ודוחים: \u0003לא,\u0004 אפשר לומר אחרת: \u0003אולם ובין האולם ולמזבח חדא קדושה\u0004 \u0005[קדושה אחת]\u0006 \u0003היא,\u0004 ואילו \u0003היכל ואולם שתי קדושות\u0004 הם וגזרו על האולם ועל בין האולם למזבח משום היכל, ואין הוכחה איפוא לדברי רבא.","שנינו במשנה כי \u0003בכל יום היה חותה\u0004 הכהן גחלים במחתה \u0003של כסף\u0004 ומערה בשל זהב. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין חותים בכל יום במחתות זהב? ומשיבים: \u0003התורה חסה על ממונן של ישראל\u0004 ומכיון שבעבודה זו נשחקת המחתה, לכך מוטב שהדבר ייעשה במחתת כסף שהיא זולה מזו של הזהב.","שנינו עוד במשנה כי \u0003\"והיום חותה בשל זהב ובה היה מכניס\".\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003משום חולשא\u0004 \u0005[חולשתו]\u0006 של ה\u0003כהן גדול\u0004 שצריך לעשות לבדו את כל העבודה ביום הצום, ולכך דאגו שימעט ככל שאפשר ולא יטרח יותר מן הצריך.","עוד שנינו במשנה כי \u0003בכל יום\u0004 היה חותה במחתה \u0003של ארבעת קבין\u0004 ומערה לתוך של שלושה. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003נתפזרו לו קב גחלים\u0004 יתירות שהיו במחתה ראשונה יותר מבשניה, היה \u0003מכבדן\u0004 (מטאטא אותם) \u0003לאמה\u0004 (לתעלת המים) העוברת במקדש ויוצאת לנחל קדרון.","\u0003תני חדא\u0004 \u0005[שנה\u0006 החכם בברייתא \u0005אחת]:\u0006 שנתפזר לו \u0003קב, ותני אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 שנתפזרו \u0003קביים\u0004 (שני קבים). ומעירים: \u0003בשלמא הך דתני\u0004 \u0005[נניח זה\u0006 החכם \u0005ששנה]\u0006 ש\u0003קב\u0004 היה מתפזר — שיטה זו \u0003כרבנן\u0004 \u0005[כחכמים]\u0006 שאומרים שהיה לוקח במחתה של ארבעה קבים ומערה לתוך של שלשה. \u0003אלא הך דתני\u0004 \u0005[\u0006ברייתא \u0005זו ששנה\u0006 בה\u0005]\u0006 שנתפזרו שם \u0003קביים\u0004 של גחלים, \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003לא רבנן\u0004 \u0005[חכמים]\u0006 \u0003ולא\u0004 כשיטת \u0003ר' יוסי,\u0004 שהרי ר' יוסי אמר שבסאה, שהיא ששה קבין, היה חותה ולחשבון זה היו צריכים להתפזר שלשה קבין גחלים!","\u0003אמר רב חסדא:\u0004 שיטה זו שיטת \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: בשל קביים היה מכניס,\u0004 ובין ארבעה קבים לשל קביים נשארו קביים עודף והם שהיו מתפזרות.","\u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 כי ברייתא זו כשיטת \u0003ר' יוסי\u0004 היא, \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003בכל יום היה חותה בשל סאה מדברית,\u0004 שהיא המידה שהיתה נהוגה במדבר והיתה של שישה קבין, \u0003ומערה\u0004 את אותה סאה \u0003לתוך שלשת קבין\u0004 לפי המידות ה\u0003ירושלמיות\u0004 והסאה הירושלמית הריהי בת חמישה קבין ולפי זה נמצא כי ההבדל ביניהם הוא רק של שני קבין.","שנינו במשנה כי \u0003בכל יום היתה\u0004 המחתה \u0003כבידה והיום קלה. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003בכל יום היתה גלדה\u0004 (דופנה) \u0003עבה, והיום\u0004 היה \u0003רך\u0004 ודק. \u0003בכל יום היתה\u0004 ידיתה \u0003קצרה והיום ארוכה. מאי טעמא\u0004 \u0005[מה הטעם] —\u0006 \u0003כדי שתהא זרועו של כהן גדול מסייעתו\u0004 שיוכל לא רק להחזיקה בכף ידו אלא גם להשעינה על זרועו.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003בכל יום לא היה לה\u0004 בראשה \u0003ניאשתיק\u0004 (טבעת שהיתה מקשקשת ומשמיע קול), כדי לקיים מה שנאמר \"ונשמע קולו בבואו אל הקודש\" (שמות כח, לו) \u0003והיום היה לה ניאשתיק.\u0004 אלו \u0003דברי בן הסגן,\u0004 שמסורת היתה בידו גם על הבדל זה.","שנינו במשנה ש\u0003בכל יום היה זהבה ירוק\u0004 והיום אדום. \u0003אמר רב חסדא: שבעה\u0004 מיני \u0003זהבים הן; זהב, וזהב טוב, וזהב אופיר\u0004 (מלכים א' י, יא) \u0003וזהב מופז\u0004 (מלכים א' י, יח) \u0003וזהב שחוט\u0004 (מלכים א' י, יז) \u0003וזהב סגור\u0004 (מלכים א' י, כא) \u0003וזהב פרוים\u0004 (דברי הימים ב' ג, ו). ומפרטים: חלוקה זו בין \u0003זהב וזהב טוב\u0004 למדנו מן הכתוב \u0003\"וזהב הארץ ההוא טוב\"\u0004 (בראשית ב, יב) ללמדנו שיש מין זהב הקרוי זהב טוב, המשובח משאר מינים. \u0003זהב אופיר\u0004 — הוא זהב \u0003דאתי\u0004 \u0005[שבא]\u0006 \u0003מאופיר. זהב מופז\u0004"],["\u0003שדומה לפז\u0004 (כעין צבע המרגלית). \u0003זהב שחוט\u0004 — הוא זהב שמפני רכותו הוא \u0003נטוה כחוט. זהב סגור\u0004 נקרא כן — משום \u0003שבשעה שנפתח\u0004 מקום לקנות בו סוג זהב זה \u0003כל החנויות\u0004 האחרות שנמכר בהן מיני זהב אחרים \u0003נסגרות. זהב פרוים\u0004 — זהב אדום, \u0003שדומה לדם הפרים.\u0004","\u0003רב אשי אמר:\u0004 לא שבעה מיני זהב אלא \u0003חמשה הן,\u0004 אותם שמנינו. \u0003וכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 ממינים הללו \u0003אית ביה זהב\u0004 \u0005[יש בו],\u0006 \u0003וזהב טוב\u0004 שהוא מין מובחר יותר. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 לענין זהב פרוים: \u0003בכל יום היה זהבה ירוק והיום אדום, והיינו זהב פרוים\u0004 ש\u0003דומה לדם הפרים.\u0004","שנינו במשנה בענין הקטורת, ש\u0003בכל יום\u0004 היה \u0003מקריב פרס\u0004 (חצי מנה) \u0003בשחרית\u0004 ופרס בין הערבים והיום מוסיף מלא חפניו. \u0003בכל יום היתה\u0004 הקטורת \u0003דקה והיום דקה מן הדקה. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר ביום הכיפורים: \u0003\"\u0004קטורת סמים \u0003דקה\"\u0004 (ויקרא טז, יב) \u0003מה תלמוד לומר? והלא כבר נאמר\u0004 בקטורת: \u0003\"ושחקת ממנה הדק\"\u0004 (שמות ל, לו), הרי שהקטורת דקה היא! \u0003אלא להביא\u0004 וללמד שביום הכיפורים יש צורך שתהא הקטורת \u0003דקה מן הדקה.\u0004","שנינו במשנה כי \u0003בכל יום\u0004 ה\u0003כהנים עולין במזרחו של כבש.\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל פינות\u0004 (פניות) \u0003שאתה פונה לא יהו אלא דרך ימין\u0004 ולצד \u0003מזרח,\u0004 ולכן היו עולין מן המזרח. וכשיורדים שוב היו פונים לצד ימין — והוא למערב הכבש.","עוד שנינו במשנה: \u0003והיום עולין באמצע ויורדין באמצע. מאי טעמא\u0004 \u0005[מהו הטעם] —\u0006 \u0003משום כבודו\u0004 של \u0003כהן גדול\u0004 שלא יהלך מן הצד, אלא באמצע.","שנינו במשנה כי \u0003בכל יום כהן גדול מקדש ידיו ורגליו מן הכיור.\u0004 והיום מקיתון זהב, \u0003מאי טעמא\u0004 \u0005[מהו הטעם] —\u0006 \u0003משום כבודו של כהן גדול.\u0004","במשנה שנינו ש\u0003בכל יום היו שם\u0004 על המזבח \u0003ארבע מערכות\u0004 עצים וביום הכיפורים היו חמש מערכות, וכן דעות נוספות בדבר. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003בכל יום היו שתים מערכות\u0004 עצים על המזבח \u0003והיום שלש.\u0004 ואלו הן: \u0003אחת מערכה גדולה, ואחת מערכה שניה של\u0004 גחלים לצורך \u0003קטורת, ואחת\u0004 מערכת מיוחדת של עצים \u0003שמוסיפין בו ביום\u0004 לצורך הקטורת שלפני ולפנים, אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' יוסי אומר: בכל יום\u0004 היו \u0003שלש\u0004 מערכות, \u0003והיום ארבע.\u0004 כיצד? \u0003אחת של מערכה גדולה, ואחת מערכה שניה של קטורת, ואחת\u0004 מערכה מיוחדת \u0003של קיום האש\u0004 שאם מתעמעמת אש המערכה הגדולה, מוסיפים לה ממערכה זו כדי להגביר את האש, \u0003ואחת שמוסיפין בו ביום.\u0004","\u0003ר' מאיר אומר: בכל יום\u0004 היו על המזבח \u0003ארבע\u0004 מערכות עצים, \u0003והיום חמש.\u0004 והן: \u0003אחת מערכה גדולה, ואחת של מערכה שניה של קטורת, ואחת של קיום האש,\u0004 ועוד \u0003אחת\u0004 שהיתה מערכה מיוחדת \u0003לאיברים ופדרים\u0004 שמאתמול \u0003שלא נתעכלו\u0004 (נשרפו) על המזבח \u0003מבערב\u0004 כל הלילה והיו עושים עוד מערכה מיוחדת לשרפם. \u0003ואחת שמוסיפין בו ביום.\u0004","ושואלים: \u0003דכולי עלמא מיהת\u0004 \u0005[על כל פנים לדעת הכל]\u0006 \u0003תרתי אית להו\u0004 \u0005[שתים יש להם],\u0006 שהכל מודים שבכל יום יש לפחות שתי מערכות, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"היא העלה על מוקדה על המזבח כל הלילה\"\u0004 (ויקרא ו, ב) — \u0003זו מערכה גדולה,\u0004 ונאמר עוד: \u0003\"ואש המזבח תוקד בו\"\u0004 (ויקרא ו, ב) — \u0003זו מערכה שניה של קטורת,\u0004 שהרי נאמרה פעמיים \"אש המזבח\". ושואלים: \u0003ור' יוסי\u0004 מערכה נוספת ל\u0003קיום האש מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 ממה שנאמר: \u0003\"והאש על המזבח תוקד בו\"\u0004 (ויקרא ו, ה) להוסיף עוד יקידה אחת, ולומר שיש צורך בעוד מערכה שאינה משמשת אלא ליקידת האש.","ושואלים: \u0003ור' יהודה\u0004 הסובר שלא היו בכל יום אלא שתי מערכות בלבד, מה לומד הוא מפסוק נוסף זה? ומשיבים: לדעתו, \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב נוסף\u0005]\u0006 לענין \u0003הצתת\u0004 \u0005[הדלקת]\u0006 ה\u0003אליתא,\u0004 שהם קיסמי עץ דקים שבאמצעותם מדליקים את אש המערכה \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ללמד. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היה ר' יהודה אומר: מניין להצתת\u0004 \u0005[הדלקת]\u0006 ה\u0003אליתא שלא תהא\u0004 נעשית \u0003אלא בראשו של\u0004 ה\u0003מזבח\u0004 ולא ידליקנה למטה ויעלה? — \u0003תלמוד לומר: \"והאש על המזבח תוקד בו\"\u0004 (ויקרא ו, ה) — לומר שאותה אש שמביאים צריכה להיות מוצתת על המזבח עצמו. \u0003אמר ר' יוסי: מניין שעושה מערכה לקיום אש — תלמוד לומר: \"והאש על המזבח תוקד בו\"\u0004 (ויקרא ו, ה).","ושואלים: \u0003ור' יוסי הצתת אליתא\u0004 שתהא בראש המזבח \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 \u0003מהיכא דנפקא ליה\u0004 \u0005[מהיכן,\u0006 מאותו מקור \u0005שיוצא לו, ש\u0006נלמד הדבר\u0005]\u0006 לשיטת \u0003ר' שמעון. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"ונתנו בני אהרן הכהן אש על המזבח\"\u0004 (ויקרא א, ז) — \u0003לימד על הצתת\u0004 ה\u0003אליתא שלא תהא אלא בכהן כשר\u0004 לעבודה, \u0003ובכלי שרת\u0004 (בבגדי כהונה). אלו \u0003דברי ר' יהודה. אמר לו ר' שמעון:\u0004 דבר זה לא נצרך, \u0003וכי תעלה על דעתך שזר קרב לגבי מזבח\u0004 לעבודה כלשהי? \u0003אלא לימד\u0004 פסוק זה \u0003על הצתת אליתא שלא תהא אלא בראשו של מזבח.\u0004","ושואלים: \u0003ור' יהודה\u0004 מה עונה הוא על טענה זו? ומשיבים: לדעתו, \u0003אי מהתם\u0004 \u0005[אם משם]\u0006 בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003קאי אארעא ועביד במפוחא\u0004 \u0005[עומד הוא על הארץ ועושה במפוח],\u0006 כדי שתדלק האש בראש המזבח, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כתוב נוסף \"על\", שההצתה עצמה צריכה להיות בראש המזבח.","ושואלים עוד: \u0003ור' מאיר\u0004 הסבור כי \u0003איברים ופדרים שלא נתעכלו מבערב\u0004 עושים להם מערכה נוספת, \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 ממה שנאמר: \u0003\"ואש\",\u0004 וא\"ו זה בא לרבות עוד מערכה נוספת של אש. ומסבירים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 האחרים שאינם דורשים כן — \u0003וא\"ו לא דרשי\u0004 \u0005[דורשים]\u0006 כאן לרבות מערכה שלימה נוספת.","ושואלים: \u0003ורבנן\u0004 \u0005[ו\u0006לדעת \u0005חכמים],\u0006 אותם \u0003איברים ופדרים שלא נתעכלו מבערב מאי עביד להו\u0004 \u0005[מה עושה הוא בהם]\u0006 והיכן שורפם? ומשיבים: \u0003מהדר להו\u0004 \u0005[מחזיר אותם]\u0006 \u0003למערכה גדולה\u0004 ושם מסתיים תהליך שריפתם. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מניין לאיברים ופדרים שלא נתעכלו מבערב\u0004"],["\u0003שסודרן על גבי מזבח, ואם אין מחזיקן\u0004 המקום שם, שהוא צר מלהכיל את כולם, \u0003שסודרן על הכבש או על גבי סובב\u0004 הבליטה סביב למזבח, \u0003עד שיעשה מערכה גדולה\u0004 שנית, \u0003וסודרן\u0004 עליה? — \u0003תלמוד לומר: \"אשר תאכל האש את העלה על המזבח\"\u0004 (ויקרא ו, ג), לומר: אותם דברים שכבר אכלתם האש מונחים על המזבח.","ושואלים: \u0003ור' מאיר\u0004 מה לומד הוא מכאן? ומשיבים: לדעתו יש ללמוד מכתוב זה כי \u0003עיכולי עולה,\u0004 כלומר אברי העולה שהתחילו להתעכל באש ומפני גודל החום פקעו ונפלו למטה \u0003אתה מחזיר\u0004 ומעלה אותם שוב על המזבח, \u0003ואי אתה מחזיר עיכולי קטורת\u0004 שנפלו ממזבח הפנימי. \u0003דתני\u0004 \u0005[כפי ששנה]\u0006 \u0003ר' חנניא בר מניומי בדבי\u0004 \u0005[\u0006בשם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אליעזר בן יעקב:\u0004 נאמר: \u0003\"אשר תאכל האש את העלה על המזבח\"\u0004 (ויקרא ו, ג) — ללמד: \u0003עיכולי עולה אתה מחזיר, ואי אתה מחזיר עיכולי קטורת.\u0004","ומעתה שואלים שאלה כללית, \u0003דכולי עלמא מיהת\u0004 \u0005[לדעת הכל על כל פנים]\u0006 מערכה זו ש\u0003מוסיפין בו ביום אית להו\u0004 \u0005[יש להם],\u0006 שלכל הדעות מוסיפים עוד מערכת מיוחדת ליום הכיפורים, ושואלים: \u0003מנא להו\u0004 \u0005[מנין להם]\u0006 דבר זה? ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא להם]\u0006 ממה שנאמר: \u0003\"והאש\"\u0004 (ויקרא ו, ג) שיש בו לשון תוספת יתרה. \u0003ואפילו למאן דלא דריש\u0004 \u0005[לדעת מי שאינו דורש]\u0006 \u0003\"וא\"ו\"\u0004 יתירה ללמוד שיש להוסיף דבר מה, אולם \u0003\"וא\"ו\"\u0004 וכן \u0003\"ה\"א\"\u0004 הבאים יחד \u0003דריש\u0004 \u0005[דורש]\u0006 ולומד מכאן שיש להוסיף.","ושואלים \u0003\"אש תמיד\"\u0004 שנאמר באותו כתוב \u0003למאי אתא\u0004 \u0005[למה בא]\u0006 ללמדנו? ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[נחוץ הוא\u0006 הדבר \u0005לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"אש תמיד תוקד על המזבח לא תכבה\"\u0004 (ויקרא ו, ו) — \u0003לימד על מערכה שניה של\u0004 ה\u0003קטורת שלא תהא אלא על מזבח החיצון\u0004 ולא במקום אחר.","\u0003אש\u0004 שעושים לצורך \u0003מחתה\u0004 של גחלי הקטורת שמכניסים לקודש הקדשים ביום הכיפורים ואש שעושים להדליק את ה\u0003מנורה מניין\u0004 שאף היא תהיה מן המזבח? ומשיבים: לכאורה \u0003ודין הוא,\u0004 כלומר: דבר זה אפשר ללמוד בדרך ההגיון: \u0003נאמרה אש בקטורת ונאמרה אש במחתה ומנורה, מה להלן\u0004 אש הקטורת היא מ\u0003על מזבח החיצון אף כאן\u0004 האש שלצורך מחתה ומנורה, \u0003על מזבח החיצון.\u0004","אולם לכאורה יש מקום גם לטענה הפוכה, \u0003או כלך\u0004 (לך) וחשוב את הדברים \u0003לדרך זו: נאמרה\u0004 הצתת \u0003אש בקטורת ונאמרה אש במחתה ובמנורה, מה להלן\u0004 בקטורת נוטלים דווקא מן האש \u0003הסמוך לו\u0004 והאש הסמוכה ביותר היא זו שעל המזבח החיצון \u0003אף\u0004 לצורך \u0003מחתה ומנורה\u0004 נוטלים דווקא מן ה\u0003סמוך לו,\u0004 כלומר: מאש המזבח הפנימי.","וכיון שהדבר שקול שוב אין להכריע בו מן הסברה ולכן \u0003תלמוד לומר\u0004 מן הכתובים: \u0003\"אש תמיד תוקד על המזבח לא תכבה\"\u0004 (ויקרא ו, ו) — \u0003אש תמיד\u0004 היא אש המנורה, שנאמר בה \"נר תמיד\" (שמות כז, כ), \u0003שאמרתי לך לא תהא\u0004 מדליק אותה \u0003אלא\u0004 מגחלים הנמצאים \u0003בראשו של מזבח החיצון.\u0004","\u0003למדנו\u0004 איפוא \u0003אש למנורה\u0004 שנאמר בה במפורש אש תמיד, אולם \u0003אש למחתה\u0004 של קטורת שלפני ולפנים \u0003מניין?\u0004 ולכאורה \u0003ודין הוא,\u0004 יכול אתה ללמוד הדבר מכח הסברה: \u0003נאמרה אש במחתה, ונאמרה אש במנורה, מה להלן\u0004 במנורה אין נוטלים גחלים לצורכה אלא מ\u0003על גבי מזבח החיצון, אף כאן\u0004 לצורך הקטורת אין נוטלים גחלים אלא מ\u0003על מזבח החיצון.\u0004","אולם אם דבר זה נלמד מסברה, אפשר אם כן לטעון: \u0003כלך לדרך זו,\u0004 לך וטען באופן אחר: \u0003נאמרה אש בקטורת, ונאמרה אש במחתה, מה להלן\u0004 בקטורת, האש באה מן המזבח ה\u0003סמוך לו\u0004 המזבח החיצון \u0003אף כאן\u0004 במנורה אין ניטלים הגחלים לצורכה אלא מן המזבח ה\u0003סמוך לו,\u0004 והוא מזבח הפנימי!","\u0003תלמוד לומר: \"ולקח מלא המחתה גחלי אש מעל המזבח מלפני ה'\"\u0004 (ויקרא טז, יב), \u0003איזהו מזבח\u0004 שרק \u0003מקצתו לפני ה',\u0004 שחלק ממנו מכוון כנגד קודש הקדשים \u0003ואין כולו לפני ה'\u0004 ויש צורך לומר שיטול גחלים דווקא מאותו החלק שלפני ה' — \u0003הוי אומר זה מזבח חיצון,\u0004 שהרי מזבח הפנימי כולו לפני ה' הוא.","ומעירים: \u0003ואיצטריך למיכתב\u0004 \u0005[וצריך\u0006 היה \u0005לכתוב]:\u0006 \u0003\"מעל המזבח\" ואיצטריך למיכתב\u0004 \u0005[וצריך\u0006 היה \u0005לכתוב]:\u0006 \u0003\"מלפני ה'\": דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 רק \u0003\"מעל המזבח\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"מזבח\"\u0004 האמור כאן — \u0003מזבח הפנימי,\u0004 לכן \u0003כתב רחמנא: \"מלפני ה'\". ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 \u0003\"מלפני ה'\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003דוקא מלפני ה'\u0004 כלומר מצד המזבח הפונה לפני ה', המכוון כנגד קודש הקדשים,"],["\u0003אבל מהאי גיסא ומהאי גיסא\u0004 \u0005[מצד זה ומצד זה]\u0006 של המזבח \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 לשני הכתובים ללמדנו הלכה זו.","\u0003אמר ר' אלעזר משום\u0004 \u0005[בשם]\u0006 \u0003בר קפרא, אומר היה ר' מאיר: איברי עולה שנתותרו\u0004 שנשארו על המזבח ולא הספיקו להתעכל — \u0003עושה להן מערכה\u0004 מיוחדת \u0003בפני עצמה וסודרן\u0004 עליה להישרף, \u0003ואפילו בשבת.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך? הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה במפורש שלשיטת ר' מאיר \u0003בכל יום היו שם ארבע מערכות\u0004 ואחת מהן מיוחדת לשריפת איברים. \u0003אמר ר' אבין: לא נצרכה אלא\u0004 לאיברים \u0003פסולין,\u0004 שיש קרבנות פסולים שכיון שעלו על המזבח, שוב אין מורידים אותם משם.","ומעירים: \u0003ודוקא\u0004 שכבר \u0003משלה בהן האור\u0004 (האש) והחלו כבר להישרף, \u0003אבל\u0004 אם עדיין \u0003לא משלה בהן האור\u0004 — \u0003לא,\u0004 אין מעלים אותם למזבח.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]:\u0006 \u0003אחד\u0004 איברי עולה \u0003כשירין ואחד פסולין, אי\u0004 \u0005[אם]\u0006 כבר \u0003משלה בהן האור\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מעלים אותם למזבח, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — לא.\u0004","ועוד שואלים: מה שאמר בר קפרא \u0003\"ואפילו בשבת\"\u0004 גם כן הרי \u0003תנינא\u0004 \u0005[שנינו]\u0006 ואין בכך חידוש, שהרי למדנו לשיטת ר' מאיר: \u0003והיום\u0004 ביום הכיפורים \u0003חמש\u0004 ואם ביום הכיפורים, שהוא שבת שבתון, ודינו לכל דבר כשבת, עושים בו חמש מערכות, ודאי שגם לשבת עושים מערכה מיוחדת לשריפת איברי עולה שנתותרו!","\u0003אמר רב אחא בר יעקב:\u0004 מכל מקום \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 להיאמר, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003הני מילי היכא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005כאשר]\u0006 \u0003חל יום הכפורים להיות אחר השבת\u0004 ביום הראשון, ואז עושים בו מערכה מיוחדת לשריפת איברי אתמול, על סמך ההלכה המקובלת ש\u0003חלבי\u0004 קרבנות שקרבו \u0003בשבת\u0004 ולא הספיקו להישרף \u0003קרבין\u0004 ונשרפים \u0003ביום הכפורים, אבל\u0004 חל יום הכיפורים \u0003באמצע שבת,\u0004 באחד מימות השבוע האחרים — \u0003לא,\u0004 אין מוסיפין בו מערכה מיוחדת לשריפת איברים של יום חול — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל אופן עושים ביום הכיפורים מערכה מיוחדת לאיברי יום אתמול, אף אם היה זה באמצע השבוע.","\u0003אמר רבא: מאן האי\u0004 \u0005[מי זה]\u0006 ש\u0003לא חייש לקמחיה\u0004 \u0005[חושש לקמחו]?\u0006 כלומר: מי הוא זה שאינו חושש לדברים שהוא מוציא מפיו, ואינו מדקדק בהם יפה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"בכל יום\" תנן\u0004 \u0005[שנינו]\u0006 ואין איפוא חילוק בין יום לחבירו! ומעירים: אכן \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005]\u0006 לדברי רב אחא בר יעקב.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 שיטת רבא ובר קפרא ש\"בכל יום\" האמור במשנה הוא דווקא, וכי אף בשבת היתה נעשית מערכה לשריפת איברי עולה של אתמול, על דעת \u0003רב הונא,\u0004 ש\u0003אמר:\u0004 קרבן תמיד \u0003תחילתו דוחה\u0004 שבת, שעבודת הקודש שבשחיטתו והקרבתו דוחה שבת, ואילו \u0003סופו,\u0004 של קרבן התמיד, גמר הקטרתו, \u0003אינו דוחה\u0004 שבת.","\u0003גופא\u0004 \u0005[\u0006ל\u0005גוף\u0006 הדברים\u0005],\u0006 כיון שהוזכרו דברי רב הונא דנים בהם לגופם. \u0003אמר רב הונא: תמיד תחילתו,\u0004 כלומר: שחיטתו והקרבתו \u0003דוחה,\u0004 ואילו \u0003סופו\u0004 הקטרת איבריו ואימוריו \u0003אינו דוחה.\u0004","ושואלים בפירוש דברים אלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אינו דוחה? רב חסדא אמר:\u0004 כוונתו, שסופו של התמיד כתחילתו שהוא \u0003דוחה את השבת,\u0004 ואף בשבת מקטירים את איבריו ואימוריו, אבל \u0003אינו דוחה את הטומאה.\u0004 שאם הוצרכו להקריבו בטומאה, מותר רק לשוחטו ולהזות את דמו, אבל אין מקטירים את איבריו. \u0003ורבה אמר: דוחה את הטומאה, ואינו דוחה את השבת.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבה: \u0003לדידך קשיא\u0004 \u0005[לשיטתך קשה]\u0006 \u0003ול\u0004שיטת \u0003רב חסדא קשיא\u0004 \u0005[קשה];\u0006 \u0003לדידך קשיא\u0004 \u0005[לשיטתך קשה]\u0006 — \u0003מאי שנא\u0004 \u0005[מה,\u0006 במה \u0005שונה]\u0006 \u0003טומאה\u0004 שהיא דוחה — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בקרבן התמיד: \u0003\"במעדו\",\u0004 והדגשה זו באה ללמד: \u0003ואפילו בטומאה,\u0004 אולם אם כן, \u0003שבת נמי\u0004 \u0005[גם כן]\u0006 תדחה, שהרי \u0003\"במעדו\"\u0004 משמע \u0003ואפילו בשבת.\u0004","\u0003ולרב חסדא קשיא\u0004 \u0005[קשה]\u0006 מאותו מקור: \u0003מאי שנא\u0004 \u0005[מה,\u0006 במה \u0005שונה]\u0006 \u0003שבת\u0004 שהתמיד דוחה אותה משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"במעדו\",\u0004 להדגיש שכן הדין \u0003אפילו בשבת,\u0004 אם כן \u0003טומאה נמי\u0004 \u0005[גם כן]\u0006 יש להבין \u0003\"במעדו\" — ואפילו בטומאה,\u0004 ומה טעם לחלק?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003לא לדידי קשיא\u0004 \u0005[לשיטתי קשה],\u0006 \u0003ולא ל\u0004שיטת \u0003רב חסדא קשיא\u0004 \u0005[קשה].\u0006 והוא מסביר: \u0003לדידי לא קשיא\u0004 \u0005[לשיטתי אינו קשה],\u0006 כי סבור אני שדנים \u0003סופו כתחילתו,\u0004"],["ולכן \u0003טומאה,\u0004 ש\u0003תחילתו בר מידחא\u0004 \u0005[ראוי לדחות]\u0006 את \u0003טומאה הוא\u0004 \u0005—\u0006 \u0003סופו נמי דחי\u0004 \u0005[גם כן דוחה]\u0006 את הטומאה. ואילו \u0003שבת\u0004 שמ\u0003תחילתו לאו בר מידחא\u0004 \u0005[אינו ראוי לדחות]\u0006 את \u0003שבת\u0004, שהרי כאן מדובר בקרבן תמיד של יום השישי שאינו דוחה את השבת, \u0003סופו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא דחי\u0004 \u0005[דוחה]\u0006 את השבת לשרוף איברים שנשארו מקרבן התמיד של יום שישי.","ואף \u0003לרב חסדא לא קשיא\u0004 \u0005[קשה],\u0006 שכן נימוק זה של \u0003סופו כתחילתו לית ליה\u0004 \u0005[אין לו],\u0006 שאין הוא מקבל השוואה זו. כי \u0003שבת\u0004 ש\u0003הותרה היא בציבור\u0004 מלכתחילה היתר גמור לכן \u0003סופו נמי דחי\u0004 \u0005[גם כן דוחה]\u0006 את השבת, שהרי עבודת הקרבנות נעשית לכתחילה בשבת.","ואילו \u0003טומאה\u0004 שרק \u0003דחויה היא בציבור,\u0004 שאף שמקריבים בציבור בטומאה, מכל מקום נעשה הדבר מתוך הדחק ואם אפשר בטהרה — עושים, ולכן \u0003תחלתו\u0004 שחיטתו והזאת דמו ש\u0003עיקר\u0004 ה\u0003כפרה\u0004 תלוי בכך, יעשה אף בטומאה ו\u0003דחי\u0004 \u0005[דוחה]\u0006 מצוה זו את הטומאה, אבל \u0003סופו דלאו\u0004 \u0005[שאינו]\u0006 \u0003עיקר כפרה — לא דחי\u0004 \u0005[דוחה]\u0006 את הטומאה, שהרי עיקר הכפרה כבר היתה, ואין סיבה איפוא להוסיף ולדחות את איסור הטומאה.","כיון שעסקנו בדיני הבאת אש למחתה ולמנורה, מביאים מה ש\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה מה דינו של \u0003המכבה אש\u0004 הגחלים הנמצאים ב\u0003מחתה\u0004 לאחר חתייתם מהמזבח \u0003ומנורה, אביי אמר: חייב\u0004 על כך. \u0003רבא אמר: פטור.\u0004","ומצמצמים את המחלוקת: \u0003דכבייה\u0004 \u0005[\u0006אם \u0005כיבה]\u0006 את האש הזו \u0003בראשו של מזבח, דכולי עלמא לא פליגי\u0004 \u0005[לדעת הכל אין חלוקים]\u0006 שהוא \u0003חייב.\u0004 כי הדבר כלול בתוך האיסור לכבות אש המזבח, כאמור: \"אש תמיד תוקד על המזבח לא תכבה\" (ויקרא ו, ו). \u0003כי פליגי דאחתיה אארעא וכבייה\u0004 \u0005[כאשר נחלקו היה כאשר הוריד\u0006 מאש זו \u0005לארץ ו\u0006שם \u0005כיבה אותה].\u0006 \u0003אביי אמר: חייב\u0004 עליה כי עדיין בכלל \u0003אש המזבח הוא, רבא אמר: פטור, כיון\u0004 ש\u0003נתקה\u0004 ממקומה לצורך חתייתה עם המחתה ושוב אינה שייכת לאש המזבח — \u0003נתקה,\u0004 ואין דינה עוד כאש המזבח.","ושואלים: \u0003אלא הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 ש\u0003אמר רב נחמן אמר רבה בר אבוה: המוריד גחלת מעל גבי המזבח וכיבה — חייב, כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי היא]\u0006 דעה זו? לכאורה רק כשיטת \u0003אביי\u0004 היא!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהלכה זו \u0003כ\u0004שיטת \u0003רבא,\u0004 ויש לחלק; \u0003התם\u0004 \u0005[שם]\u0006 הגחלת שהוריד \u0003לא אינתיק\u0004 \u0005[נותקה]\u0006 \u0003למצותה,\u0004 שעדיין מאש המזבח היא, ולא ניתנה לצורך מצוה אחרת, אבל \u0003הכא אינתיקה\u0004 \u0005[כאן נותקה\u0006 והועברה\u0005]\u0006 מ\u0003מצותה,\u0004 וכיון שעכשיו היא שייכת כבר למצות מנורה ומחתה שלא נאמר בהן איסור כיבוי כבאש המזבח, לכן פטור.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שמחלוקת זו היתה באופן אחר.","\u0003דאחתיה אארעא וכבייה\u0004 \u0005[\u0006אם \u0005הוריד\u0006 את האש במחתה \u0005על הארץ וכיבה אותה],\u0006 \u0003דכולי עלמא לא פליגי\u0004 \u0005[לדעת הכל אין חלוקים]\u0006 שהוא \u0003פטור; כי פליגי\u0004 \u0005[כאשר נחלקו] —\u0006 היה זה \u0003דכבייה\u0004 \u0005[כאשר כיבה אותה]\u0006 \u0003בראשו של\u0004 ה\u0003מזבח\u0004 לאחר שניתקה מן המערכה, \u0003אביי אמר: חייב,\u0004 שהרי \u0003אש המזבח הוא. רבא אמר: פטור,\u0004 וטעמו: \u0003כיון שנתקה — נתקה.\u0004","ושואלים: \u0003אלא הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 ש\u0003אמר רב נחמן אמר רבה בר אבוה: המוריד גחלת מעל גבי המזבח וכבה — חייב, כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי היא],\u0006 הלא אינו \u0003לא\u0004 כשיטת \u0003אביי ולא\u0004 כשיטת \u0003רבא!\u0004 ודוחים: מכאן אין להקשות לשניהם, כי \u0003התם לא אינתיק\u0004 \u0005[שם לא נותקה]\u0006 \u0003למצותה,\u0004 אלא נשארה בגדר אש המזבח, ולכן גם כשהורידוה חייבים עליה, \u0003הכא אינתיק\u0004 \u0005[כאן ניתקה]\u0006 כבר \u0003למצותה\u0004 אחרת ושוב אינה בכלל אש המזבח, ולכן אם הורידה ודאי אין חייבים על כיבויה.",""],["\u0003הוציאו לו\u0004 לכהן הגדול \u0003את הכף ואת המחתה\u0004 לצורך העבודה, \u0003חפן\u0004 מן הקטורת \u0003מלא חפניו ונתן לתוך הכף. הגדול,\u0004 כלומר: כהן שידיו גדולות — ממלא \u0003לפי גדלו, והקטן — לפי קטנו. וכך היתה מדתה\u0004 של הכף עשויה בהתאם לגודל ידיו. \u0003נטל את המחתה בימינו ואת הכף בשמאלו.\u0004","על המשנה תוהים: הבאת \u0003מחתה\u0004 הרי כבר \u0003תנא ליה\u0004 \u0005[שנה אותה]\u0006 קודם (לעיל יומא מג, ב), ששנינו: \u0003נטל את המחתה ועלה לראש המזבח וחותה ויורד,\u0004 ומה מקום אם כן להזכיר את הדבר שנית? ומסבירים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר ב\u0003מחתה\u0004 של \u0003גחלים,\u0004 שממלא בגחלי אש, \u0003והכא\u0004 \u0005[וכאן]\u0006 מדובר ב\u0003מחתה\u0004 של \u0003קטורת,\u0004 שבה היו מכניסים לו את הקטורת שממנה יחפון. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 ובה מפורש הדבר: \u0003הוציאו לו כף ריקן מלשכת הכלים, ומחתה גדושה של קטורת מלשכת בית אבטינס.\u0004","שנינו כי הכהן \u0003חפן\u0004 מן הקטורת \u0003מלא חפניו ונותן לתוך הכף. הגדול,\u0004 כלומר: כהן שידיו גדולות — ממלא \u0003לפי גדלו, והקטן — לפי קטנו. וכך היתה מדתה\u0004 של הכף עשויה בהתאם לגודל ידיו. ושואלים: \u0003כף ביום הכפורים למה לי?\u0004 הלא \"ולקח מלא המחתה גחלי אש מעל המזבח מלפני ה' \u0003ומלא חפניו\u0004 קטורת סמים דקה \u0003והביא\u0004 מבית לפרוכת\" (ויקרא טז, יב) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ומשמע שצריך להביא מלוא חפניו ביד, ולא בכלי!","ומשיבים: \u0003משום דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 לעשות אחרת; \u0003דהיכי נעביד\u0004 \u0005[ש\u0006הרי \u0005כיצד נעשה]?\u0006 \u0003נעייל והדר נעייל\u0004 \u0005[שיכניס\u0006 את המחתה \u0005ואחר יכניס]\u0006 את הקטורת — \u0003הבאה אחת אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 לגחלים ולקטורת \u0003ולא שתי הבאות.\u0004","אלא \u0003נשקליה\u0004 \u0005[שיקח]\u0006 את ה\u0003קטורת בחפניו ונחתיה\u0004 \u0005[ושישים]\u0006 את ה\u0003מחתה עלה\u0004 \u0005[עליה],\u0006 על שני החופנים שבידיו, \u0003וליעול\u0004 \u0005[ויכנס]\u0006 ויכניס הכל בבת אחת. אולם \u0003כי מטי התם היכי לעביד\u0004 \u0005[כאשר הוא מגיע שם\u0006 לקודש הקדשים \u0005איך יעשה],\u0006 כיצד יוכל להניח את המחתה במקומה? \u0003נשקליה בשיניה ונחתיה\u0004 \u0005[יקחנה בשיניו ויוריד]\u0006 את ה\u0003מחתה — השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003לפני מלך בשר ודם אין עושין כן\u0004 באופן בלתי מכובד, \u0003לפני מלך מלכי המלכים הקדוש ברוך הוא על אחת כמה וכמה\u0004 שאין לעשות כן.","\u0003הלכך\u0004 (על כן) — \u0003לא אפשר\u0004 לעשות באופן אחר, \u0003וכיון דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 לעשות אחרת \u0005—\u0006 \u0003עבדינן כדאשכחן\u0004 \u0005[כמו שמצאנו]\u0006 שעשו בקרבנות ה\u0003נשיאים\u0004 בחנוכת המשכן, שהביאו כף מליאה קטורת (\"כף אחת עשרה זהב מלאה קטורת\". במדבר ז, יד).","נאמר במשנה כי \u0003נטל הכהן את המחתה בימין ואת הכף בשמאל.\u0004 על סדר זה תוהים, כפי הפתגם המקובל: \u0003יציבא בארעא וגיורא בשמי שמיא\u0004 \u0005[האזרח\u0006 מוטל \u0005בארץ והגר בשמי השמים]?\u0006 כלומר, הלא זה היפך הסדר הראוי! שהרי עיקר המצוה היא בקטורת, ומחתת הגחלים אינה אלא לשרוף את הקטורת, והיה צריך שיקח העיקר בימינו והטפל בשמאלו!","ומשיבים: טעם הדבר הוא כי כך נוח יותר, שכן זו המחתה \u0003מרובה\u0004 בגחלים וכבידה, \u0003וזו\u0004 הקטורת \u0003מועטת. ואפילו בזמן ששניהן שוין\u0004 שיש לו בכף כשלושה קבים קטורת, \u0003וכמעשה\u0004 של \u0003ר' ישמעאל בן קמחית\u0004 שהיו ידיו גדולות ביותר, והיו מכילות קבים אחדים, מכל מקום \u0003זו\u0004 המחתה — \u0003חמה\u0004 וצריך משום כך להחזיקה ביד ימין לזהירות יתר \u0003וזו\u0004 הקטורת — \u0003צוננת,\u0004 ונוח לאחוז אותה ביד שמאל.","כיון שהוזכר ר' ישמעאל בן קמחית מספרים: \u0003אמרו עליו על ר' ישמעאל בן קמחית\u0004 שהיו ידיו גדולות ביותר עד \u0003שהיה חופן\u0004 כדי שיעור \u0003ארבעת קבין במלוא חפניו.\u0004 והיה \u0003אומר: כל הנשים זרדו,\u0004 כלומר: כל הנשים בררו \u0003וזרד אימא עלה לגג,\u0004 שמה שבררה אמי גבר על כולם. כלומר: על עצמו, שגדל כל כך בקומה ובאיברים. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שכוונתו היתה כפשוטה: \u0003בערסן\u0004 בברירת הסולת, וכדברי \u0003רבה בר יונתן,\u0004 ש\u0003אמר רבה בר יונתן אמר ר' יחיאל: ערסן\u0004 (סולת) \u0003יפה\u0004 ובריא \u0003לחולה,\u0004 וכיון שאכלה אמו בהרותה לו סולת מבוררת היטב, מכח זה גדל בנה ביותר.","\u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]\u0006 שהיה זה כינוי ל\u0003שכבת זרע\u0004, \u0003וכד\u0004ברי \u0003ר' אבהו.\u0004 ש\u0003ר' אבהו רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בין הכתובים, \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד: \u0003\"ותזרני חיל למלחמה\"\u0004 (שמואל ב' כב, מ), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק המקביל לו: \u0003\"המאזרני חיל למלחמה\"\u0004 (תהלים יח, מ), כיצד מקבילים משוים את שני הכתובים תזרני-תאזרני? \u0003אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם!\u0004 אתה \u0003זריתני\u0004 כלומר בררת את המעולה מתוך טיפת הזרע שקלטה אימי ובה גם \u0003זרזתני\u0004 (הזרתני) — יצרת אותי, ועל ידי כך מתיישבים הכתובים. כיון שהוזכר ר' ישמעאל בן קמחית מספרים מעשים אחרים שאירעו בו.","\u0003אמרו עליו על ר' ישמעאל בן קמחית: פעם אחת סיפר דברים עם ערבי אחד\u0004 ביום הכיפורים \u0003בשוק, ונתזה צינורא\u0004 \u0005[טיפת רוק]\u0006 \u0003מפיו\u0004 של הערבי \u0003על בגדיו\u0004 של ר' ישמעאל שהיה כהן גדול , ועל ידי כך נטמא (בטומאה שהיא מדברי סופרים כטומאת הזב), ולא יכול היה לשמש בכהונה, \u0003ונכנס ישבב אחיו ושמש תחתיו\u0004 בכהונה באותו יום. וכך \u0003ראתה אמן שני\u0004 בניה משמשים כ\u0003כהנים גדולים ביום אחד.\u0004","\u0003שוב אמרו עליו על ר' ישמעאל בן קמחית: פעם אחת יצא וסיפר עם אדון אחד בשוק, ונתזה צינורא\u0004 \u0005[טיפת רוק]\u0006 \u0003מפיו\u0004 של אותו אדון \u0003על בגדיו\u0004 של ר' ישמעאל \u0003ונכנס יוסף אחיו ושמש תחתיו\u0004 בכהונה גדולה, \u0003וראתה אמן\u0004 שוב \u0003שני\u0004 בניה משמשים כ\u0003כהנים גדולים ביום אחד.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003שבעה בנים היו לה לקמחית, וכולן שמשו בכהונה גדולה\u0004 כממלאי מקומו של הכהן הגדול. \u0003אמרו לה חכמים: מה עשית\u0004 מעשים טובים \u0003שזכית לכך? אמרה להם: מימי לא ראו קורות ביתי קלעי\u0004 (קליעות) \u0003שערי,\u0004 שהיתה צנועה ביותר ומקפידה בכיסוי הראש אפילו בתוך ביתה. \u0003אמרו לה: הרבה\u0004 נשים \u0003עשו כן ולא הועילו\u0004 עד כדי כך, ומשמים הוא שסייעוך לכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \"והרים ממנו \u0003בקמצו\u0004 מסולת המנחה ומשמנה\" (ויקרא ו, ח), ללמד \u0003שלא יעשה מדה לקומץ\u0004 על ידי כלי, אלא יפריש בידו ממש. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 \u0003מהו שיעשה מדה לחפינה\u0004 של הקטורת, או האם גם את הקטורת חייב לחפון בידיו ממש?","וצדדי השאלה: \u0003התם\u0004 \u0005[שם]\u0006 בקמיצה \u0003הוא דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"בקמצו\"\u0004 ללמד: בקומץ עצמו ולא על ידי כלי, \u0003אבל הכא דלא כתיב\u0004 \u0005[כאן שלא נאמר]\u0006 \u0003\"בחפניו\", אלא: \"ומלא חפניו קטרת סמים דקה\"\u0004 (ויקרא טז, יב), שמא הכוונה היא ללמד שמלוא חפניו \u0003לא\u0004 יצטרך לעשותה דווקא בידיו, אלא יחפון כדי מידה זו אף בכלי. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003יליף\u0004 \u0005[לומד]\u0006 הוא בכעין גזירה שוה \u0003\"מלא\" \"מלא\" מקמצו\u0004 שנאמר במנחה ואף בקטורת לא יחפון אלא בידו ממש?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 תשובה לדבר ממה ששנינו: \u0003\"וכך היתה מדתה\", מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שכדי חפניו זוהי אכן מידתה, אבל אינו חייב לחפון בידו דווקא ו\u0003אם רצה לעשות מדה אחרת — עושה\u0004 ובה היה לוקח. ודוחים: \u0003לא, הכי קאמר\u0004 \u0005[כך אמר]\u0006 זו היא הכוונה: \u0003וכך\u0004 באותה מידה עצמה \u0003היה חוזר וחופנה לפנים\u0004 ולא היה משנה.","ושואלים: אם כן \u0003שמעת מינה\u0004 \u0005[למד מכאן]\u0006 \u0003חופן וחוזר וחופן,\u0004 שמתחילה חופן פעם אחת ואחר כך חוזר וחופן בקודש הקדשים, ועל ידי כך נפתרת בעיה שנשאלה בנושא זה (להלן יומא מט, א)!","ודוחים: לא, אפשר לפרש כאן \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003שאם רצה לעשות מדה עושה\u0004 שהרי מן הלשון אין הוכחה לפירוש הקודם שלנו, ושמא פירושה כפי שפירשנו תחילה שאינו צריך לחפון דווקא בידו, ואין לפתור איפוא את הבעיה. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 הכוונה היא \u0003שלא יחסר ושלא יותיר,\u0004 אלא כמידתה בצמצום, ואין להוכיח מכאן דבר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"מלא קמצו\"\u0004 (ויקרא טז, יב). \u0003יכול מבורץ\u0004 שתהא הקטורת מבצבצת מן הקומץ ויוצאת חוצה לו — \u0003תלמוד לומר: \"בקמצו\"\u0004 בדיוק, ולא יותר. \u0003אי\u0004 \u0005[אם]\u0006 נדקדק מן הלשון \u0003\"בקמצו\" יכול\u0004 יקמוץ מעט \u0003אפילו בראשי אצבעותיו\u0004 ולא בכל בית קיבולה של הקומץ, \u0003תלמוד לומר: \"מלא קמצו\",\u0004 וכוונתו: \u0003כדקמצי אינשי\u0004 \u0005[כפי שאנשים\u0006 רגילים \u0005לקמוץ],\u0006 שלוקחים מלוא היד. \u0003הא כיצד\u0004 עושה — \u0003חופה\u0004 (מכסה) \u0003שלש אצבעותיו על פיסת ידו וקומץ\u0004 מסולת המנחה."],["ובמנחת \u0003מחבת\u0004 ובמנחת \u0003מרחשת,\u0004 שהיו מטוגנות לפני קמיצתן והיו קשות יותר \u0003מוחק\u0004 מנקה \u0003בגודלו\u0004 את מה שהיה מבצבץ ויוצא \u0003מלמעלה,\u0004 ומוחק \u0003באצבעו קטנה\u0004 את מה שהיה מבצבץ ויוצא \u0003מלמטה. וזו\u0004 הקמיצה המדוייקת \u0003היא\u0004 ה\u0003עבודה\u0004 ה\u0003קשה שבמקדש.\u0004 ושואלים: ו\u0003זו היא ותו\u0004 \u0005[ועוד]\u0006 \u0003לא? והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003מליקה\u0004 שגם עליה נאמר שהיא עבודה קשה, \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003חפינה! אלא\u0004 כך יש להבין: \u0003זו היא\u0004 אחת מן ה\u0003עבודות\u0004 ה\u0003קשות שבמקדש.\u0004","\u0003אמר ר' יוחנן, בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יהושע בן עוזאה\u0004 שאלה זו: \u0003בין הבינים\u0004 אותו חלק הנשאר בין האצבעות \u0003של מלא קומצו, מהו?\u0004 האם נחשב הוא כחלק מן הקומץ, או הוא כחלק מן המנחה? ומפרטים: \u0003אמר רב פפא: דגואי\u0004 \u0005[שבפנים]\u0006 לצד היד \u0003לא תיבעי\u0004 \u0005[יסתפק]\u0006 \u0003לך\u0004 בענין זה, ש\u0003ודאי קומץ הוא,\u0004 וכן \u0003דבראי\u0004 \u0005[\u0006החלק \u0005שבחוץ]\u0006 \u0003לא תיבעי\u0004 \u0005[יסתפק]\u0006 \u0003לך\u0004 בו — ש\u0003ודאי שירים הוא\u0004 כשאר מנחה.","\u0003כי תיבעי\u0004 \u0005[כאשר יסתפק]\u0006 \u0003לך —\u0004 הרי זה במה שנמצא \u0003ביני ביני\u0004 \u0005[באמצע]\u0006 בין פנים וחוץ \u0003מאי\u0004 \u0005[מה\u0006 יהיה דינו\u0005]\u0006. \u0003אמר ר' יוחנן: הדר פשטה\u0004 \u0005[חזר ופתרה]\u0006 \u0003יהושע בן עוזאה\u0004 לשאלתו ואמר כי מה שנמצא \u0003בין הבינים — ספק נינהו\u0004 \u0005[הוא]\u0006 ויש לנהוג בו כדין ספק.","ושואלים: \u0003היכי עביד\u0004 \u0005[כיצד הוא עושה,\u0006 נוהג\u0005]\u0006 בספק זה? \u0003אמר ר' חנינא,\u0004 כך הוא עושה: \u0003מקטיר קומץ לחודיה\u0004 \u0005[לעצמו]\u0006 \u0003תחלה, והדר\u0004 \u0005[ואחר כך]\u0006 מקטיר מה ש\u0003בין הבינים. דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 שיקטיר את מה שנמצא \u0003בין הבינים ברישא\u0004 \u0005[בתחילה] —\u0006 \u0003דילמא שירים נינהו\u0004 \u0005[הם]\u0006 \u0003והוו להו\u0004 \u0005[והרי יהיו אלה]\u0006 כדין \u0003שירים שחסרו בין קמיצה להקטרה\u0004 שהרי הוא נוטל מחלק השיריים של המנחה, \u0003ואמר מר\u0004 \u0005[החכם]\u0006 בהלכה זו: \u0003שירים שחסרו בין קמיצה להקטרה — אין מקטירין עליהן את הקומץ.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שיש ספק שמא חלק זה מן השיריים הוא — \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 אם יקטיר את מה שבין הבינים לאחר הקטרת הקומץ \u0003איקרי כאן\u0004 \u0005[קרא כאן]\u0006 את ההלכה: \u0003כל שממנו לאשים — הרי הוא בבל תקטירו.\u0004 שהלכה היא בידינו שכל דבר שמקטירים חלק ממנו למזבח, אם מקטיר את החלק שאינו נועד להקטרה עובר עליו באיסור לא תעשה. ואם בין הבינים אינו נחשב אלא כשירים — הרי הוא עובר בהקטרתו משום איסור זה!","\u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי:\u0004 מדובר כאן שאינו מקטירם לשם מנחה, אלא \u0003מקטיר ליה\u0004 \u0005[אותו]\u0006 \u0003לשום\u0004 (לשם) \u0003עצים.\u0004 כלומר: אינו מקטיר לשם קרבן אלא כחומר דלק בלבד למזבח, ודבר זה מותר, כדברי \u0003ר' אליעזר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר אומר:\u0004 נאמר: \u0003\"\u0004ואל המזבח לא יעלו \u0003לריח ניחח\"\u0004 (ויקרא ב, יב), לומר: \"לריח ניחוח\" \u0003אי אתה מעלה,\u0004 שאינם עולים כקרבן, \u0003אבל אתה מעלה\u0004 דברים אחרים \u0003לשום עצים.\u0004","ושואלים: \u0003הניחא\u0004 \u0005[דבר זה נוח]\u0006 לשיטת \u0003ר' אליעזר, אלא לרבנן\u0004 \u0005[לחכמים]\u0006 החולקים על ר' אליעזר ואינם מסכימים להלכה זו \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003אמר רב מרי:\u0004 צריך לומר: \u0003דקמצי שמיני\u0004 \u0005[שקומצים\u0006 את המנחה כהנים \u0005שמנים]\u0006 שעובי הבשר של אצבעותיהם דוחק את כל מה שביניהם, ואין סולת נשארת בין האצבעות. ואומרים: \u0003השתא דאתית להכי\u0004 \u0005[ועכשיו שהגעת לכך]\u0006 לתירוץ זה, לשיטת \u0003ר' אליעזר נמי\u0004 \u0005[גם כן]\u0006 \u0003לכתחילה\u0004 ראוי \u0003דקמצי שמיני\u0004 \u0005[שקומצים\u0006 כהנים \u0005שמנים]\u0006 וממילא אין מגיעים כלל לידי ספק.","\u0003בין הביניי\"ם, פש\"ט, ומח\"ץ, ופז\"ר, וחש\"ב, בחפינ\"ת חביר\"ו\u0004 — \u0003סימן\u0004 לבעיות הבאות של רב פפא. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: בין הבינים של מלא חפניו\u0004 קטורת \u0003מהו\u0004 דינו? ושואלים: \u0003מאי קא מבעיא ליה\u0004 \u0005[מהו שנשאל לו]\u0006 מה הספק בדבר זה? \u0003אי גמר\u0004 \u0005[אם לומד]\u0006 הוא גזירה שוה \u0003\"מלא\" \"מלא\" מהתם\u0004 \u0005[משם]\u0006 מדין קומץ המנחה — \u0003היינו הך\u0004 \u0005[הרי זה אותו דבר]\u0006 ואף בין הביניים של הקטורת — פסול\u0005,\u0006 ואם לא למד כן, אם כן מה מקום לשאלה?","ומסבירים: \u0003רב פפא הכי בעי ליה\u0004 \u0005[כך נשאל לו]:\u0006 האם מה שנאמר: \u0003\"ומלא חפניו\u0004 קטורת סמים דקה \u0003והביא\u0004 מבית לפרוכת\u0003\"\u0004 (ויקרא טז, יב) בא לומר כי \"מלוא חפניו\" וכן \"והביא\" \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 לקיים, \u0003והא איכא\u0004 \u0005[והרי יש\u0006 כאן\u0005]\u0006 שהרי הביא מלוא חפניו, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003\"ולקח\" \"והביא\"\u0004 (ויקרא טז, יב) \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 לקיים, שתהיה הלקיחה וההבאה מדעתו \u0003והא ליכא\u0004 \u0005[והרי אין]\u0006 שהרי תוספת זו שבין אצבעותיו לא נתכווין לה כלל בעת לקיחתו? שאלה זו לא נפתרה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד\u0006 השאלה במקומה\u0005].\u0006","\u0003אמר רב פפא: פשיטא\u0004 \u0005[פשוט\u0006 ברור\u0005]\u0006 \u0003לי\u0004 כי \u0003מלא קומצו\u0004 יש לכתחילה לעשות \u0003כדקמצי אינשי\u0004 \u0005[כמו,\u0006 כדרך \u0005שקומצים אנשים]\u0006 כרגיל, כשראשי אצבעותיו כלפי מטה. אולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם \u0003קמץ בראשי אצבעותיו,\u0004 כלומר: שהכניס בתחילה את כף ידו לתוך הכלי ולאחר מכן הושיט את אצבעותיו וקירב באמצעותן את הסולת וכך מילא את כף ידו, \u0003מהו?\u0004 האם יפסול הדבר את הקמיצה או לא?","וכן: אם עשה זאת כשגב כף ידו מונח בתוך הכלי כלפי \u0003מטה\u0004 ובאמצעות אצבעותיו העלה את הסולת כלפי \u0003מעלה\u0004 לתוך כף ידו \u0003מהו?\u0004 וכן: אם קמץ \u0003מן הצדדין,\u0004 שהעביר את גב כף ידו בכוח הלוך וחזור על גבי הסולת שבתוך הכלי כשאצבעותיו פשוקות וכך נדחק הסולת ביניהן לתוך כף ידו, \u0003מהו\u0004 הדין? שאלות אלו לא נפתרו, ונשארו ב\u0003תיקו.\u0004","וכיוצא בזה \u0003אמר רב פפא: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי\u0004 שמה שנאמר \u0003\"מלא חפניו\" — כדחפני אינשי\u0004 \u0005[כמו שחופנים בני אדם]\u0006 ודרכם שמכניסים גב היד בכלי ומצרפים שתי ידים זו לזו, אולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא\u0004 אם \u0003חפן בראשי אצבעותיו מהו?\u0004 וכן אם חפן \u0003מלמטה למעלה מהו,\u0004 אם חפן \u0003מן הצד מהו?\u0004 ואם \u0003חפן\u0004 ביד \u0003זו\u0004 וביד \u0003זו וקרבן זו אצל זו מהו?\u0004 אף שאלות אלה לא נפתרו ונשארו ב\u0003תיקו\u0004 \u0005[תעמוד\u0006 השאלה במקומה\u0005].\u0006","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006"],["\u0003רב פפא:\u0004 מדיני הקמיצה הוא, שלאחר שקומצים את הקומץ בכלי אחד קיימת חובה להניחו בכלי שרת אחר כדי להקטירו אחר כך ובכך הוא מקדישו, ואם במקום להניחו בתחתית הכלי כראוי \u0003דבקיה לקומץ בדופניה דמנא מאי\u0004 \u0005[הדביק את הקומץ בדופן הכלי\u0006 \u0005מהו\u0006 דינו\u0005]?\u0006 וצדדי השאלה: האם רק שהקומץ יהיה ב\u0003תוך כלי בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003והא איכא\u0004 \u0005[והרי יש],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003הנחה בתוכו כתקנו בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003והא ליכא\u0004 \u0005[והרי\u0006 דבר זה \u0005אינו].\u0006 לשאלה זו לא נמצאה תשובה והושארה ב\u0003תיקו\u0004 \u0005[תעמוד\u0006 השאלה במקומה\u0005].\u0006","כעין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003מר בר רב אשי: אפכיה למנא ודבקיה\u0004 \u0005[הפך את הכלי, והדביק]\u0006 את ה\u0003קומץ בארעיתיה דמנא\u0004 \u0005[בקרקעית,\u0006 תחתית \u0005הכלי]\u0006 \u0003מהו\u0004 דינו? האם \u0003הנחה בתוכו בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 שהרי הקומץ בין דופני הכלי, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003הנחה כתקנו בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003וליכא\u0004 \u0005[ואין כאן]?\u0006 אף שאלה זו נשארה ב\u0003תיקו\u0004 \u0005[תעמוד\u0006 השאלה במקומה\u0005].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: מלא חפניו שאמרו\u0004 האם צריכים להיות \u0003מחוקות\u0004 כלומר במידה מצומצמת ומחוקה, \u0003או גדושות\u0004 במקצת? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב אשי: תא שמע\u0004 \u0005[בוא ולמד]\u0006 ממה ששנינו מפורש בברייתא: \u0003מלא חפניו שאמרו — לא מחוקות, ולא גדושות, אלא טפופות\u0004 כלומר, מליאות למדי אבל לא בגדישה.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה בזבחים (לב,א): \u0003נשפך הדם\u0004 של בהמת הקרבן \u0003על הרצפה\u0004 במקום לקבלו ישירות לכלי \u0003ואספו\u0004 משם לכלי \u0003פסול,\u0004 משום שלא נתקבל הדם כתיקונו. ואם כבר קיבל את הדם בכלי ולאחר מכן נשפך הדם \u0003מן הכלי\u0004 שקיבלו אותו בו \u0003על הרצפה ואספו\u0004 והחזירו לכלי — \u0003כשר.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 במדרש הלכה: נאמר: \u0003\"ולקח\u0004 הכהן המשיח \u0003מדם הפר\"\u0004 (ויקרא ד, ה) ומשמעו: מדם הפר שהוא \u0003דם הנפש\u0004 עצמו, שהוא הדם המקלח מבית שחיטתו ובו הנפש יוצאת \u0003ולא מדם העור\u0004 שיצא אגב חיתוך העור שלפני השחיטה, וכן \u0003לא מדם התמצית\u0004 היוצא לאחר שהפסיק הדם לקלח אחר השחיטה.","\u0003\"מדם הפר\",\u0004 דורשים כאילו היה כתוב בשינוי סדר האותיות — \u0003\"דם מהפר\" יקבלנו\u0004 — במישרין, \u0003דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך]\u0006 לומר ולדרוש כרגיל כי תוספת האות \"מ\" במילים \u0003\"מדם הפר\"\u0004 באה לצמצם את הדברים ולומר כי הכוונה היא — \u0003מדם ואפילו מקצת דם, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה: המקבל, צריך שיקבל את כל דמו של\u0004 ה\u0003פר, שנאמר: \"ואת כל דם הפר ישפך אל יסוד מזבח העלה\"\u0004 (ויקרא ד, ז) — הדגיש הכתוב לומר כי יש לשפוך את כל דמו של הפר, ודבר זה לא שייך אלא רק אם נאמר שחובה עליו לקבל את כל דמו.","\u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 יש לדרוש \u0003\"מדם הפר\" — דם מהפר יקבלנו. וקסבר\u0004 \u0005[וסבר]\u0006 חכם זה: כי \u0003גורעין\u0004 אות ממילה אחת \u0003ומוסיפין\u0004 למילה שניה \u0003ודורשין\u0004 כאילו היו הדברים יחד.","על סמך הלכה זו \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא\u0004 שאלה זו: אם \u0003נתפזר הקטורת ממלוא חפניו מהו?\u0004 האם \u0003ידו כצואר בהמה דמי\u0004 \u0005[נחשב]\u0006 ולכן הקטורת \u0003פסולה, או דילמא\u0004 \u0005[שמא]\u0006 ידו \u0003ככלי שרת דמי\u0004 \u0005[נחשבת]\u0006 ואם נפלה מן היד \u0003לא פסולה?\u0004 שאלה זו לא נמצאה לה תשובה והושארה אף היא ב\u0003תיקו\u0004 \u0005[תעמוד\u0006 השאלה במקומה\u0005].\u0006","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: חישב\u0004 מחשבה של פסול בשעת \u0003חפינת קטורת\u0004 כגון שחשב להקטירה לאחר הזמן הראוי לה \u0003מהו?\u0004 האם פוסלת מחשבה זו או לא? \u0003מי אמרינן\u0004 \u0005[האם אומרים\u0006 אנו\u0005]\u0006 כי \u0003יליף\u0004 \u0005[לומדים אנו]\u0006 בגזירה שוה \u0003\"מלא\" \"מלא\" ממנחה, מה התם\u0004 \u0005[מה שם]\u0006 במנחה \u0003מהניא\u0004 \u0005[מועילה]\u0006 \u0003בה מחשבה\u0004 לפוסלה, אף \u0003הכא נמי מהניא\u0004 \u0005[כאן גם כן מועילה]\u0006 \u0003בה מחשבה\u0004 בחפינה לפסול, \u0003או לא,\u0004 שמא אין להשוותן בכך?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שימי בר אשי לרב פפא: תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון לשאלתך, ממה ששנינו: \u0003הוסיף ר' עקיבא הקומץ\u0004 של סולת המנחה, וכן \u0003הקטורת,\u0004 או \u0003הלבונה,\u0004 או \u0003הגחלים\u0004 הצבורים בכלי אחד, שגזרו חכמים \u0003שאם נגע טבול יום במקצתן — פסל את כולן,\u0004 שמפני חיבת הקודש דנים אנו אותם כאילו היו חטיבה אחת, אף שבאמת אינם מחוברים זה לזה, אלא הם יחידות קטנות בפני עצמן, ומעיקר הדין היה צריך טבול יום לפסול רק את אותו חלק שנגע בו ולא יותר.","ומעתה נדון: \u0003קא סלקא דעתך\u0004 \u0005[עלה על דעתך],\u0006 כלומר: הנחה ראשונה היתה: \u0003מדפסל\u0004 \u0005[\u0006כיון שדברים אלה \u0005נפסלים]\u0006 במגע \u0003טבול יום —\u0004 כך \u0003פסלה\u0004 בהם \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לינה\u0004 לאחר זמנם. ומכיון ש\u0003לינה פסלה —\u0004 כך \u0003פסלה נמי\u0004 \u0005[גם כן]\u0006 \u0003מחשבה.\u0004 ועל כן, כיון שהקטורת נחשבת כמו הסולת לגבי טומאה — אף לגבי מחשבה נפסלת היא כמותה.","עוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא\u0004 שאלה זו:"],["\u0003חישב\u0004 מחשבת פסול בשעת \u0003חתיית גחלים מהו?\u0004 האם פוסלת המחשבה את הקטורת. ויסוד השאלה הוא: \u0003מכשירי מצוה\u0004 האם \u0003כמצוה דמו\u0004 \u0005[נחשבים],\u0006 ולכן אף כשהוא חותה את הגחלים, שהם רק מכשירים למצות הקטורת, הרי זו כהקטרה עצמה ופוסל בה, \u0003או לא?\u0004 שאלה זו לא נמצאה לה תשובה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד\u0006 השאלה במקומה\u0005].\u0006","\u0003בעי מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרב ששת\u0004 שאלה זו: \u0003הולכה\u0004 של דם ביד \u0003שמאל מהו\u0004 האם כשרה היא, או שדינה כקבלה וזריקה שחובה לעשותן דווקא ביד ימין? \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת\u0004 לשואלים: כבר \u0003תניתוה\u0004 \u0005[שניתם אותה].\u0006 כלומר: יש תשובה לדבר ממקור ידוע. שהרי שנינו בענין דומה: \u0003נטל את המחתה בימינו ואת הכף בשמאלו,\u0004 הרי, אף שמוליך את הכף למקום העבודה ביד שמאל, זוהי דרך הכשרו.","ושואלים: \u0003ונפשוט להו מהא דתנן\u0004 \u0005[ושיפתור להם\u0006 את הבעיה \u0005מזו ששנינו\u0006 במשנה\u0005]:\u0006 שהכהן שזכה בהעלאת הראש והרגל לכבש, היה מעלה את \u0003הרגל של ימין\u0004 ביד \u0003שמאל ובית עורה\u0004 השלם צריך שיהיה כלפי \u0003חוץ\u0004 ואילו בית שחיטתה שהוא המקום החתוך צריך להיות כלפי הכהן, הרי שאפשר להוליך ביד שמאל!","ודוחים: \u0003אי מהתם הוה אמינא\u0004 \u0005[אם\u0006 היה מוכיח \u0005משם, הייתי אומר]\u0006 בדחיה: כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003הולכה\u0004 שהרי היא \u0003לא מעכבא\u0004 \u0005[מעכבת]\u0006 את ה\u0003כפרה,\u0004 שהרי גם אם לא הועלו האיברים למזבח כבר היתה הכפרה בזריקת הדם, שהרי אף אם לא הוקטרו איברי הקרבן כלל — כשר, \u0003אבל הולכה\u0004 זכו \u0003דמעכבא\u0004 \u0005[שמעכבת]\u0006 את ה\u0003כפרה,\u0004 כגון הולכת הדם למזבח — \u0003לא,\u0004 ויש לעשותה דווקא בימין, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 ממקור זה, שמוליך את הכף לצורך עיקר המצוה, ובכל זאת כשירה בשמאל."],["\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 מן הברייתא: \u0003זר\u0004 שאינו כהן, \u0003ואונן\u0004 (אבל ביום אבלו הראשון), \u0003שיכור, ובעל מום,\u0004 כל אלו \u0003בקבלה ובהולכה ובזריקה\u0004 של הדם — \u0003פסול. וכן\u0004 פסול העושה זאת כשהוא \u0003יושב, וכן\u0004 אם עושה אחת מעבודות אלו ביד \u0003שמאל — פסול,\u0004 והרי הדברים סותרים את דעת רב ששת! ומסכמים: הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה],\u0006 ונדחו איפוא דברי רב ששת.","ותוהים על רב ששת: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב ששת הוא דאותבה\u0004 \u0005[שהקשה אותה]\u0006 והשתמש בברייתא זו, שהרי \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת לאמוריה\u0004 \u0005[למתורגמנו]\u0006 של \u0003רב חסדא בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003מרב חסדא\u0004 שאלה זו: \u0003הולכה\u0004 של הדם \u0003בזר מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כשירה, ומקרא מסייעני,\u0004 שהרי נאמר: \u0003\"וישחטו הפסח ויזרקו הכהנים מידם והלוים מפשיטים\"\u0004 (דברי הימים ב' לה, יא), משמע שהכהנים לקחו את הדם מידי הלויים, ומסתבר שהם שהוליכו את הדם ממקום השחיטה למקום הזריקה!","\u0003ומותיב\u0004 \u0005[והקשה]\u0006 \u0003רב ששת\u0004 מברייתא זו: \u0003זר ואונן, שיכור ובעל מום,\u0004 כל אלו אינם \u0003בקבלה ובהולכה ובזריקה\u0004 ואם בכל זאת עשו אחת מהעבודות הללו \u0003— פסול, וכן\u0004 אם עשה אחת מעבודות אלו כשהוא \u0003יושב וכן\u0004 ביד \u0003שמאל — פסול.\u0004 משמע שאי אפשר שתהא הולכה בזר! ומתוך שהקשה ר' ששת מברייתא זו, ודאי שידע אותה ואיך אם כן פסק הוא עצמו הלכה בניגוד לברייתא זו?","ומשיבים: \u0003בתר דשמעה\u0004 \u0005[אחר ששמע אותה]\u0006 כשהקשו ממנה לשיטתו \u0003הדר אותבה\u0004 \u0005[חזר והקשה ממנה],\u0006 שבתחילה גם רב ששת לא ידע אותה ולכן פסק בניגוד לה, וכששמע — הסתמך עליה כדי להקשות על דברי רב חסדא. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב חסדא קרא קאמר\u0004 \u0005[כתוב אמר]\u0006 והמקרא מסייעו, ואם כן כיצד יכולה הברייתא לחלוק על המקרא? ומשיבים: אין הכוונה שהלויים הוליכו את הדם. אלא \u0003דעבוד מעשה\u0004 \u0005[שעשו מעשה]\u0006 \u0003איצטבא,\u0004 שרק החזיקו את מזרקי הדם בידם, אבל לא הוליכום ממקומם.","שוב חוזרים אנו לבירור ענין החפינה וצורות החפינה הכשירה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: חפן חבירו, ונתן לתוך חפניו\u0004 של הכהן \u0003מהו?\u0004 וצדדי השאלה: האם \u0003\"מלא חפניו\" בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003והא איכא\u0004 \u0005[והרי יש]!\u0006 שהרי בסופו של דבר חופניו מלאים, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003\"ולקח\" \"והביא\" בעינן\u0004 \u0005[צריכים אנו]?\u0006 שהכהן עצמו יקח ויחפון, \u0003והא ליכא\u0004 \u0005[וזה איננו]!\u0006 אף שאלה זו לא נמצאה לה תשובה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד\u0006 השאלה במקומה\u0005].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יהושע בן לוי: חפן\u0004 הכהן הגדול \u0003ומת, מהו שיכנס\u0004 כהן גדול \u0003אחר\u0004 שמשמש תחתיו \u0003בחפינתו?\u0004 האם יכול השני להכניס את הקטורת שחפן הכהן הראשון, או שמא צריך להתחיל מתחילה? \u0003אמר ר' חנינא\u0004 לתלמידיו בהתפעלות: \u0003בא וראה\u0004 שהדור האחרון זכה לשאול שאלה חמורה וקשה כ\u0003שאלת הראשונים.\u0004 שאף אני, ר' חנינא, זכיתי כבר לשאול שאלה זו של ר' יהושע בן לוי שהוא מן הראשונים.","מתחילה מבררים את הביטוי: \u0003למימרא\u0004 \u0005[האם נאמר\u0006 ונלמד מכאן\u0005]\u0006 כי \u0003ר' יהושע בן לוי קשיש\u0004 \u0005[זקן]\u0006 היה מר' חנינא, שר' חנינא קורא לו ראשון? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יהושע בן לוי: לי התיר ר' חנינא לשתות שחליים\u0004 (מין ירק) \u0003בשבת\u0004 לצורך רפואה, משמע שר' חנינא היה גדול ממנו!","אגב הזכרת הענין תוהים: \u0003לשתות, פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 ומדוע אסור יהיה לשתות? \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל האוכלין,\u0004 כלומר: דברים הראויים לאכילה — \u0003אוכל אדם,\u0004 גם אם הוא מתכוין בכך \u0003לרפואה. וכל המשקין\u0004 הראויין לשתיה \u0003שותה,\u0004 גם אם מועילים \u0003לרפואה,\u0004 ולא גזרו עליהם משום איסור רפואה בשבת!","\u0003אלא,\u0004 השאלה היתה: האם מותר \u0003לשחוק ולשתות שחליים בשבת.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה\u0006 הדבר\u0005]?\u0006 \u0003אי דאיכא סכנתא\u0004 \u0005[אם יש סכנה\u0006 בדבר\u0005]\u0006 וזו היא התרופה לכך — \u0003משרא שרי\u0004 \u0005[היתר\u0006 גמור הרי \u0005הותר].\u0006 \u0003ואי דליכא סכנתא\u0004 \u0005[ואם אין סכנה] —\u0006 \u0003מיסר אסיר\u0004 \u0005[אסור\u0006 הדבר\u0005],\u0006 שהרי זו מלאכה אסורה ממש! ומשיבים: \u0003לעולם\u0004 יש לפרש \u0003דאיכא סכנתא\u0004 \u0005[שהיתה\u0006 בכך \u0005סכנה]\u0006 \u0003והכי מבעיא ליה\u0004 \u0005[וזה שנסתפק לו]:\u0006 \u0003מי מסיא, דניחול עלייהו שבתא\u0004 \u0005[האם מרפא\u0006 משקה זה שראוי \u0005לחלל עליו את השבת],\u0006 \u0003או לא מסיא\u0004 \u0005[מרפא]\u0006 \u0003ולא ניחול עלייהו שבתא\u0004 \u0005[יחללו עליו את השבת].\u0006","ושואלים: אם לא היתה זו שאלה הלכתית, אלא בעיה רפואית, \u0003ומאי שנא\u0004 \u0005[ובמה שונה],\u0006 מדוע בחר דווקא ב\u0003ר' חנינא\u0004 לשאול אותו? ומסבירים: \u0003משום\u0004 ש\u0003בקי ברפואות הוא.\u0004 ש\u0003אמר ר' חנינא: מעולם לא שאלני אדם על מכת פרדה לבנה וחיה.\u0004 הרי שר' חנינא היה נשאל שאלות רפואיות שונות.","על עצם הדבר תוהים: \u0003והא קא חזינן דחיי\u0004 \u0005[והרי אנו רואים\u0006 שאדם נבעט על ידי פרדה \u0005וחי]!\u0006 ומתרצים: \u0003אימא: וחיית\u0004 \u0005[אמור: וחיתה\u0006 המכה\u0005],\u0006 כלומר: המכה אינה מתרפאה לעולם. ומקשים: \u0003והא קא חזינן דמיתסי\u0004 \u0005[והרי רואים אנו שהיא מתרפא]!\u0006 ומשיבים: \u0003בסומקן אינהו וחיורן ריש כרעיהו קאמרינן\u0004 \u0005[\u0006כשהפרדות \u0005הן אדומות, ולבנים\u0006 רק \u0005ראשי הרגלים שלהם, אומרים אנו],\u0006 שפרדות אלה מכתן קשה ביותר, ואין להן רפואה.","\u0003מכל מקום שמע מינה\u0004 \u0005[למד מכאן]\u0006 מן הענין ש\u0003ר' חנינא קשיש\u0004 \u0005[זקן]\u0006 היה מר' יהושע בן לוי, ומדוע התבטא על דבריו בלשון \"שאלת הראשונים\"? \u0003אלא\u0004 מסבירים כי \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את דבריו: \u0003שאלתן כשאילה של ראשונים.\u0004 שלא נתכוין לומר בוא וראה כמה יפה שואלים הראשונים, אלא: ראה שאלה זו שהיא חמורה וקשה כשאלותיהם של הראשונים.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' חנינא הכי\u0004 \u0005[כך]\u0006 ששאלה זו חמורה וקשה להשיב עליה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חנינא:\u0004 נאמר: \"בזאת יבא אהרן אל הקודש \u0003בפר\u0004 בן בקר\" (ויקרא טז, ג), ומדייקים: בפר \u0003ולא בדמו של פר.\u0004 כלומר: הכהן הגדול צריך לשחוט בעצמו פר החטאת משלו ואם שחט כהן אחד וקיבל את הדם ומת, לא יבוא בדם פר כהן אחר המשמש תחתיו, אלא צריך להביא פר אחר, לשוחטו, לקבל דמו ולהביאו לפנים.","וכן \u0003אמר ר' חנינא: קטורת שחפנה קודם שחיטת הפר — לא עשה ולא כלום,\u0004 שצריכה החפינה להיות לאחר שחיטה. ואם כן, לשיטת ר' חנינא, לא יתכן כלל שכהן אחד יכנס בחפינתו של חבירו, שהרי אם מת הכהן הראשון לאחר החפינה, ודאי שעדיין לא הכניס את דם הפר שקיבל ולכך אין שחיטתו מועילה לממלא מקומו, וחייב הוא לחזור על כל סדר העבודה, משחיטת הפר והלאה!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 ר' חנינא: \u0003מדקא מיבעיא ליה\u0004 \u0005[מכיון שהסתפקה לו\u0006 לר' יהושע בן לוי שאלה זו\u0005],\u0006 \u0003הא מכלל\u0004 \u0005[הרי]\u0006 מכלל הדברים אתה לומד \u0003דקסבר\u0004 \u0005[שהוא סבר]\u0006 כי מה שאמרו \u0003\"בפר\"\u0004 כוונתו: \u0003ואפילו בדמו של פר.\u0004 שהכהן השני אינו צריך לחזור ולשחוט פר חדש. \u0003ולמאי דסבירא ליה\u0004 \u0005[ולפי מה שהוא סבור] —\u0006 \u0003שאילתו כשאילת הראשונים,\u0004 שאף שלדעת ר' חנינא אין מקום לשאלה זו, הרי לשיטת ר' יהושע בן לוי שאלה זו שאלה חמורה ויפה.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על שאלה זו, ומה אכן הדין בחפן ומת, האם יכול כהן אחר להסתפק בחפינה זו, או שמא צריך חפינה מחודשת? \u0003אמר רב פפא:\u0004 פתרון שאלה זו תלוי בבעיה אחרת \u0003אי\u0004 \u0005[אם]\u0006 נאמר ש\u0003חופן\u0004 הכהן הגדול כשלוקח את הקטורת ממחתת הקטורת ו\u0003חוזר וחופן\u0004 פעם שניה גם בקודש הקדשים — הרי אז \u0003חבירו נכנס\u0004 ודי לו \u0003בחפינתו\u0004 של כהן ראשון. ומדוע — \u0003דהא מקימא\u0004 \u0005[שהרי מתקיימת]\u0006 מצות \u0003חפינה. אי\u0004 \u0005[אם]\u0006 \u0003אין חופן וחוזר וחופן — תבעי לך\u0004 \u0005[תשאל לך]\u0006 שאלה זו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא: אדרבה\u0004 (להיפך), \u0003אי\u0004 \u0005[אם]\u0006 \u0003חופן וחוזר וחופן — לא יכנס אחר בחפינתו,\u0004 ומדוע — שהרי \u0003אי אפשר\u0004 שבחפינה מחודשת זו \u0003לא יחסר ושלא יותיר\u0004 משיעור החפינה של הראשון. ונמצא שלא חפן כראוי. אולם \u0003אי\u0004 \u0005[אם]\u0006 \u0003אין חופן וחוזר וחופן\u0004 — אז \u0003תיבעי לך\u0004 \u0005[תשאל לך]\u0006 שאלה זו, שהרי נתקיימה כבר מצות חפינה בכהן, והכהן השני אינו צריך אלא להניח את הקטורת על הגחלים.","ומסבירים את רקע הבעיה \u0003דאיבעיא להו\u0004 \u0005[שנשאלה להם]\u0006 ללומדים שאלה זו: האם הכהן הגדול \u0003חופן\u0004 מן הקטורת פעם אחת ו\u0003חוזר וחופן\u0004 פעם שניה בקודש הקדשים, \u0003או לא?\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון לאותה שאלה, ששנינו: \u0003כך היתה מידתה\u0004 של הכף. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003כשם שמדתה מבחוץ כך מדתה מבפנים,\u0004 לומר שאין צורך לחזור ולחפון, אלא זו היא מידתה הקבועה, וממנה היה שופך על המחתה!","ודוחים: \u0003לא\u0004 כך יש להבין, \u0003דילמא\u0004 \u0005[שמא]\u0006 הכוונה היא \u0003שאם רצה לעשות מדה\u0004 לחפניו \u0003עושה,\u0004 וחופן על ידי כלי, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003שלא יחסר ושלא יותיר\u0004 ממידה זו שחפן תחילה. ואם כן, אין מכאן איפוא כל הוכחה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בא ושמע]\u0006 פתרון לשאלה זו מברייתא:"],["\u0003כיצד הוא עושה\u0004 בבית קודש הקדשים כשצריך להניח את הקטורת על הגחלים ולשם כך צריך לחפון מן הבזך וליתן לתוך חפניו? \u0003אוחז את\u0004 ראש \u0003הבזך\u0004 (הכלי) של קטורת \u0003בראש אצבעותיו\u0004 לאחר שהניח את המחתה בארץ, \u0003ויש אומרים\u0004 כי אוחזו \u0003בשיניו,\u0004 וידו של הבזך מונח כלפי בין זרועותיו \u0003ומעלה\u0004 ודוחף אותו \u0003בגודלו\u0004 לצד גופו מעט מעט \u0003עד שמגעת\u0004 (הבזך) \u0003לבין אצילי ידיו\u0004 (מרפקו), ובהם יכול להסתייע כדי להופכו, \u0003וחוזר ומחזירה לתוך חפניו,\u0004 ואחר כך שופכה מתוך חפניו למחתת הגחלים, \u0003וצוברה\u0004 לקטורת על גבי הגחלים בערימה, \u0003כדי שיהא עשנה שוהה לבוא. ויש אומרים:\u0004 לא כן, אלא אדרבא היה \u0003מפזרה, כדי שיהא עשנה ממהרת לבוא.\u0004","ועבודה \u0003זו\u0004 של חפינת הקטורת \u0003היא עבודה קשה שבמקדש.\u0004 על לשון זו שואלים: \u0003זו היא ותו לא\u0004 \u0005[ולא עוד]?\u0006 \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 עבודת ה\u0003מליקה\u0004 שנאמר שהיא קשה! \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 עבודת ה\u0003קמיצה\u0004 הקשה! \u0003אלא:\u0004 יש לומר כי \u0003זו היא עבודה קשה מעבודות קשות שבמקדש.\u0004 על כל פנים \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003חופן וחוזר וחופן.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003שחט\u0004 הכהן הגדול את הפר \u0003ומת, מה הוא שיכנס\u0004 כהן גדול \u0003אחר\u0004 לפני ולפנים \u0003בדמו\u0004 של הפר ששחט הראשון? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי מה שנאמר: \"בזאת יבא אהרן אל הקודש \u0003בפר\u0004 בן בקר לחטאת\" (ויקרא טז, ג), כוונתו — כי אין הכהן נכנס אלא בדם הפר, אבל אין קפידה מיוחדת שיהיה זה דווקא דמו של הפר שנשחט על ידו ויתכן כי אין כל חיסרון אם הוא נכנס \u0003אפילו בדמו של פר\u0004 ששחטו אחר, \u0003או דילמא\u0004 \u0005[שמא]\u0006 יש לדייק: \u0003\"בפר\" — ולא בדמו של פר.\u0004","ונחלקו חכמים בדבר: \u0003ר' חנינא אומר: — \"בפר\" ולא בדמו של פר,\u0004 ולכן עליו לשחוט פר חדש ואינו נכנס אלא בדמו של פר זה \u0003וריש לקיש אמר: \"בפר\" — ואפילו בדמו של פר.\u0004 כיוצא בכך \u0003אמר ר' אמי: \"בפר\" — ולא בדמו של פר, ר' יצחק אמר: \"בפר\" — ואפילו בדמו של פר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אמי לר' יצחק נפחא\u0004 \u0005[הנפח]:\u0006 שנינו בהלכות קרבן פסח, שכדי להצטרף לחבורה המקריבה יחד קרבן אחד \u0003נמנין\u0004 בני חבורה עליו, וכן \u0003מושכין ידיהן ממנו\u0004 ועוברים לחבורה אחרת, \u0003עד שישחט\u0004 הקרבן. \u0003ואם איתא\u0004 \u0005[יש\u0006 ממש\u0005]\u0006 בדבריך, שגם דמו של הקרבן נחשב עדיין כקרבן, הרי \u0003\"עד שיזרוק\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 ומדוע אין יכולים להמשיך ולהמנות וכן למשוך ידיהם ממנו עד אז, שהרי לדעתך דם הקרבן והקרבן דבר אחד הם!","ענה לו: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ואם ימעט הבית \u0003מהיות משה\u0004 ולקח הוא ושכנו הקרוב אל ביתו\" (שמות יב, ד) שאנו דורשים \"מהיות משה\" — \u0003מחיותה\u0004 \u0005[מחיותו]\u0006 של ה\u0003שה,\u0004 לומר: כל זמן שהשה חי מותר להמנות ולהמשך ממנו. ואם כן, גזירת הכתוב היא בפסח, וביום הכיפורים לא נאמרה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003מר זוטרא,\u0004 שנינו: \u0003אין פודין\u0004 פטר חמור אלא בשה \u0003לא בעגל ולא בחיה, ולא\u0004 בכבשה \u0003שחוטה, ולא בטריפה, ולא בכלאים\u0004 (של כבש ועז) \u0003ולא בכוי\u0004 (שהוא ספק חיה ספק בהמה) \u0003אלא בשה.\u0004 משמע שבהמה שחוטה שוב אינה קרויה שה! ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דיליף\u0004 \u0005[שהוא לומד]\u0006 בגזירה שוה \u0003\"שה\" \"שה\" מפסח,\u0004 ולכן האמור בדיני פסח שייך גם בדיני פטר חמור.","ושואלים: אם כן, \u0003אי\u0004 \u0005[אם]\u0006 \u0003מה להלן\u0004 בפסח צריך שיהא הקרבן \u0003זכר, תם\u0004 ממום, \u0003ובן שנה, אף כאן\u0004 בפדיון פטר חמור יצטרכו שיהא זה \u0003זכר\u0004 דווקא, \u0003תם\u0004 בלי מום, \u0003ובן שנה? תלמוד לומר:\u0004 \"וכל פטר חמור תפדה בשה ואם לא תפדה וערפתו\", שכפל דבריו לומר פעמים לשון \u0003\"תפדה\" \"תפדה\"\u0004 (שמות יג, יג) ובכך \u0003ריבה\u0004 הכתוב שפדיון כשר בכל און שיהיה, ולא דווקא כעין קרבן פסח.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 אומר אתה ש\u0003\"תפדה\" \"תפדה\" ריבה — אפילו כולהו נמי\u0004 \u0005[כולם גם כן]\u0006 עגל, חיה, שחוטה וכיוצא! ומשיבים: \u0003אם כן,\u0004 הגזירה השוה \u0003\"שה\" מאי אהני ליה\u0004 \u0005[מה הועילה לו]?\u0006 אלא ודאי יש לרבות ויש למעט, הכל לפי הענין, ומכל מקום לענין יום הכיפורים אין להוכיח מכאן."]]};
